                    </div>
                    <div class="title">
                        1. उद्यमेन हि सिध्यन्ति
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम् </td>
                            <td>उद्यमेन हि सिध्यन्ति कार्याणि न मनोरथैः ।<br> न हि सुप्तस्य सिंहस्य प्रविशन्ति मुखे मृगाः ॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>उद्यमेन हि सिध्यन्ति कार्याणि न मनोरथैः । न हि सुप्तस्य सिंहस्य प्रविशन्ति मुखे मृगाः ॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>कार्याणि उद्यमेन हि सिध्यन्ति। मनोरथैः न (सिध्यन्ति) । मृगाः सुप्तस्य सिंहस्य मुखे न हि प्रविशन्ति॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>कार्याणि = सङ्कल्पितानि आचरणीयानि; tasks, work;<br> उद्यमेन = प्रयत्नेन; by effort, trying;<br> हि = नूनं; indeed;<br> सिध्यन्ति = सम्पद्यन्ते; get accomplished, done, (bear fruit);<br> मनोरथैः = कामनाभिः; by desires, fancies;<br> न (सिध्यन्ति) = पूर्णानि न भवन्ति; (are) not (accomplished);<br> मृगाः = जन्तवः, पशुविशेषः; deer, or animals in general;<br> सुप्तस्य = शयनं कुर्वतः; of that which is slept;<br> सिंहस्य = मृगराजस्य; of the lion;<br> मुखे = आस्ये; in the mouth;<br> न हि प्रविशन्ति = न कदापि प्रवेशं कुर्वन्ति; do not enter</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>प्रयतनेनैव कर्माणि सफलीभवन्ति, न कदापि मानसिकीच्छया। यथा शयानस्य मृगराजस्य मुखे जन्तवः आगत्य स्वयं आहारं न भवन्ति, तस्य मृगयानन्तरमेव वशीकृत्य हत्वैव आहारेण परिवर्तन्ते, तथैव अत्रापि। <br>Tasks can be accomplished by strong efforts; not merely by desiring (their completion).Animals do not enter a sleeping lion's mouth on their own.</td>
                        </tr><tr class="vyakyaa">
                            <td style="width: 90px">वाक्याभ्यासः </td>
                            <td>श्लोकपदान्युपयुज्य- १. उद्यमेन कार्याणि सिद्ध्यन्ति। २. कार्याणि मनोरथैः न सिद्ध्यन्ति। ३. सिंहस्य मुखे मृगाःन प्रविशन्ति। 
                            <br>पर्यायपदान्युपयुज्य- १. सङ्कल्पितानिआचरणीयानिप्रयत्नेन न सम्पद्यन्ते। २.करणीयानि कार्याणि कामनाभिःपूर्णानि न भवन्ति। ३. जन्तवःशयनं कुर्वतःमृगराजस्यआस्यान्तः न गच्छन्ति। </td>
                            </tr>
                            
                        <tr class="prasnaa">
                            <td style="width: 90px">प्रश्नाः </td>
                            <td>१. कार्याणिकथंसिद्ध्यन्ति? <br>२. मृगाः कुत्र न प्रविशन्ति? <br>३. -------कार्याणि न सिद्ध्यन्ति। <br>४. मनोरथैः इति शब्दस्य पदविश्लेषणं वदत? <br>५. कार्याणि इति शब्दस्य किं लिङ्गम्? <br>६. सुप्तस्य इति कस्य विशेषणम्?</td>
                        </tr>
                        

                    </table>
                </div>
                    
                <div id="2" class="total">
                    <div>
                        <button id="moolamsmall2" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('moolam', '2')">मूलम्</button>
                        <button id="padasmall2" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '2')">पदविभागः</button>
                        <button id="anvayasmall2" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '2')">अन्वयः</button>
                        <button id="pratismall2" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '2')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall2" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '2')">तात्पर्यम्</button>
                        <button id="vyakyaasmall2" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('vyakyaa', '2')">वाक्याभ्यासः</button>
                        <button id="prasnaasmall2" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prasnaa', '2')">प्रश्नाः</button>
                    </div>
                    <div class="title">
                        2. गते शोकं न कुर्वीत
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम् </td>
                            <td>गते शोकं न कुर्वीत भविष्यं नैव चिन्तयेत्।<br> वर्तमानेषु कालेषु वर्तयन्ति विचक्षणाः॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>सुलभः</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>गते शोकं न कुर्वीत। नैव भविष्यं चिन्तयेत्। विचक्षणाः वर्तमानेषु कालेषु वर्तयन्ति ।</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>गते = अतीते काले; In the past;<br> शोकं = दुःखं; (obj.) Sorrow, grief, distress, affliction, lamentation, wailing, deep anguish;<br> न कुर्वीत = न करणीयम्; Should not do;<br> नैव = न एव; Never, [neither (here)];<br> भविष्यं = अनागतकालं; (obj.) The future, futurity, Imminent, impending;<br> चिन्तयेत् = चिन्तनीयम्; Should not think, consider, reflect, ponder over;<br> विचक्षणाः = विवेकशीलिनः; learned men, wise men;<br> वर्तमानेषु = प्रचलितेषु; In the contemporary, the present time;<br> कालेषु = समयेषु; in the times;<br> वर्तयन्ति = प्रवर्तन्ते; They be, exist, abide, remain, subsist, stay</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>कदापि गतकालमाश्रित्यखिन्नैः न भवितव्यम्। भविष्यद्विषये चिन्ताकुलैःनभवितव्यम्। विवेकवन्तः प्रचलितेषु कालेषु प्रवर्तन्ते (कार्येषु दृष्टिं संस्थाप्य यत्करणीयं तत् कुर्वन्ति)। <br>One should not brood over past; nor worry about future. The wise men always remain in present times.</td>
                        </tr>
                        <tr class="prasnaa">
                            <td style="width: 90px">प्रश्नाः </td>
                            <td>१.कुत्रशोकंनकुर्वीत?  <br>२.विचक्षणाः कुत्र वर्तयन्ति? <br>३.------नैव चिन्तयेत्। (रिक्तस्थानं पूरयत।) <br>४.‘वर्तमान’ शब्दस्यपदविश्लेषणं वदत? <br>५.‘विचक्षणाः’ इत्यस्य पदविश्लेषणं वदत?</td>
                        </tr>
                        

                    </table>
                </div>
                    
                <div id="3" class="total">
                    <div>
                        <button id="moolamsmall3" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('moolam', '3')">मूलम्</button>
                        <button id="padasmall3" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '3')">पदविभागः</button>
                        <button id="anvayasmall3" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '3')">अन्वयः</button>
                        <button id="pratismall3" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '3')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall3" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '3')">तात्पर्यम्</button>
                        <button id="vyakyaasmall3" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('vyakyaa', '3')">वाक्याभ्यासः</button>
                        <button id="prasnaasmall3" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prasnaa', '3')">प्रश्नाः</button>
                    </div>
                    <div class="title">
                        3. वरंपर्वतदुर्गेषु
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम् </td>
                            <td>वरं पर्वतदुर्गेषु भ्रान्तं वनचरैः सह।<br> न मूर्खजनसम्पर्कः सुरेन्द्रभवनेष्वपि॥-भर्तृहरेः नीतिशतकम्</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>वरं पर्वत-दुर्गेषु भ्रान्तं वनचरैः सह न मूर्ख-जन-सम्पर्कः सुरेन्द्र-भवनेषु अपि॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>पर्वत-दुर्गेषु वनचरैः सह भ्रान्तं वरम् । मूर्ख-जन-सम्पर्कः सुरेन्द्र-भवनेषु अपि न (वरम्)॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>पर्वतदुर्गेषु = दुर्गमपर्वतेषु; In mountains, rocks;<br> वनचरैः सह = वने ये चरन्ति, निवसन्ति तैः साकं; along with wild animals/people;<br> भ्रान्तं = भ्रमणं; lost;<br> वरं = श्रेष्ठम्; better;<br> मूर्खजन-सम्पर्कः = अर्धज्ञैः सह मेलनं; contact of fools;<br> सुरेन्द्रभवनेषु = इन्द्रस्य आवासेषु; in the palaces of Indra;<br> अपि न = कदापि न; also no.</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>गन्तुमशक्येषु पर्वतप्रान्तेषु लक्ष्यरहितं भ्रमणं अपि श्रेष्ठम् इव दृश्यते। वनचारिभिः पशुभिः क्रूरमृगैः सार्धम्अटनमपि वरम्। किन्तु अर्धज्ञैः सह परिचयः, साङ्गत्यं वा महेन्द्रस्य सौधेष्वपि अनर्थदायकम्। <br>Being lost in mountains, caves and other deserted places, or with wild animals, wild people seem better than being with fools. We cannot be with them even if it were in heaven.</td>
                        </tr>
                        <tr class="prasnaa">
                            <td style="width: 90px">प्रश्नाः </td>
                            <td>१. कुत्रभ्रान्तंवरम्? <br>२.सुरेन्द्रभवनेष्वपि किं न भवतु? <br>३. ‘वनचरैः सह’ इत्यत्र केनपाणिनि-सूत्रेण तृतीयाविभक्तिः? <br>४. ‘मूर्खजनसम्पर्कः’इत्यत्र कः समसः? <br>५. ‘भवनेष्वपि’ इत्यत्र सन्धिः (साधुविकल्पं चिनुत) = क. भवने-ष्वपि ख. भवनेष्व-पि ग. भवनेषु-अपि  <br>६. न------सम्पर्कः। (रिक्तस्थानं पूरयतु)</td>
                        </tr>
                        

                    </table>
                </div>
                    
                <div id="4" class="total">
