                        <button id="padasmall4" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '4')">पदविभागः</button>
                        <button id="anvayasmall4" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '4')">अन्वयः</button>
