                        <button id="vyakyaasmall4" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('vyakyaa', '4')">वाक्याभ्यासः</button>
                        <button id="prasnaasmall4" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prasnaa', '4')">प्रश्नाः</button>
                    </div>
                    <div class="title">
                        4. विद्या विवादाय
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम् </td>
                            <td>विद्या विवादाय धनं मदाय शक्तिः परेषां परिपीडनाय।<br>  खलस्य साधोर्विपरीतमेतत् ज्ञानाय दानाय च रक्षणाय ॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>विद्या विवादाय धनं मदाय शक्तिः परेषां परिपीडनाय। खलस्य साधोः विपरीतम् एतत् ज्ञानाय दानाय च रक्षणाय ॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>खलस्य विद्या विवादाय, धनं मदाय, शक्तिः परेषां परिपीडनाय (च भवति)। एतत् साधोः विपरीतम्। (विद्या) ज्ञानाय (धनं) दानाय (शक्तिः परेषां) रक्षणाय च (भवति)॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>खलस्य = दुष्टस्य; of crooked man, wicked man;<br> विद्या = विद्वत्त्वं, अधिगमः; education, knowledge;<br> विवादाय = वादप्रतिवादनाय; argument;<br> धनं = अर्थः; wealth, money;<br> मदाय = गर्वोद्धतये, दम्भाय; for pride, arrogance, conceit;<br> शक्तिः = शारीरकं बलं; power, strength;<br> परेषां = अन्येषां; of others;<br> परिपीडनाय = क्लेशनाय; for inflicting pain upon;<br> एतत् = इदं; this;<br> साधोः = सज्जनस्य; of good man;<br> विपरीतम् = विरुद्धं; opposite;<br> ज्ञानाय = ज्ञानार्जनाय; for wisdom;<br> दानाय = परस्मै प्रदानाय; for charity;<br> च = च; and;<br> रक्षणाय = पालनाय; for protection</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>दुष्टानां विद्या विवादाय भवति। धनं च दम्भाय भवति। शक्तिः इतरेषां पीडनार्थं भवति। अस्य विरुद्धं, सज्जनस्य विद्या ज्ञानवर्धनाय, धनं च परेभ्यः दातुं, शारीरकशक्तिः च अन्येषां साहाय्यार्थं भवति। <br>A wicked man uses his education for argument, money to be arrogant and strength to hurt others. In contrast a virtuous person uses the same for acquiring new knowledge, charity and protecting respectively.</td>
                        </tr>
                        <tr class="prasnaa">
                            <td style="width: 90px">प्रश्नाः </td>
                            <td>१. खलस्यविद्याकुतोभवति? <br>२. साधोः किं ज्ञानाय भवति? <br>३. शक्तिः परेषां------। (रिक्तस्थानं पूरयत) <br>४. ‘साधोर्विपरीतम्’इत्यत्र सन्धिविच्छेदनं कुरुत। <br>५. साधुजनः शक्तिं कुतः उपयुनक्ति? (साधुविकल्पं चिनुत) क. ज्ञानाय ख. दानाय ग. रक्षणाय <br>६.‘शक्तिः’ इत्यस्य किं व्याकरणम्?</td>
                        </tr>
                        

                    </table>
                </div>
                    
