                        <button id="vyakyaasmall5" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('vyakyaa', '5')">वाक्याभ्यासः</button>
                        <button id="prasnaasmall5" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prasnaa', '5')">प्रश्नाः</button>
                    </div>
                    <div class="title">
                        5.छायामन्यस्य कुर्वन्ति
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम् </td>
                            <td>छायामन्यस्य कुर्वन्ति तिष्ठन्ति स्वयमातपे ।<br>  फलान्यपि परार्थाय वृक्षाः सत्पुरुषा इव ॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>छायाम् अन्यस्य कुर्वन्ति तिष्ठन्ति स्वयम् आतपे। फलानि अपि परार्थाय वृक्षाः सत्पुरुषा इव ॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>अन्यस्य छायाम् कुर्वन्ति। स्वयम् आतपे तिष्ठन्ति ।फलानि अपि परार्थाय (यच्छन्ति)। वृक्षाः सत्पुरुषा इव (वर्तन्ते) ॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>वृक्षाः = पादपाः; Trees;<br> अन्यस्य = इतरस्य; for others;<br> छायाम्कुर्वन्ति = आतपाद् रक्षणस्थानं कल्पयन्ति; shade (they) do;<br> स्वयम् = आत्मना; themselves;<br> आतपे = सूर्यप्रकाशे; in heat, under Sun;<br> तिष्ठन्ति = स्थिताः सन्ति; (They) stand;<br> फलानि = वृक्षजातानि खाद्यानि; fruits;<br> अपि = अपि; also;<br> परार्थाय = इतरेभ्यः; for others;<br> सत्पुरुषाः = सज्जनाः; Noble persons;<br> इव = वत्; like, same as</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>जनेभ्यः आतपात् छायां ददति। स्वयं च आतपे तिष्ठन्ति। फलानि अपि अन्येभ्यः यच्छन्ति। वृक्षाः (आचरणे) च सत्पुरुषसमानाः। <br>Trees, like Noble persons, provide shade to others but themselves stand in the heat of the Sun. They provide their fruits for the benefit of others.</td>
                        </tr>
                        <tr class="prasnaa">
                            <td style="width: 90px">प्रश्नाः </td>
                            <td>१. छायांकेकुर्वन्ति? <br>२. स्वयं कुत्र तिष्ठन्ति? <br>३. फलानि किं कुर्वन्ति? <br>४. ‘फलान्यपि’ इत्यत्र सन्धिः विभज्यताम्। <br>५. ‘परार्थाय’ इत्यत्र चतुर्थीविभक्तिःकथम्?c <br>६. वृक्षाः ------ इव। (रिक्तस्थानं पूरयत)।</td>
                        </tr>
                        

                    </table>
                </div>
                    
