                        <button id="padasmall6" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '6')">पदविभागः</button>
                        <button id="anvayasmall6" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '6')">अन्वयः</button>
                        <button id="pratismall6" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '6')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall6" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '6')">तात्पर्यम्</button>
                        <button id="vyakyaasmall6" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('vyakyaa', '6')">वाक्याभ्यासः</button>
                        <button id="prasnaasmall6" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prasnaa', '6')">प्रश्नाः</button>
                    </div>
                    <div class="title">
                        6.गच्छन् पिपीलको 
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम् </td>
                            <td>गच्छन् पिपीलको याति योजनानां शतान्यपि।<br> अगच्छन् वैनतेयोऽपि पदमेकं न गच्छति॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>गच्छन् पिपीलको याति, योजनानां शतानि अपि। अगच्छन् वैनतेयः अपि, पदम् एकं न गच्छति॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>पिपीलकः गच्छन् योजनानां शतानि अपि याति,वैनतेयः अगच्छन् एकं पदम् (अपि) न गच्छति।</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>पिपीलकः = प्राणिविशेषः, अल्पः षट्पादजीवी; ant;<br> गच्छन् = चलन्,अग्रे सरन्; (lit. the one who is) while moving, walking,;<br> योजनानां शतानि = अध्वानविशेषः,अतिशयेन दूरम्; (of) hundreds of miles (yojana = an ancient measure of distance) [Apte-A measure of distance equal to four Krośas or eight or nine miles];<br> अपि = च; also;<br> याति = गच्छति; goes;<br> वैनतेयः = गरुडः, विनतानन्दनः; son of vinatA, garuDa, the king of birds;<br> अगच्छन् = गमनं न कुर्वन्; (the one who is) while not moving;<br> एकंपदम् (अपि) = एकस्य पदस्य दूरम्; onestep;<br> नगच्छति = न प्राप्नोति; (does) notgo</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>लघुपिपीलकः अपि प्रयत्नपूर्वकं गच्छन्शतानि योजनानि (अर्थात् बहुदूरम्) गन्तुं समर्थः भवति, परन्तु बलशालीवैनतेयः (गरुडः) अग्रे न सरन्(अर्थात् प्रयत्नं विना) एकमपि पदं न गच्छति। अर्थात् अतिसमर्थः अपि यदि कार्यारम्भं न करोति तर्हि कार्यं न साध्यते।सामान्यः जनः अपि यदि प्रयत्नेन कार्यं करोति तर्हि कार्यसंसिद्धिः भवति। <br>An ant covers hundreds of miles when it keeps moving. Garuda, when stagnant, does not move even one foot.</td>
                        </tr>
                        <tr class="prasnaa">
                            <td style="width: 90px">प्रश्नाः </td>
                            <td> १. योजनानांशतान्यपि कः कथं याति? <br>२. पदमेकं अपि कः न गच्छति? <br>३. ‘वैनतेयोऽपि’ इति शब्दस्य व्याकरणम् किम्? <br>४. अगच्छन्------पदमेकंनगच्छति। (रिक्तस्थानं पूरयत) <br>५. ‘शतान्यपि’इत्यत्रसन्धिः विभज्यताम्। <br>६. गच्छन्------याति। क. पिपीलकः ख. वैनतेयः ग. कोऽपि न</td>
                        </tr>
                        

                    </table>
                </div>
                    
                <div id="7" class="total">
                    <div>
                        <button id="moolamsmall7" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('moolam', '7')">मूलम्</button>
                        <button id="padasmall7" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '7')">पदविभागः</button>
                        <button id="anvayasmall7" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '7')">अन्वयः</button>
                        <button id="pratismall7" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '7')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall7" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '7')">तात्पर्यम्</button>
                        <button id="vyakyaasmall7" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('vyakyaa', '7')">वाक्याभ्यासः</button>
                        <button id="prasnaasmall7" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prasnaa', '7')">प्रश्नाः</button>
                    </div>
                    <div class="title">
                        7. तत्कर्म यन्न बन्धाय 
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम् </td>
                            <td>तत्कर्म यन्न बन्धाय सा विद्या या विमुक्तये।<br> आयासायापरं कर्म विद्यान्या शिल्पनैपुणम्॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>तत् कर्म यत् न बन्धाय,सा विद्या या विमुक्तये। आयासाय अपरं कर्म विद्या अन्या शिल्पनैपुणम्॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>यत् न बन्धाय (भवति) तत् (एव) कर्म। या विमुक्तये (कल्पिता) सा विद्या। अपरं कर्म आयासाय (भवति)। अन्या विद्या शिल्पनैपुणम् (मात्रम् भवति)।</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>यत्न बन्धाय (भवति) = यत् (पाप-पुण्यादिना) न बध्नाति, स्वतन्त्रतां न हरति; that which is not for bondage;<br> तत् (एव)कर्म = तदेव कार्यं; that (alone is)action, effort, activity;<br> याविमुक्तये (कल्पिता) = या मुक्तिं ददाति; that which (leads to) liberation;<br> सा विद्या = तत् ज्ञानं; that is learning, knowledge;<br> अपरं कर्म = अन्यत् कर्म; other work, activity;<br> आयासाय (भवति) = श्रान्तये; (is only) for waste of energy, exertion;<br> अन्या विद्या = अन्यत् ज्ञानं; other learning;<br> शिल्पनैपुणम् (मात्रम् भवति) = केवलं क्रियाकौशलम्; (is just mere) craftsmanship.</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>यत् कर्म पाप-पुण्यादिना न बध्नाति तदेव कर्म अवितथं कर्म भवति। अन्यत् कर्म श्रममात्रं भवति। या मुक्तिमार्गे नयति, सा विद्या अन्वर्था विद्या भवति। अन्यत् सर्वं केवलक्रियाकौशलम् भवति। <br>Effort is that which does not make us bound (to puNya and pApa). Learning is that which leads us to liberation. Rest of all activity is for exertion. And all other learning is mere craftsmanship.</td>
                        </tr>
                        <tr class="prasnaa">
                            <td style="width: 90px">प्रश्नाः </td>
                            <td>१. काविद्याविद्याभवति? <br>२. किं कर्म वास्तवेन कर्म भवति? <br>३. ------अपरंकर्म। (रिक्तस्थानं पूरयत) <br>४. ‘शिल्पनैपुणम्’इति शब्दस्य व्याकरणम् किम्? <br>५. ‘यन्न’इत्यस्य सन्धिः विभज्यताम्। <br>६. अन्या विद्या कस्मै भवति? (साधुविकल्पं चिनुत) क. विमुक्तये ख. शिल्पनैपुणम् ग. बन्धाय</td>
                        </tr>
                        

                    </table>
                </div>
                    
                <div id="8" class="total">
                    <div>
