                        <button id="padasmall8" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '8')">पदविभागः</button>
                        <button id="anvayasmall8" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '8')">अन्वयः</button>
                        <button id="pratismall8" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '8')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall8" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '8')">तात्पर्यम्</button>
                        <button id="vyakyaasmall8" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('vyakyaa', '8')">वाक्याभ्यासः</button>
