                    </div>
                    <div class="title">
                        8. श्रूयतां धर्मसर्वस्वं  
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम् </td>
                            <td>श्रूयतां धर्मसर्वस्वं श्रुत्वा चैव विचार्यताम् ।<br>आत्मनः प्रतिकूलानि परेषान्न समाचरेत् ॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>श्रूयतांधर्मसर्वस्वंश्रुत्वाच एवविचार्यताम् । आत्मनःप्रतिकूलानिपरेषां न समाचरेत्॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>धर्म-सर्वस्वं श्रूयताम्। श्रुत्वा च एव विचार्यताम् । आत्मनः प्रतिकूलानि परेषां न समाचरेत् ॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>धर्म-सर्वस्वं = आचरणयोग्यं समस्तं; essence of all dharma (It has many meanings-What applies here is this :Apte-Duty, prescribed course of conduct);<br> श्रूयताम् = अवधार्यताम्; Do hear;<br> श्रुत्वाच एव  = अवधीर्य; Having heard, after hearing;<br> विचार्यताम् = चिन्तनं क्रियताम्; think, ponder;<br> आत्मनः = स्वस्य; of the self;<br> प्रतिकूलानि = कष्टप्रदानि; unpleasant, disagreeable things;<br> परेषां = इतरेभ्यः; to others;<br> न समाचरेत् = न आचरेत्; never, do not - should do, perform, practise</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>आचरणयोग्यं समस्तं कथ्यते, तत् श्रूयताम्। विचारणं क्रियताम्। यत् स्वस्य कृते क्लेशोत्पादकं भवति, तत् अन्येषां विषये न आचरणीयम्। (यतो हि सर्वत्र सर्वेषु एक एव आत्मा निवसति।) <br>Listen to the essence of all dharma,and then think it over well. Do never perform things, that are disagreeable to one-self, towards others.</td>
                        </tr>
                        <tr class="prasnaa">
                            <td style="width: 90px">प्रश्नाः </td>
                            <td>१. किंश्रूयताम्? <br>२. श्रुत्वा किं क्रियताम्? <br>३. परेषां किं न समाचरेत्? <br>३. परेषां किं न समाचरेत्? <br>५. ‘परेषान्न’ इत्यत्र सन्धिः विभज्यताम्। <br>६. श्रूयतां ------। (रिक्तस्थानं पूरयत)।</td>
                        </tr>
                        

                    </table>
                </div>
                    
