                        <button id="padasmall9" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '9')">पदविभागः</button>
                        <button id="anvayasmall9" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '9')">अन्वयः</button>
                        <button id="pratismall9" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '9')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall9" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '9')">तात्पर्यम्</button>
                        <button id="vyakyaasmall9" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('vyakyaa', '9')">वाक्याभ्यासः</button>
                        <button id="prasnaasmall9" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prasnaa', '9')">प्रश्नाः</button>
                    </div>
                    <div class="title">
                        9. विदेशेषु धनं
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम् </td>
                            <td>विदेशेषु धनं विद्या व्यसनेषु धनं मतिः।<br> परलोके धनं धर्मः शीलं सर्वत्र वै धनम्॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>सुलभः</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>विदेशेषु विद्या धनं। व्यसनेषु मतिः धनं। परलोके धर्मः धनं। शीलं सर्वत्र वै धनम्॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>विदेशेषु = देशान्तरेषु, अज्ञातस्थलेषु; In foreign countries;<br> धनं = सम्पत्तिः, उपयुक्तं वस्तु (न केवलं रूप्यकाणि); money, currency;<br> विद्या = अधीतं ज्ञानं; Learning, knowledge;<br> व्यसनेषु = दुर्भाग्य-कष्ट-प्रतिकूल-कालेषु; in adversities;<br> धनं = बलं, (आवश्यकं वस्तु); wealth;<br> मतिः = बुद्धिः; Intellect, sense;<br> परलोके = जन्मतः प्रयाते सति, लोकान्तरे; in next-world (in Life after death);<br> धनं = साधकं; currency;<br> धर्मः = (अत्र) पुण्यं; (here) good deeds, virtues;<br> शीलं = सद्गुणं, सत्प्रकृतिः, सत्स्वभावः; good character;<br> सर्वत्र = सर्वेषु देशकालेषु; everywhere;<br> वै = हि; indeed;<br> धनम् = प्रतिपत्तिः; treasure</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>विदेशेषु धनं विद्या व्यसनेष धनं मतिः। परलोके धनं धर्मः शीलं सर्वत्र वै धनम्॥ <br>In foreign countries, learning or knowledge is money. In adversities wealth is intellect. In next-world (in Life after death) currency is good deeds done. Good character is treasure everywhere,indeed.</td>
                        </tr>
                        <tr class="prasnaa">
                            <td style="width: 90px">प्रश्नाः </td>
                            <td>१. विद्याकुत्रधनम्?। <br>२. व्यसनेषु किं धनम्? <br>३. धर्मः कुत्र धनम्? <br>४. ‘व्यसनेषु’ इत्यत्र पदविश्लेषणं वदत? <br>५. ‘परलोके’ इत्यत्र समासविग्रहं वदत? <br>६. ------ धनं धर्मः । (रिक्तस्थानं पूरयत।)</td>
                        </tr>
                        

                    </table>
                </div>
                    
                <div id="10" class="total">
                    <div>
