                        <button id="padasmall10" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '10')">पदविभागः</button>
                        <button id="anvayasmall10" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '10')">अन्वयः</button>
                        <button id="pratismall10" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '10')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall10" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '10')">तात्पर्यम्</button>
                        <button id="vyakyaasmall10" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('vyakyaa', '10')">वाक्याभ्यासः</button>
                        <button id="prasnaasmall10" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prasnaa', '10')">प्रश्नाः</button>
                    </div>
                    <div class="title">
                        10. माता शत्रुः
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम् </td>
                            <td>माता शत्रुः पिता वैरी येन बालो न पाठितः ।<br> न शोभते सभामध्ये हंसमध्ये बको यथा ॥ --चाणक्यः </td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>माता शत्रुः पिता वैरी येन बालः न पाठितः । न शोभते सभामध्ये हंसमध्ये बकः यथा । </td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>माता शत्रुः पिता वैरी येन बालो न पाठितः । हंसमध्ये बको यथा न शोभते (तथा) सभामध्ये (सः न शोभते)॥ </td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>माता = जननी; mother;<br> शत्रुः = प्रत्यर्थी; enemy;<br> पिता = जनकः; father;<br> वैरी = वैरमनेन अस्ति इति वैरी, शत्रुः, विपक्षी; opponent;<br> येन = (अत्र) पितृभ्यां; by whom;<br> बालो = पुत्रः; child, (offspring);<br> न पाठितः = विद्या न दापयिता; is not educated;<br> हंसमध्ये = हंसपक्षीनां समूहे; among swans;<br> बको = पक्षिविशेषः; duck;<br> यथा = येन प्रकारेण; like, same as;<br> न शोभते = (तस्य उपस्थितिः) न युज्यते; does not look proper;<br> सभामध्ये = पण्डितसदसि; in meeting</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>यौ पितरौ पुत्रं न विद्यायुक्तं कुर्वतः तौ तस्य शत्रू इव। सः बालः पण्डितसभासु श्वेतहंसमध्यस्थितः श्यामः काकः इव कदापि न शोभते। <br>Both the mother and father are enemies of a child if they do not educate him. He will be a misfit in any gathering-like a duck among swans.</td>
                        </tr>
                        <tr class="prasnaa">
                            <td style="width: 90px">प्रश्नाः </td>
                            <td>१.का शत्रुः कः वैरी? <br>२. कः न शोभते? <br>३. अत्र उपमानं किम्? <br>४. ‘हंसमध्ये’ इत्यत्र समासविग्रहः कः? <br>५. ‘पाठितः’ इत्यत्रपदविश्लेषणं किम्? <br>६. ------ बको यथा। (रिक्तस्थानं पूरयत।)</td>
                        </tr>
                        

                    </table>
                </div>
                    
                <div id="11" class="total">
                    <div>
                        <button id="moolamsmall11" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('moolam', '11')">मूलम्</button>
                        <button id="padasmall11" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '11')">पदविभागः</button>
                        <button id="anvayasmall11" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '11')">अन्वयः</button>
                        <button id="pratismall11" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '11')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall11" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '11')">तात्पर्यम्</button>
                        <button id="vyakyaasmall11" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('vyakyaa', '11')">वाक्याभ्यासः</button>
                        <button id="prasnaasmall11" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prasnaa', '11')">प्रश्नाः</button>
                    </div>
                    <div class="title">
                        11.रूपयौवनसम्पन्नाः 
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम् </td>
                            <td>रूपयौवनसम्पन्नाः विशालकुलसम्भवाः ।<br> विद्याहीनाः न शोभन्ते निर्गन्धाः इव किंशुकाः ॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>रूप-यौवन-सम्पन्नाः विशाल-कुल-सम्भवाः विद्या-हीनाः न शोभन्ते, निर्गन्धाः इव किंशुकाः ॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>रूप-यौवन-सम्पन्नाः,विशाल-कुल-सम्भवाः,विद्या-हीनाः,निर्गन्धाः किंशुकाः इव न शोभन्ते ॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>रूपयौवनसम्पन्नाः = सौन्दर्ये यौवने च आढ्याः; those rich in beauty and youthful;<br> विशालकुलसम्भवाः = प्रसिद्ध-गृहेषु जाताः; those born in great family/clan;<br> विद्या-हीनाः = ज्ञानहीनाः; those devoid of education, knowledge-less;<br> निर्गन्धाः = सुगन्धहीनाः; those lack of fragrance;<br> किंशुकाः इव = पलाशपुष्पाणि इव; blossoms, but without any odour;<br> न शोभन्ते = न युक्ततां भजन्ति; do not befit, do not look proper</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>ये सौन्दर्यातिशयं, यौवनातिशयं भजन्तः अपि विद्यया हीनाः, ते लोके शोभाहीनाः भवन्ति। यथा किंशुकपुष्पाणि सुन्दराणि किन्तु गन्धहीनानि तथा। <br>The people who are beautiful, youthful, born in great families, but still devoid of education are unbefitting like fragrance-less flowers.</td>
                        </tr>
                        <tr class="prasnaa">
                            <td style="width: 90px">प्रश्नाः </td>
                            <td>१.के न शोभन्ते? <br>२.अत्र उपमानं किम्? <br>३.‘रूपयौवनसम्पन्नाः’ इत्यत्र कः समासविग्रहः? <br>४.‘विशालकुलसम्भवाः’ इति शब्दस्य पदविश्लेषणं किम्? <br>५.------ न शोभन्ते। (रिक्तस्थानं पूरयत)। <br>६.‘किंशुका’ नाम के?</td>
                        </tr>
                        

                    </table>
                </div>
                    
                <div id="12" class="total">
                    <div>
                        <button id="moolamsmall12" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('moolam', '12')">मूलम्</button>
                        <button id="padasmall12" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '12')">पदविभागः</button>
                        <button id="anvayasmall12" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '12')">अन्वयः</button>
                        <button id="pratismall12" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '12')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall12" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '12')">तात्पर्यम्</button>
                        <button id="vyakyaasmall12" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('vyakyaa', '12')">वाक्याभ्यासः</button>
                        <button id="prasnaasmall12" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prasnaa', '12')">प्रश्नाः</button>
                    </div>
                    <div class="title">
                        12.आयुः कर्म च
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम् </td>
                            <td>आयुः कर्म च वित्तञ्च विद्या निधनमेव च ।<br> पञ्चैतानि हि सृज्यन्ते गर्भस्थस्यैव देहिनः॥ --चाणक्यनीतिः (पाठान्तरम्-पञ्चैते ननु कल्प्यन्ते गर्भगत्त्वेन देहिनाम् ॥)</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>आयुः कर्म च वित्तं च विद्या निधनम् एव च । पञ्चैतानि हि सृज्यन्ते गर्भस्थस्यैव देहिनः॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>आयुः कर्म वित्तं विद्या निधनम् एव च । पञ्चैतानि हि गर्भस्थस्यैव देहिनः सृज्यन्ते ॥ </td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>आयुः = आजन्म-मृत्यु-अवधिकालः; life-span;<br> कर्म = (अत्र)भाग्यं(पूर्वकृतस्य फलं); (here) fortune (result of previous deeds);<br> वित्तं = धनं; wealth;<br> विद्या = ज्ञानं; education;<br> निधनम् = मृत्युः; death;<br> एव च = तदपि; (lit.) and;<br> ननु = हि; indeed;<br> एते = इमे; all these;<br> पञ्च = एते पञ्चविषयाः; five;<br> एतानि = इमानि; these;<br> सृज्यन्ते = कल्प्यन्ते, प्रभवन्ति; arranged;<br> गर्भस्थस्यैव = गर्भे स्थितस्य एव, पिण्डप्राये एव; while in womb;<br> देहिनः = जीविनः; of human-being</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>मनुष्यस्य आयुर्दायं कियत्प्रमाणकं, भाग्यं कथं भविष्यति, आर्थिकीस्थितिः कीदृशी, ज्ञानं कियल्लप्स्यते, मृत्युश्च कदा भविष्यतीति तस्मिन् मातुः गर्भे एव स्थिते एव निर्णीयते। (अर्थात् अत्र पञ्चविषयेषु प्राणिनः इच्छा न गण्यते।) <br>These five: the life-span, the type of work, wealth, learning and the time of one's death are determined while one is in the womb. (The being’s like or dislike does not count here.)</td>
                        </tr>
                        <tr class="prasnaa">
                            <td style="width: 90px">प्रश्नाः </td>
                            <td>१.पञ्च के सृज्यन्ते? <br>२.पञ्च कस्य सृज्यन्ते? <br>३.‘गर्भस्थस्य’ इत्यत्र पदविश्लेषणं किम्? <br>४.‘देहिनः’ इत्यत्र का विभक्तिः? <br>५.‘वित्तञ्च’ इत्यत्र सन्धिविग्रहंकुरुत? <br>६.------ हि सृज्यन्ते । (रिक्तस्थानं पूरयत)।</td>
                        </tr>
                        

                    </table>
                </div>
                    
                <div id="13" class="total">
                    <div>
