                        <button id="padasmall13" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '13')">पदविभागः</button>
                        <button id="anvayasmall13" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '13')">अन्वयः</button>
