                        <button id="vyakyaasmall13" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('vyakyaa', '13')">वाक्याभ्यासः</button>
                        <button id="prasnaasmall13" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prasnaa', '13')">प्रश्नाः</button>
                    </div>
                    <div class="title">
                        13.शकटं पञ्चहस्तेषु 
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम् </td>
                            <td>शकटं पञ्चहस्तेषु दशहस्तेषु वाजिनम् ।<br> गजं हस्तसहस्रेषु दुर्जनं दूरतस्त्यजेत् ॥ (पाठ.गजं हस्तसहस्रे च दुष्टं दूरे च वर्जजेत् ॥)</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>शकटं पञ्चहस्तेषु दशहस्तेषु वाजिनम् । गजं हस्तसहस्रेषु दुर्जनं दूरतः त्यजेत् ॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>शकटं पञ्चहस्तेषु (त्यजेत्)। दशहस्तेषु वाजिनम् (त्यजेत्)। गजं हस्तसहस्रेषु (त्यजेत्) ।दुर्जनं दूरतः त्यजेत् ॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>शकटं = वाहनं, रथः; chariot, moving vehicle;<br> पञ्चहस्तेषु = पञ्चहस्तप्रमाणकं दूरं (हस्तः नाम कफोणितः मध्यमापर्यन्तं अन्तरालं); (a distance of) 5 times one’s hand-length;<br> दशहस्तेषु = दशहस्तप्रमाणकं दूरं; (a distance of) 10 times one’s hand-length;<br> वाजिनम् = अश्वं; horse;<br> गजं = हस्तिनं; elephant;<br> हस्तसहस्रेषु = सहस्रहस्तप्रमाणकं दूरं; (a distance of) 1000 times one’s hand-length;<br> दुर्जनं = खलं, दुष्टं; (obj. sing.) wicked person, villain;<br> दूरतः = असमीपतः, अनिकटतः; from long distance;<br> त्यजेत् = मुञ्चेत्, नापसर्पयेत्; should leave out, should not approach</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>पञ्चहस्तप्रमाणकात् दूरात् शकटं, दशभ्यः तुरगं, सहस्रात् च गजं त्यजेत्। एते सर्वे अपसर्पणे आपत्कारिणः। दुर्जनस्तु (ततोऽपि अधिकां हानिं करोतीति) सहस्रहस्त-प्रमाणकात् दूरादपि अधिकदूरात् तं त्यजेदिति सन्देशः। (हस्तो नाम मानविशेषः। प्रलम्बित-मध्यमिकायाः कफण्यवधिकं दूरं, अर्धमीटर-मितम्।) <br>One should keep away from a (moving) vehicle at (a distance of) 5 times one’s hand-length; from a horse at (a distance of) 10 times one’s hand-length; an elephant (a distance of) 1000 times one’s hand-length and from a wicked person for a long long distance. (Hasta = 'hand' = a measure of length corresponding to the distance from the elbow to the tip of an elongated middle finger, about 0.5 meters.</td>
                        </tr>
                        <tr class="prasnaa">
                            <td style="width: 90px">प्रश्नाः </td>
                            <td>१.कं पञ्चहस्तेषु त्यजेत्? <br>२.वाजिनं कुत्र त्यजेत्? <br>३.दुर्जनं किं कुर्यात्? <br>४.‘दूरतस्त्यजेत्’ इत्यत्र सन्धिविग्रहं कुरुत? <br>५.‘हस्तसहस्रेषु’ इत्यत्र समासविग्रहं कुरुत? <br>६.------ दूरतस्त्यजेत्। (रिक्तस्थानं पूरयत)।</td>
                        </tr>
                        

                    </table>
                </div>
                    
