                        <button id="padasmall14" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '14')">पदविभागः</button>
                        <button id="anvayasmall14" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '14')">अन्वयः</button>
                        <button id="pratismall14" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '14')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall14" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '14')">तात्पर्यम्</button>
                        <button id="vyakyaasmall14" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('vyakyaa', '14')">वाक्याभ्यासः</button>
                        <button id="prasnaasmall14" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prasnaa', '14')">प्रश्नाः</button>
                    </div>
                    <div class="title">
                        14.उपकारोऽपि नीचानां 
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम् </td>
                            <td>उपकारोऽपि नीचानामपकाराय वर्तते ।<br> पयःपानं भुजङ्गानां केवलं विषवर्धनम् ॥--नीतिसारः</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>उपकारः अपि नीचानाम् अपकाराय वर्तते । पयःपानं भुजङ्गानां केवलं विषवर्धनम् ॥ </td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>नीचानाम् उपकारः अपि अपकाराय वर्तते । भुजङ्गानां पयःपानं केवलं विषवर्धनं (भवति) ॥ </td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>नीचानां = अधमजनानां; of the low people;<br> उपकारः = साहाय्यं; Service, help, assistance, favour, kindness, obligation;<br> अपि = तदपि; also;<br> अपकाराय = हानये; Harm, wrong, injury, hurt, offene, misdeed, wrong deed;<br> वर्तते = भवति; it is (used for completeness in a sentence);<br> भुजङ्गानां = पन्नगानां, सर्पाणां; of the snakes;<br> पयःपानं = दुग्धपानं; giving milk to drink (lit. causal = drink milk);<br> केवलं = (अत्र) नान्यत् प्रयोजकं; alone, only, (here) no other use;<br> विषवर्धनं = विषस्य वर्धकं; growing/ increasing poison </td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>नीचानाम् उपकारः अपि अपकाराय वर्तते ।भुजङ्गानां पयःपानं केवलं विषवर्धनं (भवति) ॥ <br>Helping an evil person will cause harm to one even; same as feeding milk to a snake will only increase its poison.</td>
                        </tr>
                        <tr class="prasnaa">
                            <td style="width: 90px">प्रश्नाः </td>
                            <td>१.किम् अपकाराय वर्तते? <br>२.विषवर्धनं किम्? <br>३.‘उपकारोऽपि’ अत्यत्र सन्धिः विभज्यताम्। <br>४.‘अपकाराय’ इत्यत्र चतुर्थीविभक्तिः कथम्? <br>५.‘पयःपानं’ इत्यस्य समासविग्रहं कुरुत? <br>६.------ भुजङ्गानां केवलं ------। (रिक्तस्थानं पूरयत।)</td>
                        </tr>
                        

                    </table>
                </div>
                    
                <div id="15" class="total">
                    <div>
