                        <button id="padasmall15" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '15')">पदविभागः</button>
                        <button id="anvayasmall15" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '15')">अन्वयः</button>
                        <button id="pratismall15" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '15')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall15" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '15')">तात्पर्यम्</button>
                        <button id="vyakyaasmall15" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('vyakyaa', '15')">वाक्याभ्यासः</button>
                        <button id="prasnaasmall15" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prasnaa', '15')">प्रश्नाः</button>
                    </div>
                    <div class="title">
                        15.वृश्चिकस्य विषं 
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम् </td>
                            <td>वृश्चिकस्य विषं पुच्छं मक्षिकायाः विषं शिरः ।<br> तक्षकस्य विषं दन्तं सर्वाङ्गं दुर्जनस्य च ॥ (पाठ. Verse starts with तक्षकस्य विषं दन्ते..; सर्वाङ्गे दुर्जनो विषम्)</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>वृश्चिकस्य विषं पुच्छं मक्षिकायाः विषं शिरः । तक्षकस्य विषं दन्तं सर्वाङ्गं दुर्जनस्य च ॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>वृश्चिकस्य पुच्छं विषं (भवति)। मक्षिकायाः शिरः विषं (भवति)। तक्षकस्य दन्तं विषं (भवति)। दुर्जनस्य सर्वाङ्गं (विषं भवति)।</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>वृश्चिकस्य = कृमिविशेषः तस्य; of scorpion;<br> पुच्छं = लाङ्गूलं; tail;<br> विषं = क्ष्वेलं, गरलं; poison;<br> मक्षिकायाः = कीटविशेषः तस्याः; of fly;<br> शिरः = मस्तकं; head;<br> तक्षकस्य = सर्पविशेषस्य; of snake (Name of one of the principal serpents);<br> दन्तं = दंशः; teeth;<br> दुर्जनस्य = खलस्य, दुष्टस्य; of wicked;<br> सर्वाङ्गं च = समस्तं शरीरं च; whole body</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>वृश्चिकस्य पुच्छे, मक्षिकायाः शिरसि, तक्षकस्य दन्ते च विष-मयत्वं कल्पितम्। (जन्तूनां एकैकस्मिन्नेव अङ्गे विषं भवति।) खलस्य तु समस्तशरीरे गरलमेव भवति।  <br>The poison of a scorpion is in its tail; the poison of a fly is in its head; the poison of a snake is in its teeth; the poison of a wicked person is in his whole body.</td>
                        </tr>
                        <tr class="prasnaa">
                            <td style="width: 90px">प्रश्नाः </td>
                            <td>१.कस्य विषं पुच्छम्? <br>२.मक्षिकायाः विषं कुत्र? <br>३.दन्ते कस्य विषम्? <br>४.‘सर्वाङ्गं’ इत्यत्र पदविश्लेषणं वदत? <br>५.------ विषं दन्तम् । (रिक्तस्थानं पूरयत।)</td>
                        </tr>
                        

                    </table>
                </div>
                    
                <div id="16" class="total">
                    <div>
