                        <button id="padasmall16" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '16')">पदविभागः</button>
                        <button id="anvayasmall16" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '16')">अन्वयः</button>
                        <button id="pratismall16" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '16')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall16" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '16')">तात्पर्यम्</button>
                        <button id="vyakyaasmall16" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('vyakyaa', '16')">वाक्याभ्यासः</button>
                        <button id="prasnaasmall16" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prasnaa', '16')">प्रश्नाः</button>
                    </div>
                    <div class="title">
                        16.आचार्यात् पादमादत्ते
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम् </td>
                            <td>आचार्यात् पादमादत्ते पादं शिष्यः स्वमेधया ।<br> पादं सब्रह्मचारिभ्यः पादं कालक्रमेण च ॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>आचार्यात् पादम् आदत्ते पादं शिष्यः स्वमेधया पादं सब्रह्मचारिभ्यः पादं कालक्रमेण च। </td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>शिष्यः पादम् आचार्यात् आदत्ते। पादं स्वमेधया (आदत्ते)। पादं सब्रह्मचारिभ्यः (आदत्ते)। पादं कालक्रमेण च (आदत्ते)। </td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>शिष्यः = गुरुकुलनिवासी अध्येता, छात्रः; student (lit. traditional student);<br> पादम् = चतुर्थं भागं; one fourth;<br> आचार्यात् = गुरोः सकाशात्; from Teacher (lit. traditional Guru);<br> आदत्ते = लभते; obtaines, gets;<br> स्वमेधया = स्वस्य धीशक्त्या; by self-understanding, own knowledge;<br> सब्रह्मचारिभ्यः = सहविद्यार्थिभिः साकम् अधीत्य; co-students, fellow learners;<br> कालक्रमेण च = कालान्तरेण; by passage of time</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>(अध्ययनेन अवगमनं कदापि एककाले सम्पूर्णत्वं न याति।) अध्येता एकैकं पादभागं गुरोः सकाशात्(शिक्षणेन), सतीर्थेभ्यः (चर्चादिकं कृत्वा, पौनःपुन्यचिन्तनेन) स्वस्य बुद्ध्या (च गृहीत्वा) अवशिष्टं पादभागं तु शनैः शनैः जीवने अनुभवेन अध्येति।[पादमिति अत्र अवगमनविषयकमिति गुरुशिष्यप्रसङ्गेन ज्ञायते।]  <br>A student gets a quarter (knowledge) from his teacher, a quarter by his own intelligence. A quarter from his co-students and a quarter in due course of time. (Since this is about Shishya, the one-fourth is understood as pertaining to learning.)</td>
                        </tr>
                        <tr class="prasnaa">
                            <td style="width: 90px">प्रश्नाः </td>
                            <td>१.शिष्यः प्रथमपादं कस्मात् आदत्ते? <br>२.द्वितीयं पादभागं केभ्यः आदत्ते? <br>३. कालक्रमेण किमादत्ते? <br>४.‘स्वमेधया’ इत्यत्र तृतीयाविभक्तिसिद्धिं वदत? <br>५. ‘सब्रह्मचारिभ्यः’ इत्यत्र पदविश्लेषणंकुरुत? <br>६.‘कालक्रमेण’ इत्यत्र समासं वदत?</td>
                        </tr>
                        

                    </table>
                </div>
                    
                <div id="17" class="total">
                    <div>
                        <button id="moolamsmall17" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('moolam', '17')">मूलम्</button>
                        <button id="padasmall17" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '17')">पदविभागः</button>
                        <button id="anvayasmall17" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '17')">अन्वयः</button>
                        <button id="pratismall17" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '17')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall17" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '17')">तात्पर्यम्</button>
                        <button id="vyakyaasmall17" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('vyakyaa', '17')">वाक्याभ्यासः</button>
                        <button id="prasnaasmall17" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prasnaa', '17')">प्रश्नाः</button>
                    </div>
                    <div class="title">
                        17.अवश्यमनुभोक्तव्यं 
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम् </td>
                            <td>अवश्यमनुभोक्तव्यं कृतं कर्म शुभाशुभम् ।<br> नाभुक्तं क्षीयते कर्म कल्पकोटिशतैरपि ॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>अवश्यम् अनुभोक्तव्यं कृतं कर्म शुभाशुभम्। न अभुक्तं क्षीयते कर्म कल्प-कोटि-शतैः अपि ॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>कृतं कर्म शुभाशुभम् अवश्यम् अनुभोक्तव्यं (भवति)। अभुक्तं कर्म कल्प-कोटि-शतैः अपि न क्षीयते ॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>कृतं = आचरितं; Done, performed;<br> कर्म = क्रिया; action, deed;<br> शुभाशुभम् = मङ्गलं, अमङ्गलं वा; auspicious (or/and) inauspicious;<br> अवश्यम् = विनापकरणं, अनिवार्यं; definitely;<br> अनुभोक्तव्यम् = अनुभवे प्राप्तव्यम्; has to suffer, bear, undergo;<br> अभुक्तं = न अनुभुक्तं; unenjoyed, unused (here = not beared, not undergone);<br> कर्म = क्रियाफलं; (here-) fruit of deeds;<br> कल्प-कोटि-शतैः = शतानि ब्रह्मवत्सरैः, (1 कल्पः- 4320 लक्षमिताः मनुष्यवत्सराः इति आप्टेकोशे); hundreds of Brahma’s years (कल्प Apte: a period of 432 million years of mortals);<br> अपि = तथापि; also, (even then);<br> न क्षीयते = क्षयंन याति; does not decay, perish, destroy, diminish</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>यत् कार्यमस्माभिः आचरितं, तस्य फलं विनापकरणं अनुभोक्तव्यमेव। अनुभवेनापकरणं विना नान्यः मार्गः। तत् कर्म  ब्रह्मवत्सराणां शतमपि तथैव अक्षीणं तिष्ठति। <br>Man is bound to experience the fruits of his good and bad actions. The karma does not diminish even afterages.</td>
                        </tr>
                        <tr class="prasnaa">
                            <td style="width: 90px">प्रश्नाः </td>
                            <td>१.किमनुभोक्तव्यम्? <br>२.किं कैः न क्षीयते? <br>३.‘कल्पकोटिशतैरपि’ इत्यत्र पदविश्लेषणं किम्? <br>४.‘शुभाशुभम्’ इत्यत्र समासविग्रहं वदत? <br>५.नाभुक्तं ------ कर्म। (रिक्तस्थानं पूरयत) <br>६.‘अनुभोक्तव्यं’ इत्यत्र पदविश्लेषणं किम्?</td>
                        </tr>
                        

                    </table>
                </div>
                    
                <div id="18" class="total">
                    <div>
                        <button id="moolamsmall18" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('moolam', '18')">मूलम्</button>
                        <button id="padasmall18" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '18')">पदविभागः</button>
                        <button id="anvayasmall18" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '18')">अन्वयः</button>
                        <button id="pratismall18" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '18')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall18" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '18')">तात्पर्यम्</button>
                        <button id="vyakyaasmall18" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('vyakyaa', '18')">वाक्याभ्यासः</button>
                        <button id="prasnaasmall18" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prasnaa', '18')">प्रश्नाः</button>
                    </div>
                    <div class="title">
                        18.सत्यम् माता पिता ज्ञानं 
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम् </td>
                            <td>सत्यं माता पिता ज्ञानं धर्मो भ्राता दया सखी ।<br> शान्तिः पत्नी क्षमा पुत्रः षडमी मम बान्धवाः ॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>सत्यं माता पिता ज्ञानं धर्मो भ्राता दया सखी. शान्तिः पत्नी क्षमा पुत्रः षट् अमी मम बान्धवाः॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>सत्यं माता , ज्ञानं पिता , धर्मो भ्राता , दया सखी , शान्तिः पत्नी, क्षमा पुत्रः (सन्ति). अमी षट् मम बान्धवाः॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>सत्यं = यदस्ति तत् सत्यं; That which Is, Truth;<br> माता = जन्मदात्री, जननी; Mother;<br> पिता = जन्मदाता; Father;<br> ज्ञानं = अवबोधः; Knowledge;<br> धर्मो = (अत्र) आचरणीयः कर्तव्यः; Duty;<br> भ्राता = सहोदरः; brother;<br> दया = अनुकम्पा, करुणा; compassion;<br> सखी = मित्रं; friend;<br> शान्तिः = प्रशान्तता, कामक्रोधादिजयः; peace, winning over desire and anger;<br> पत्नी = भार्या; wife;<br> क्षमा = क्षान्तिः, अक्रोधः; Forgiveness, non-anger;<br> पुत्रः = स्वजन्यपुरुषः; Son;<br> अमी षट् = एते षट्; These six;<br> मम बान्धवाः = मत्सम्बन्धिनः; myRelatives</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>मम बान्धवाः षट् सन्ति। सत्यं मम जननी। ज्ञानं जनकः।धर्मः सोदरः। दयामित्रम्। शान्तिः भार्या च । पुत्रः क्षमा।  <br>Truth is my mother, knowledge is my father, righteousness is my brother, compassion is my friend, peace is my wife and patience is my son. These six are my kith and kin.</td>
                        </tr>
                        <tr class="prasnaa">
                            <td style="width: 90px">प्रश्नाः </td>
                            <td>१.के मम बान्धवाः? <br>२.का सखी? <br>३.सत्यं किंतुल्यम्? <br>४.‘षडमी’ इत्यत्र सन्धिः विभज्यताम्। <br>५.पत्नी का? <br>६.षडमी मम ------। (रिक्तस्थानं पूरयत।)</td>
                        </tr>
                        

                    </table>
                </div>
                    
                <div id="19" class="total">
                    <div>
                        <button id="moolamsmall19" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('moolam', '19')">मूलम्</button>
                        <button id="padasmall19" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '19')">पदविभागः</button>
                        <button id="anvayasmall19" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '19')">अन्वयः</button>
                        <button id="pratismall19" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '19')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall19" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '19')">तात्पर्यम्</button>
                        <button id="vyakyaasmall19" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('vyakyaa', '19')">वाक्याभ्यासः</button>
                        <button id="prasnaasmall19" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prasnaa', '19')">प्रश्नाः</button>
                    </div>
                    <div class="title">
                        19.धर्मो जयति
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम् </td>
                            <td>धर्मो जयति नाधर्मः सत्यं जयति नानृतम् ।<br> क्षमा जयति न क्रोधो विष्णुर्जयति नासुरः ॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>धर्मः जयति न अधर्मः। सत्यं जयति न अनृतम् । क्षमा जयति न क्रोधः विष्णुः जयति न असुरः॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>धर्मः जयति, अधर्मःन (जयति), सत्यं जयति, अनृतम् न (जयति), क्षमा जयति, क्रोधः न (जयति), विष्णुः जयति, असुरः न (जयति)॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>धर्मः = ध्रियते सः धर्मः; (here)Right, justice, equity;<br> जयति = जयं लभते,विजयते; wins;<br> नअधर्मः = धर्मभिन्नः न; not injustice;<br> सत्यं = यत् सर्वदा अस्ति तत्; truth, that which always is;<br> न अनृतम् = सत्यभिन्नं, मृषा; not falsehood;<br> क्षमा = अक्रोधः; Patience, forbearance, forgiveness;<br> न क्रोधः = कोपभावना; not anger, wrath;<br> विष्णुः = भगवान् सर्वान्तर्यामी; The All-pervading (In general) God, Almighty;<br> न असुरः = सुरभिन्नः न; not evil spirit, a demon </td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>यदाकदापि लोके धर्मस्य, सत्यस्य, क्षमायाः विष्णोः एव जयः। अधर्मस्य, अनृतस्य, क्रोधस्य, असुरस्य च सर्वदा अपजयः एव।  <br>Justice wins, not injustice; Truth wins, not falsehood; Patience wins, not anger; Almighty wins, not demon.</td>
                        </tr>
                        <tr class="prasnaa">
                            <td style="width: 90px">प्रश्नाः </td>
                            <td>१.के जयन्ति?  <br>२.के न जयन्ति?  <br>३.‘विष्णुर्जयति’इत्यत्र सन्धिविच्छेदनं वदत?  <br>४.‘धर्मो जयति’ इत्यत्र कः सन्धिः? विशदयत।  <br>५.‘अनृतम्’ इत्यत्र समासं विशदयत।</td>
                        </tr>
                        

                    </table>
                </div>
                    
                <div id="20" class="total">
                    <div>
                        <button id="moolamsmall20" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('moolam', '20')">मूलम्</button>
                        <button id="padasmall20" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '20')">पदविभागः</button>
                        <button id="anvayasmall20" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '20')">अन्वयः</button>
                        <button id="pratismall20" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '20')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall20" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '20')">तात्पर्यम्</button>
                        <button id="vyakyaasmall20" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('vyakyaa', '20')">वाक्याभ्यासः</button>
                        <button id="prasnaasmall20" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prasnaa', '20')">प्रश्नाः</button>
                    </div>
                    <div class="title">
                        20.मातृवत् परदारेषु 
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम् </td>
                            <td>मातृवत् परदारांश्च परद्रव्याणि लोष्ठवत् ।<br> आत्मवत् सर्वभूतानि यः पश्यति सः पण्डितः ॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>मातृवत् परदारान् च परद्रव्याणि लोष्टवत् । आत्मवत् सर्वभूतानि यः पश्यति सः पण्डितः ॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>यः परदारान् च मातृवत्, परद्रव्याणि लोष्टवत्, सर्वभूतानि आत्मवत्, पश्यति सः पण्डितः ॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>यः = यः मनुष्यः; the person who, one whoever;<br> परदारान् = अन्येषांपत्नीः; (in) others’ wives;<br> मातृवत् = स्वस्य जननी इव; like mother;<br> परद्रव्याणि = परेषां वस्तूनि; (in) others possessions;<br> लोष्टवत् = मृत्पिण्डवत्; like a lump of earth or clay;<br> सर्वभूतानि = समस्तप्राणिनः; (in) all beings;<br> आत्मवत् = स्वीयवत्; like self;<br> पश्यति = भावयति; sees;<br> सः पण्डितः = सः विवेकशीली; he (is) a scholar</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>यः मनुष्यः अन्येषांपत्नीः स्वस्य जननी इव, परेषां वस्तूनि मृत्पिण्डवत्, समस्तप्राणिनःच स्वीयवत् पश्यन् व्यवहरति- (तथाविधां दृष्टिं वहति) सः विवेकशीली भवति। <br>One who sees others’ wives as one’s own mother, other's wealth as clay, and all the other living creatures as equal to one’s self,that is a scholar, indeed.</td>
                        </tr>
                        <tr class="prasnaa">
                            <td style="width: 90px">प्रश्नाः </td>
                            <td>१.परदारान् कथं पश्येत्? <br>२.कानि लोष्ठवत् पश्यति? <br>३.आत्मवत् कानि पश्येत्? <br>४.कः पण्डितः? <br>५.‘आत्मवत्’ इत्यत्र पदविश्लेषणं वदत? <br>६.‘परद्रव्याणि’ इत्यत्र समासविग्रहं वदत?</td>
                        </tr>
                        

                    </table>
                </div>
                    
