                    </div>
                    <div class="title">
                        21.मक्षिका व्रणमिच्छन्ति
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम् </td>
                            <td>मक्षिका व्रणमिच्छन्ति धनमिच्छन्ति पार्थिवाः ।<br> नीचाः कलहमिच्छन्ति शान्तिमिच्छन्ति साधवः ॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>मक्षिकाः व्रणम् इच्छन्ति। धनम् इच्छन्ति पार्थिवाः। नीचाः कलहमिच्छन्ति सन्धिम् इच्छन्ति साधवः ॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>मक्षिकाः व्रणम् इच्छन्ति। पार्थिवाः धनम् इच्छन्ति। नीचाः कलहम् इच्छन्ति। साधवः सन्धिम् इच्छन्ति॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>मक्षिकाः = कीटविशेषाः; flies;<br> व्रणम् = शरीरक्षतं; wound (obj.);<br> इच्छन्ति = वाञ्छन्ति; desire;<br> पार्थिवाः = राजानः; kings;<br> धनम् = वित्तं; money;<br> नीचाः = अधमजनाः; low minded-people;<br> कलहम् = विवादं; strife, quarrel (obj.);<br> साधवः = सज्जनाः; noble people;<br> सन्धिम् = शान्तिं, सामरस्यं; peace, compromise</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>मक्षिकाः शरीरक्षतम् इच्छन्ति। राजानः वित्तं वाञ्छन्ति। अधमाः विवादं काङ्क्षन्ति। बुधजनाः सामरस्यम् अभिलषन्ति। <br>Flies desire wounds. Kings want money. Low people look for quarrel. Noble people like to have peace.</td>
                        </tr>
                        <tr class="prasnaa">
                            <td style="width: 90px">प्रश्नाः </td>
                            <td>१.मक्षिकाःकिम्इच्छन्ति?  <br>२.सन्धिं के इच्छन्ति? <br>३.नीचाः------ इच्छन्ति। (रिक्तस्थानं पूरयत।)  <br>४.‘पार्थिव’-शब्दस्य पदविश्लेषणंकुरुत?  <br>५.‘इच्छन्ति’इत्यत्र धातुः--क. इच्, ख. इष् ग. इच्छ् (साधुविकल्पं चिनुत)  <br>६.‘सन्धिः’ इत्यस्य------ अर्थः। (रिक्तस्थानं पूरयत।)</td>
                        </tr>
                        

                    </table>
                </div>
                    
                <div id="22" class="total">
                    <div>
                        <button id="moolamsmall22" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('moolam', '22')">मूलम्</button>
                        <button id="padasmall22" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '22')">पदविभागः</button>
                        <button id="anvayasmall22" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '22')">अन्वयः</button>
                        <button id="pratismall22" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '22')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall22" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '22')">तात्पर्यम्</button>
                        <button id="vyakyaasmall22" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('vyakyaa', '22')">वाक्याभ्यासः</button>
                        <button id="prasnaasmall22" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prasnaa', '22')">प्रश्नाः</button>
                    </div>
                    <div class="title">
                        22.अदाता पुरुषस्तयागी 
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम् </td>
                            <td>अदाता पुरुषस्तयागी धनं सन्त्यज्य गच्छति ।<br> दातारं कृपणं मन्ये मृतोऽप्यर्थं न मुञ्चति ॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td></td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>अदाता पुरुषः त्यागी (भवति) । धनं सन्त्यज्य गच्छति । दातारं कृपणं मन्ये। मृतः अपि अर्थं न मुञ्चति ॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>अदाता = दानविमुखः; non-giver, one who does not give charity, miser;<br> पुरुषः = मनुष्यः (स्त्री अपि); man or woman, human;<br> त्यागी = यः सर्वं जहाति, त्यजति; donor, one who gives away without expecting anything in return;<br> धनं = वित्तं; money;<br> सन्त्यज्य = सम्यक् विमुच्य; having left behind;<br> गच्छति = (अत्र- परलोकं) एति; goes away;<br> दातारं = यः (धनादिकं) यच्छति, तं दानशीलिनं; one who gives donations,giver (obj.);<br> कृपणं = यः कदापि किमपि दातुं नेच्छति, लोभी, तं; miser, mean (obj.);<br> मन्ये = इति भावये; I consider, regard, deem, look upon;<br> मृतः अपि = विगतप्राणः अपि; even (when) dead, life-less (man);<br> अर्थं = प्रयोजनं, धनं; (here) substance, objective -(pun here on this word. It means both money and purpose);<br> न मुञ्चति = न त्यजति; does not leave</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>यो दानशीली नास्ति, स पुरुषः त्यागी अस्ति। सः स्वस्य समस्तं धनम् अत्रैव त्यक्त्वा म्रियते,(येन बन्धवः धनं लभन्ते। सः परलेको किमपि न प्राप्नोति। अतः) वास्तविकम् अर्थं मुञ्चति। यः स्वस्मिन् प्राणैः स्थिते सति धनं पूर्वमेव सर्वेभ्यः दत्त्वा म्रियते, स एव यथार्थः लोभी। (तस्य मरणानन्तरं बन्धुभिः स्वीकरणाय किमपि न मुच्यते।) सः वास्तविकं अर्थं मनुष्यजीवनप्रयोजनं न मुञ्चति। <br>The person who does not donate [his wealth] is a charity man. He dies leaving his wealth behind [for others]. I consider the person who makes great donations, a [real] miser [because] he does not leave the fruit even after his death. (The non-giver leaves off the fruit of donation in the other world by possessing; so he is the real giver-up. The giver gets the fruit of donations in the other world by charity; so he is the real miser.)</td>
                        </tr>
                        <tr class="prasnaa">
                            <td style="width: 90px">प्रश्नाः </td>
                            <td>१.कः त्यागी?  <br>२.कः कृपणः?  <br>३.कः किं कदा न मुञ्चति?   <br>४.------ कृपणं मन्ये। (रिक्तस्थानं पूरयत)  <br>५.‘मृतोऽप्यर्थं’इत्यत्र सन्धिः विभज्यताम्। <br>६.‘पुरुषस्तयागी’ इत्यत्र सन्धिः विभज्यताम्।</td>
                        </tr>
                        

                    </table>
                </div>
                    
                <div id="23" class="total">
                    <div>
                        <button id="moolamsmall23" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('moolam', '23')">मूलम्</button>
                        <button id="padasmall23" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '23')">पदविभागः</button>
                        <button id="anvayasmall23" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '23')">अन्वयः</button>
                        <button id="pratismall23" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '23')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall23" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '23')">तात्पर्यम्</button>
                        <button id="vyakyaasmall23" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('vyakyaa', '23')">वाक्याभ्यासः</button>
                        <button id="prasnaasmall23" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prasnaa', '23')">प्रश्नाः</button>
                    </div>
                    <div class="title">
                        23.यस्य नास्ति स्वयं प्रज्ञा 
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम् </td>
                            <td>यस्य नास्ति स्वयं प्रज्ञा शास्त्रं तस्य करोति किम् ।<br> लोचनाभ्याम् विहीनस्य दर्पणः किं करिष्यति॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>यस्य नास्ति स्वयं प्रज्ञा शास्त्रं तस्य करोति किम् ।लोचनाभ्याम् विहीनस्य दर्पणः किं करिष्यति॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>यस्य स्वयं प्रज्ञा नास्ति शास्त्रं तस्य किम् करोति?लोचनाभ्याम् विहीनस्य दर्पणः किं करिष्यति॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>यस्य = यस्य पुरुषस्य; one whose;<br> स्वयं = आत्मनः; oneself, in one's own person;<br> प्रज्ञा = बुद्धिः, धीः; Intelligence, intellect, wisdom;<br> नास्ति = न वर्तते; does not have;<br> शास्त्रं = अध्येयं वस्तु; science, (logos), discipline Any department of knowledge;<br> तस्य = तस्य पुरुषस्य; (here) for him;<br> किम् करोति = को लाभः; what does it do;<br> लोचनाभ्याम् = अक्षिभ्यां; (by his) eyes;<br> विहीनस्य = रहितस्य; of the one who is devoid of;<br> दर्पणः = आदर्शः; mirror;<br> किं करिष्यति = को लाभः; what will (it) do?</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>यस्य स्वबुद्धौ कौशल्यं नास्ति, [शास्त्राध्ययन-सामर्थ्याभावात्] शास्त्रं तस्योपयोगाय न भवति। [अत्र निदर्शनं दीयते] यः अन्धः सः दर्पणेन कं लाभं प्राप्स्यति? [रूपदर्शन-साधनभूत-नेत्रयोरभावात्] <br>What is use of discipline of study to a person who does not have intellectual capacity? What way can a mirror help a person who is blind?</td>
                        </tr>
                        <tr class="prasnaa">
                            <td style="width: 90px">प्रश्नाः </td>
                            <td>१.शास्त्रं कस्य किं करोति इति प्रश्नः? <br>२.अत्र उपमानं किम्? <br>३.‘लोचनाभ्याम् विहीनस्य’ इत्यत्र तृतीया विभक्तिः कथम्? <br>४.------ किं करिष्यति। (रिक्तस्थानं पूरयत) <br>५.अत्र श्लोके कस्य कस्य तुलना केन केन कृता?</td>
                        </tr>
                        

                    </table>
                </div>
                    
                <div id="24" class="total">
                    <div>
                        <button id="moolamsmall24" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('moolam', '24')">मूलम्</button>
                        <button id="padasmall24" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '24')">पदविभागः</button>
                        <button id="anvayasmall24" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '24')">अन्वयः</button>
                        <button id="pratismall24" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '24')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall24" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '24')">तात्पर्यम्</button>
                        <button id="vyakyaasmall24" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('vyakyaa', '24')">वाक्याभ्यासः</button>
                        <button id="prasnaasmall24" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prasnaa', '24')">प्रश्नाः</button>
                    </div>
                    <div class="title">
                        24.कोकिलानां स्वरो रूपं 
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम् </td>
                            <td>कोकिलानां स्वरो रूपं नार्या रूपं पतिव्रतम् ।<br> विद्या रूपं कुरूपाणां क्षमा रूपं तपस्विनाम् ॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>सुलभः</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>कोकिलानां रूपंस्वरः। नार्याः रूपं पतिव्रतम् । कुरूपाणां रूपं विद्या । तपस्विनांरूपं क्षमा ॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>कोकिलानां = पक्षिविशेषाणां; of the cuckoo birds;<br> स्वरो = कण्ठध्वनिः; voice;<br> रूपं = सौन्दर्यं; (here) beauty, elegance, grace;<br> नार्या = स्त्रीणां; of women;<br> पतिव्रतम् = पतौ भक्तिः, सेवानिरतिश्च; quality of being devoted to husband;<br> कुरूपाणां = असुन्दराणां; of the ugly (not good looking) men;<br> विद्या = ज्ञानं; knowledge;<br> तपस्विनाम् = तपः शीलं येषां; of the sages;<br> क्षमा = अकोपः; Patience, forbearance, forgiveness</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>कोकिलपक्षिणां सौन्दर्यं मधुरस्वनौ वर्तते। स्त्रीणां च सौन्दर्यं स्वस्य पतौ अनुरक्तिः सेवाभावना च भवति। ज्ञानमेव रूपहीनानां सौन्दर्यं मन्यते। तपःसम्पन्नानां सौन्दर्यं परेषु सहिष्णुतायां विभाति।  <br>Cuckoos' beauty is their voice. Women’s attraction point is in being husband-devoted. Elegance of ugly men is learning (having knowledge) and sages’ grace is forgiveness.</td>
                        </tr>
                        <tr class="prasnaa">
                            <td style="width: 90px">प्रश्नाः </td>
                            <td>१.कस्य स्वरो रूपम्? <br>२.नार्या रूपं किम्?  <br>३.तपस्विनां किं रूपम्?  <br>४.विद्या रूपं ------ । (रिक्तस्थानं पूरयत)  <br>५.‘पतिव्रतम्’ शब्दस्य कोऽर्थः?  <br>६.‘तपस्विनां’ शब्दस्य पदविश्लेषणं कुरुत।</td>
                        </tr>
                        

                    </table>
                </div>
                    
                <div id="25" class="total">
                    <div>
