                        <button id="padasmall25" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '25')">पदविभागः</button>
                        <button id="anvayasmall25" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '25')">अन्वयः</button>
                        <button id="pratismall25" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '25')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall25" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '25')">तात्पर्यम्</button>
                        <button id="vyakyaasmall25" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('vyakyaa', '25')">वाक्याभ्यासः</button>
                        <button id="prasnaasmall25" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prasnaa', '25')">प्रश्नाः</button>
                    </div>
                    <div class="title">
                        25.पुस्तकस्था तु या विद्या 
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम् </td>
                            <td>पुस्तकस्था तु या विद्या परहस्तगतं धनं।<br> (पाठ. परहस्ते च यद्धनम्) कार्यकाले समायाते न सा विद्या न तद्धनम्॥(पाठ. समुत्पन्ने)</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>पुस्तकस्था तु या विद्या परहस्त-गतं धनं। कार्यकाले समायाते न सा विद्या न तत् धनम्॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>या विद्या पुस्तकस्था तु (यत्) परहस्त-गतं च धनं, कार्यकाले समायाते सा विद्या न (उपयोगाय) तत् धनं न (उपयोगाय)॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>या विद्या = यत् ज्ञानं; that knowledge;<br> पुस्तकस्था तु = ग्रन्थे स्थिता; (which is there) (only) in the book;<br> परहस्तगतं = परेषां अधीनं कृतं; (that which is) gone into others’ hands;<br> धनं = अर्थः, सम्पत्; money;<br> कार्यकालेसमायाते = आवश्यकतायाः आगमने, अवसरे प्राप्ते; (when) time of need (Lit. work) arrives, comes;<br> न सा विद्या = तत् ज्ञानं न ( = निरर्थकं); that is not knowledge;<br> न तत् धनम् = तत् धनं न ( = निरर्थकं); that is not money</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>यत् ज्ञानं पुस्तके स्थितं (न पुनः बुद्धौ) यत् धनं परेषां हस्ते समर्पितं (न पुनः प्राप्तं) - ते द्वे च उपयोगाय न भवतः। व्यर्थमेव तत् द्वयम्। <br>The knowledge in the books, [not understood by oneself] and money given to others [not returned back for personal use] are useless [not handy] in time of need.</td>
                        </tr>
                        <tr class="prasnaa">
                            <td style="width: 90px">प्रश्नाः </td>
                            <td>१.का न विद्या?  <br>२.किं न धनम्?  <br>३.‘पुस्तकस्था’ इत्यस्य पदविश्लेषणं वदत? <br>४.‘परहस्तगतं’ इत्यत्र समासविग्रहं वदत? <br>५.‘कार्यकाले समायाते’ अत्र सप्तमी कथम्?</td>
                        </tr>
                        

                    </table>
                </div>
                    
                <div id="26" class="total">
                    <div>
                        <button id="moolamsmall26" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('moolam', '26')">मूलम्</button>
                        <button id="padasmall26" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '26')">पदविभागः</button>
                        <button id="anvayasmall26" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '26')">अन्वयः</button>
                        <button id="pratismall26" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '26')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall26" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '26')">तात्पर्यम्</button>
                        <button id="vyakyaasmall26" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('vyakyaa', '26')">वाक्याभ्यासः</button>
                        <button id="prasnaasmall26" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prasnaa', '26')">प्रश्नाः</button>
                    </div>
                    <div class="title">
                        26.आदौ चित्ते 
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम् </td>
                            <td>आदौ चित्ते ततः काये सतां सम्पद्यते जरा ।<br> असतां तु पुनः काये नैव चित्ते कदाचन॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>सुलभः</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>सतां जरा आदौ चित्ते ततः(च) काये सम्पद्यते । पुनः असतां तु काये (एव सम्पद्यते) । चित्ते नैव कदाचन (सम्पद्यते) ॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>सतां = महात्मनां; of the noble people, good or virtuous men;<br> जरा = वार्धक्यं; old age;<br> आदौ = प्रथमं; first;<br> चित्ते = मनसि; in (the) mind;<br> ततः = तत्पश्चात्; then;<br> काये = शरीरे; in the body;<br> सम्पद्यते = जायते; arises, is born or produced.;<br> पुनः = (अत्र) किन्तु; On the other hand, on the contrary, but, however,;<br> असतां = दुरात्मनां; of the wicked;<br> तु = निश्चितम्; nevertheless;<br> न एव = न (भवति); never;<br> कदाचन = कदाचिदपि; at some time (here = ever)</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>ये साधुपुरुषाः, वार्धक्यं प्रथमं तेषां मनसि प्रविशति, तत्पश्चादेव शरीरेदृश्यते। दुर्जनानां तु शरीरे वार्धक्यापतनं पश्चादपि मनसि नोदेति। (अन्तरार्थः-) साधुपुरुषाः स्ववयसः अधिकं ज्ञानं प्राप्य ज्ञानेन वृद्धा इव आचरन्ति। गच्छता कालेन ते शरीरेण वार्धक्यं प्राप्नुवन्ति। किन्तु दुष्टाः सर्वदा वार्धक्यं प्राप्यापि ज्ञानं न विन्दन्ति। सदा बाला इवैव आचरन्ति।  <br>Old age gets first into the mind and then into the body [in the case] of virtuous people. But it arises in body, but never mind of the wicked. It means-Virtuous people get ripe in thinking soon, but, for the wicked, even though the body becomes old, the mind never develops. [Old age signifies growth and ripeness]</td>
                        </tr>
                        <tr class="prasnaa">
                            <td style="width: 90px">प्रश्नाः </td>
                            <td>१.सतां जरा कुत्र सम्पद्यते?  <br>२.असतां जरा कुत्र सम्पद्यते?  <br>३.सतां ------ जरा। (रिक्तस्थानं पूरयत।)  <br>४.नैव ----- कदाचन। क. चित्ते ख. काये ग. सतां (साधु विकल्पं चिनुत) <br>५.‘सम्पद्यते’ इत्यस्य पदविश्लेषणं वदत।</td>
                        </tr>
                        

                    </table>
                </div>
                    
                <div id="27" class="total">
                    <div>
                        <button id="moolamsmall27" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('moolam', '27')">मूलम्</button>
                        <button id="padasmall27" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '27')">पदविभागः</button>
                        <button id="anvayasmall27" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '27')">अन्वयः</button>
                        <button id="pratismall27" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '27')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall27" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '27')">तात्पर्यम्</button>
                        <button id="vyakyaasmall27" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('vyakyaa', '27')">वाक्याभ्यासः</button>
                        <button id="prasnaasmall27" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prasnaa', '27')">प्रश्नाः</button>
                    </div>
                    <div class="title">
                        27.आयुषः खण्डमादाय 
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम् </td>
                            <td>आयुषः खण्डमादाय रविरस्तमयं गतः ।<br> अहन्यहनि बोद्धव्यं किमेतत् सुकृतं कृतम्॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>आयुषः खण्डम् आदाय रविः अस्तमयं गतः । अहनि अहनि बोद्धव्यं किम् एतत् सुकृतं कृतम्॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>रविः आयुषः खण्डम् आदाय अस्तमयं गतः। किम् एतत् सुकृतं कृतम्(इति) अहनि अहनि बोद्धव्यम् ॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>रविः = सूर्यः; sun;<br> आयुषः = जीवनकालस्य; of the life-span;<br> खण्डम् = भागं, शकलं; some part;<br> आदाय = गृहीत्वा; having taken;<br> अस्तमयं गतः = (सूर्यस्य) अदर्शनं प्राप्तः; has set down(lit. gone for setting) decline in the western horizon;<br> (गतः(lit.); one who is gone);<br> किम्एतत् = किमिदम्; what (is)this;<br> सुकृतं = सुष्ठु आचरणं; good deeds;<br> कृतम् = आचरितम्; done;<br> अहनि अहनि = प्रतिदिनं; every day;<br> बोद्धव्यम् = चिन्तितव्यम्; should know, understand, comprehend</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>प्रतिदिनं सूर्यास्तमयेन जीवानां आयुर्दायः शनैः शनैः क्षयं याति। ‘किमद्य मया सुष्ठु आचरितम्?’ इति अस्माभिः अहरहं चिन्तितव्यम्। (यतो हि सुकृतमेव अस्मभ्यः पुण्यं ददाति।) <br>Sun is gone away taking somepart of our life-span. So one should one comprehend (contemplate) everyday-‘What good deeds have I done [today]?’ [Not a very good standard of language, [at एतत् and बोद्धव्यम्] but idea is beautiful. So sharing.]</td>
                        </tr>
                        <tr class="prasnaa">
                            <td style="width: 90px">प्रश्नाः </td>
                            <td>१.कःअस्तमयं गतः?  <br>२.किमादाय गतः? <br>३.किं बोद्धव्यम्? <br>४.‘अहन्यहनि’ इत्यत्र सन्धिविग्रहंवदत? <br>५.‘बोद्धव्यं’इत्यत्र पदविश्लेषणं किम्? <br>६.किमेतत् ------ कृतम्। (रिक्तस्थानं पूरयत।)</td>
                        </tr>
                        

                    </table>
                </div>
                    
                <div id="28" class="total">
                    <div>
                        <button id="moolamsmall28" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('moolam', '28')">मूलम्</button>
                        <button id="padasmall28" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '28')">पदविभागः</button>
                        <button id="anvayasmall28" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '28')">अन्वयः</button>
                        <button id="pratismall28" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '28')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall28" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '28')">तात्पर्यम्</button>
                        <button id="vyakyaasmall28" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('vyakyaa', '28')">वाक्याभ्यासः</button>
                        <button id="prasnaasmall28" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prasnaa', '28')">प्रश्नाः</button>
                    </div>
                    <div class="title">
                        28. कः कालः कानि
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम् </td>
                            <td>कः कालः कानि मित्राणि को देशः कौ व्ययागमौ ।<br> कश्चाहं का च मे शक्तिरिति चिन्त्यं मुहुर्मुहुः ॥ (पाठ. कस्याहं)</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>कः कालः कानि मित्राणि कः देशः कौ व्यय-आगमौ । कः च अहं का च मे शक्तिः इति मुहुः मुहुः चिन्त्यम् ॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td></td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>कः कालः = कः समयः; what (is the) time;<br> कानि मित्राणि = के सुहृदः; who (are) friends;<br> कः देशः = कः भूगोलभागविशेषः, जनपदः; which (is the) place, country;<br> कौ व्यय-आगमौ = अर्थस्यापगमः, अर्थादीनां प्राप्तिः (उपार्जनम्); what (are the) expenditure and income;<br> कः च अहं = स्वयं कः; who (am) I;<br> (कस्य अहम् = स्वयं कस्य सम्बन्धी; whose, belonging to whom?);<br> का च मे शक्तिः = मम सामर्थ्यम्; what (is) my strength;<br> इति = एवं; thus;<br> मुहुः मुहुः = वारं वारं; again and again, repeatedly;<br> चिन्त्यं = आध्यानं कर्तव्यम्; should be thought (over)</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>अयं समयः कीदृशः, के जनाःमम सुहृदः, किंविशिष्टःअयं प्रदेशः, कियान् व्ययः,कियान् आगमः,कः च अहं, (कस्य सम्बन्धी इति वा),मम शक्तिः कियती– इत्यादयः वारं वारं चिन्त्याः मानवेन ॥ <br>What is the present time? Who are (my) friends? Which is this place? What are the expenditure and income? Who am I (or whom do I belong to)? What is my strength?-Thus one should constantly think over (about these things.) [This helps in keeping a person always alert and informed. One should never forget one’s real life position.]</td>
                        </tr>
                        <tr class="prasnaa">
                            <td style="width: 90px">प्रश्नाः </td>
                            <td>१. किं मुहुर्मुहुः चिन्त्यम्? <br>२.‘कश्चाहं’ इत्यत्र सन्धिविग्रहं वदत? <br>३.‘शक्तिरिति’ इत्यत्र सन्धिविग्रहं वदत? <br>४.‘व्ययागमौ’ इत्यस्य समासविग्रहं वदत?  <br>५.‘चिन्त्यं’इत्यस्य पदविश्लेषणं वदत? <br>६.‘मुहुर्मुहुः’ इत्यत्र सन्धिविग्रहं वदत?</td>
                        </tr>
                        

                    </table>
                </div>
                    
                <div id="29" class="total">
                    <div>
                        <button id="moolamsmall29" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('moolam', '29')">मूलम्</button>
                        <button id="padasmall29" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '29')">पदविभागः</button>
                        <button id="anvayasmall29" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '29')">अन्वयः</button>
                        <button id="pratismall29" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '29')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall29" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '29')">तात्पर्यम्</button>
                        <button id="vyakyaasmall29" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('vyakyaa', '29')">वाक्याभ्यासः</button>
                        <button id="prasnaasmall29" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prasnaa', '29')">प्रश्नाः</button>
                    </div>
                    <div class="title">
                        29.प्राणमेकं परित्यज्य 
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम् </td>
                            <td>प्राणमेकं परित्यज्य मानमेवाभिरक्षतु ।<br> अनित्याश्चाध्रुवाः प्राणाः मानमाचन्द्रतारकम् ॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>प्राणम् एकं परित्यज्य मानम् एव अभिरक्षतु । अनित्याः च अध्रुवाः प्राणाः मानम् आचन्द्रतारकम् ॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>प्राणम् एकं परित्यज्य मानम् एव अभिरक्षतु । प्राणाः अनित्याः अध्रुवाः च । मानम् (तु) आचन्द्रतारकं (तिष्ठति) ॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>प्राणम् = श्वासः(शरीरे सञ्चरन्तः जीवनसूचकाः पञ्च वायवः); The first of the five life-winds or vital airs, (प्राण, अपान, समान, व्यान and उदान) or the breath of life,in general;<br> एकं = केवलं; alone;<br> परित्यज्य = त्यक्त्वा, अपरिगणय्य; (here) leaving aside;<br> मानम् = अभिमानं, आत्मगौरवम्; self-respect, honour;<br> एव = मात्रं; only;<br> अभिरक्षतु = रक्षां करोतु; save, protect, preserve, guard;<br> प्राणाः = पञ्चप्राणाः, पञ्चवृत्तिकः देहस्थः वायुः; the (five) vital airs;<br> अनित्याः = न नित्याः, सर्वदा न भवन्ति ये; transient, perishable;<br> अध्रुवाः = न निश्चिताः; uncertain;<br> आचन्द्रतारकम् = यावत् चन्द्रः, तारकानि च तिष्ठन्तितावत्; As long as there are the moon and stars</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>प्राणमपि अविगणयन् मानमेव रक्षेत्। श्वासाः न सर्वदा तिष्ठन्ति किन्तु मानं तु शाश्वतिकं भवति।[अस्मिन् सुभाषिते मानस्य महत्त्वं दर्शितम्। अत्र अर्थः प्राणाः मूल्यवन्त नेति न। द्वयोः तुलनायां सत्यां पाञ्चभौतिक-शरीरात् मानस्य आयुः दीर्घं भवति। सति मानहानौ सज्जनाः प्राणान् तृणमिव मन्यन्ते।]  <br>Leaving aside life, one should guard self-respect. Breath is uncertain and transient. But honour is lasting till moon and stars. [This subhAshita stresses on importance of honour. That does not mean that life is unimportant altogether. But when both are compared, since honour has longer life than one’s mortal body, one should care more for honour. Virtuous people care for their reputation more than life. Whenever malice touches their honour, they tend to disregard even their lives.]</td>
                        </tr>
                        <tr class="prasnaa">
                            <td style="width: 90px">प्रश्नाः </td>
                            <td>१.किं परित्यज्य किमभिरक्षतु?  <br>२.मानं कीदृशम्? <br>३.‘अनित्याश्चाध्रुवाः’ इत्यत्र सन्धिः विभज्यताम्।  <br>४.‘आचन्द्रतारकम्’इत्यस्य समासविग्रहं कुरुत? <br>५.प्राणमेकं परित्यज्य ------ । (रिक्तस्थानं पूरयत।)</td>
                        </tr>
                        

                    </table>
                </div>
                    
                <div id="30" class="total">
                    <div>
                        <button id="moolamsmall30" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('moolam', '30')">मूलम्</button>
                        <button id="padasmall30" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '30')">पदविभागः</button>
                        <button id="anvayasmall30" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '30')">अन्वयः</button>
                        <button id="pratismall30" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '30')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall30" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '30')">तात्पर्यम्</button>
                        <button id="vyakyaasmall30" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('vyakyaa', '30')">वाक्याभ्यासः</button>
                        <button id="prasnaasmall30" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prasnaa', '30')">प्रश्नाः</button>
                    </div>
                    <div class="title">
                        30.अनित्यानि शरीराणि
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम् </td>
                            <td>अनित्यानि शरीराणि वैभवं नैव शाश्वतम् ।<br> (पाठ. विभवो नैव शाश्वतः) नित्यं सन्निहितो मृत्युः कर्तव्यो धर्मसङ्ग्रहः ॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td></td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>शरीराणि अनित्यानि । वैभवं न एव शाश्वतम् । मृत्युः नित्यं सन्निहितः। धर्मसङ्ग्रहः कर्तव्यः ॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>अनित्यानि शरीराणि = अशाश्वतानि कायानि; (pl.) mortal bodies are non-eternal, perishable;<br> वैभवम् = सम्पत्; grandeur, glory, magnificence;<br> न एव = न एव; never;<br> शाश्वतम् = नित्यं; constant;<br> मृत्युः = शरीरनाशः; death;<br> नित्यं = सर्वदा; eternal, perpetual;<br> सन्निहितः = निकटस्थः; near;<br> धर्मसङ्ग्रहः = पुण्यसञ्चयः; accumulating (here- earning) (religious or moral) merit, virtue;<br> कर्तव्यः = कार्यः; duty, that which is to be done </td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>देहाः न सर्वकाल-स्थायिनः। धनादिसम्पच्च न शाश्वतम्।अन्तकालः सदा समीपे तिष्ठति। अतः पुण्यसङ्ग्रहः कर्तव्यः।  <br>Physical bodies are transitory. Wealth (and other resources) is not eternal. Death is always near-by. (So) earning (religious or moral) merit is (one’s) duty.</td>
                        </tr>
                        <tr class="prasnaa">
                            <td style="width: 90px">प्रश्नाः </td>
                            <td>१.कानि अनित्यानि?  <br>२.कः कर्तव्यः?  <br>३.मृत्युः कीदृशः? <br>४.नित्यं ------ मृत्युः। (रिक्तस्थानं पूरयत।) <br>५.‘धर्मसङ्ग्रहः’इत्यत्र समासविग्रहं वदत? <br>६.‘सन्निहितः’इत्यत्र पदविश्लेषणं वदत?</td>
                        </tr>
                        

                    </table>
                </div>
                    
                <div id="31" class="total">
                    <div>
                        <button id="moolamsmall31" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('moolam', '31')">मूलम्</button>
                        <button id="padasmall31" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '31')">पदविभागः</button>
                        <button id="anvayasmall31" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '31')">अन्वयः</button>
                        <button id="pratismall31" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '31')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall31" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '31')">तात्पर्यम्</button>
                        <button id="vyakyaasmall31" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('vyakyaa', '31')">वाक्याभ्यासः</button>
                        <button id="prasnaasmall31" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prasnaa', '31')">प्रश्नाः</button>
                    </div>
                    <div class="title">
                        31.उत्पलस्यारविन्दस्य 
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम् </td>
                            <td>उत्पलस्यारविन्दस्य मत्स्यस्य कुमुदस्य च ।<br> एकयोनिप्रसूतानां तेषां गन्धः पृथक् पृथक् ॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>उत्पलस्य अरविन्दस्य मत्स्यस्य कुमुदस्य च । एकयोनि-प्रसूतानां तेषां गन्धः पृथक् पृथक् ॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>उत्पलस्य अरविन्दस्य मत्स्यस्य कुमुदस्य च , एकयोनि-प्रसूतानां (अपि) तेषां पृथक् पृथक् गन्धः॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>उत्पलस्य = नीलकमलस्य; of the blue lotus, any lotus or water lily (Apte), the blossom of the blue lotus, (Nymphaea Caerulea) (MW);<br> अरविन्दस्य = रक्तकमलस्य; of the sun lotus (Nymphea Stellata) (Apte);<br> मत्स्यस्य = मीनस्य; of the fish;<br> कुमुदस्य च = श्वेतोत्पलस्य; of the white water = lily said to open at moon-rise [Nymphea alba] (Apte);<br> तेषां = एतेषां; of these, their;<br> एकयोनि-प्रसूतानां = एकस्मात् कारणात् जातानां; of the produced/originated from same/common source;<br> पृथक् पृथक् = विभिन्नम्; different, dissimilar;<br> गन्धः = सौरभम्; frangrance, smell in general</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>एकत्र (जले) जातानां अपि श्वेतकमलस्य, रक्त-कमलस्य, उत्पलस्य, मीनस्य च गन्धः भिन्नं भिन्नं भवति।  <br>Though blue lotus, sun lotus, fish and water lily are produced from same source, their smell is different from each other. </td>
                        </tr>
                        <tr class="prasnaa">
                            <td style="width: 90px">प्रश्नाः </td>
                            <td>१.केषां किं पृथक् पृथक्? <br>२.‘एकयोनिप्रसूतानां’ इत्यस्य कोऽर्थः?  <br>३.‘एकयोनिप्रसूतानां’ इत्यत्र समासविग्रहं वदत? <br>४.तेषां गन्धः ------। (रिक्तस्थानं पूरयत।)</td>
                        </tr>
                        

                    </table>
                </div>
                    
                <div id="32" class="total">
                    <div>
                        <button id="moolamsmall32" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('moolam', '32')">मूलम्</button>
                        <button id="padasmall32" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '32')">पदविभागः</button>
                        <button id="anvayasmall32" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '32')">अन्वयः</button>
                        <button id="pratismall32" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '32')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall32" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '32')">तात्पर्यम्</button>
                        <button id="vyakyaasmall32" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('vyakyaa', '32')">वाक्याभ्यासः</button>
                        <button id="prasnaasmall32" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prasnaa', '32')">प्रश्नाः</button>
                    </div>
                    <div class="title">
                        32.अर्थानामर्जने 
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम् </td>
                            <td>अर्थानामर्जने दुःखमर्जितानां च रक्षणे ।<br> आये दुःखं व्यये दुःखं धिगर्थाः कष्टसंश्रयाः ॥(पाठ. आये व्यये महद्दुःखं कथमर्थाः सुखावहाः)</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>अर्थानाम् अर्जने दुःखम् अर्जितानां च रक्षणे । आये दुःखं व्यये दुःखं धिग्, अर्थाः कष्टसंश्रयाः ॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>अर्थानाम् अर्जने दुःखम् अर्जितानां च रक्षणे (दुःखम्) । आये दुःखं व्यये दुःखं धिग् अर्थाः कष्टसंश्रयाः ॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>अर्थानाम् = धनस्य; of the riches, wealth;<br> अर्जने = द्रव्य-सम्पादने; in earning;<br> दुःखम् = मनसः पीडा; unhappiness, pain;<br> अर्जितानां च = स्वत्व-कृतानां अर्थानां; of the earned (riches);<br> रक्षणे = (अत्र) सञ्चये; in safe-guarding;<br> आये = लाभे, प्राप्तौ; in earning, in acquisition of money;<br> व्यये = अर्थस्य अपगमे; in spending;<br> धिग् = (निन्दार्थकमव्ययम्)अहो; fie;<br> अर्थाः = धनं; riches, wealth;<br> कष्टसंश्रयाः = व्यथा-स्थानम्; resort of misery, suffering,</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>धनं सम्पादयितुमपि पीडा भवति, तस्य परिरक्षणेऽपि दुःखमेव। धनलाभेन, अपगमेनापि मनसि व्यथा जायते। एवंविध-दुःखभाजनस्य धनस्य धिक्।[अनेन धनार्जनं त्यक्तव्यमिति, धनं पूर्णतया अनुपयुक्तमिति वा न अर्थोऽत्र। किन्तु आवश्यकताम् अतिरिच्य तस्मिन् आदरभावः न युक्तः। अस्य सुभाषितस्य एवं समाधानं वक्तुं शक्यते- 'यल्लभसे निजकर्मोपात्तम्, वित्तं तेन विनोदय चित्तम्']  <br>It is difficult to earn money, and to protect the earnings. Income as well as expenditure give pain-Fie on Money which is the cause of hardship. [This does not mean that money is totally useless or one should stop earning it. But investing too much interest in it is bad. Answer to this would be from something like this-'यल्लभसे निजकर्मोपात्तम्,वित्तंतेनविनोदयचित्तम्']</td>
                        </tr>
                        <tr class="prasnaa">
                            <td style="width: 90px">प्रश्नाः </td>
                            <td>१.के कष्टसंश्रयाः? <br>२.कुत्र कुत्र दुःखं भवति? <br>३.किमनेन धनार्जनं त्यक्तव्यमिति अर्थः? <br>४.‘कष्टसंश्रयाः’ इत्यत्र समासविग्रहःकथम्? <br>५.आये दुःखं ------ दुःखं। (रिक्तस्थानं पूरयत।)</td>
                        </tr>
                        

                    </table>
                </div>
                    
                <div id="33" class="total">
                    <div>
                        <button id="moolamsmall33" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('moolam', '33')">मूलम्</button>
                        <button id="padasmall33" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '33')">पदविभागः</button>
                        <button id="anvayasmall33" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '33')">अन्वयः</button>
                        <button id="pratismall33" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '33')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall33" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '33')">तात्पर्यम्</button>
                        <button id="vyakyaasmall33" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('vyakyaa', '33')">वाक्याभ्यासः</button>
                        <button id="prasnaasmall33" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prasnaa', '33')">प्रश्नाः</button>
                    </div>
                    <div class="title">
                        33.उत्सवे व्यसने 
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम् </td>
                            <td>उत्सवे व्यसने चैव दुर्भिक्षे राष्ट्रविप्लवे राजद्वारे श्मशाने च यस्तिष्ठति स बान्धवः ॥।<br></td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td></td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>उत्सवे व्यसने च एव दुर्भिक्षे राष्ट्रविप्लवे राजद्वारे श्मशाने च यः तिष्ठति स बान्धवः ॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>उत्सवे = आनन्दसमये, पर्वसमये; in festival, joyous or festive occasion;<br> व्यसने च एव = आपत्काले; in Adversity, need;<br> दुर्भिक्षे = प्रकृतिवैपरीत्यकाले; in scarcity of provisions, dearth, famine;<br> राष्ट्रविप्लवे = शत्र्वादिना राज्य-विपत्तौ; during predatory warfare, danger from an enemy.;<br> राजद्वारे = राज्ञः कवाटे; at the gate of king’s palace;<br> श्मशाने च = मृतदेह-दहन-स्थाने; at the a burial or burning ground;<br> यः तिष्ठति = यः पार्श्वे भवति; one who stays (with you in support);<br> स बान्धवः = स बन्धुः; he (indeed) is a relative, kinsman.</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>यः कस्यचित् हर्षसमये, विपत्तौ, अन्नहीने काले, राज्यापद-समये, राजास्थान-गमन-काले, दहनसमये (बन्ध्वादिनां मृतिकाले) पार्श्वे भूत्वा धैर्येण रक्षति, सः एव बन्धु, नान्यः।  <br>He is a (genuine) kinsman, who stands by (in support) in celebration, in adversity, in calamity (like famine), during a scuffle with the enemy and in the royal court (of law?) and in the funeral yard/ burial ground.</td>
                        </tr>
                        <tr class="prasnaa">
                            <td style="width: 90px">प्रश्नाः </td>
                            <td>१.कः बान्धवः?  <br>२.‘यस्तिष्ठति’ इत्यत्र सन्धिविच्छेदनं वदत?  <br>३.‘दुर्भिक्षे’ इत्यस्य अर्थः कः?  <br>४.‘राष्ट्रविप्लवे’ इत्यस्य समासविग्रहं वदत?  <br>५.यस्तिष्ठति स ------। (रिक्तस्थानं पूरयत।) <br>६.उत्सवे इत्यादिषु सप्तमीविभक्तिः केन सूत्रेण?</td>
                        </tr>
                        

                    </table>
                </div>
                    
                <div id="34" class="total">
                    <div>
