                        <button id="anvayasmall34" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '34')">अन्वयः</button>
                        <button id="pratismall34" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '34')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall34" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '34')">तात्पर्यम्</button>
                        <button id="vyakyaasmall34" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('vyakyaa', '34')">वाक्याभ्यासः</button>
                        <button id="prasnaasmall34" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prasnaa', '34')">प्रश्नाः</button>
                    </div>
                    <div class="title">
                        34.पृथिव्यां त्रीणि रत्नानि 
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम् </td>
                            <td>पृथिव्यां त्रीणि रत्नानि जलमन्नं सुभाषितम्।<br> मूढैः पाषाणखण्डेषु रत्नसंज्ञा विधीयते ॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>पृथिव्यां त्रीणि रत्नानि जलम् अन्नं सुभाषितम्।मूढैः पाषाणखण्डेषु रत्नसंज्ञा विधीयते ॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>पृथिव्यां त्रीणि रत्नानि। जलम् अन्नं सुभाषितम्(च)।मूढैः पाषाणखण्डेषु रत्नसंज्ञा विधीयते ॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>पृथिव्यां = भूमौ; on the earth;<br> त्रीणि = त्रयं; three;<br> रत्नानि = मणयः; gems;<br> जलम् = नीरं; water;<br> अन्नं = खाद्यं; food;<br> सुभाषितम् = सूक्तिः; good saying;<br> मूढैः = बुद्धिहीनैः; by the fools;<br> पाषाणखण्डेषु = शिलाखण्डेषु; on the stone-pieces;<br>  रत्नसंज्ञा = रत्नमिति नाम; name (as) gem;<br>  विधीयते = क्रियते; (here) is given (prescribe)</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>लोकेऽस्मिन् त्रीण्येव रत्नानि, नीरं, खाद्यं, सूक्तिश्च। मूढाः एव शिलाखण्डान् (दृष्ट्वा) रत्नानीति कथयन्ति। <br>There are three jewels on earth — water, food and wise sayings. [Only] fools call pieces of [gem] stone as jewels.</td>
                        </tr>
                        <tr class="prasnaa">
                            <td style="width: 90px">प्रश्नाः </td>
                            <td>१.कानि रत्नानि?  <br>२.कुत्र रत्नसंज्ञा मूढैः विधीयते?  <br>३.------ त्रीणि रत्नानि। (रिक्तस्थानं पूरयत।)  <br>४.‘पाषाणखण्डेषु’ इत्यत्र समासविग्रहं वदत?  <br>५.‘रत्नसंज्ञा’ नाम किम्?  <br>६.‘सुभाषितम्’ इत्यस्य पदविश्लेषणं वदत?</td>
                        </tr>
                        

                    </table>
                </div>
                    
                <div id="35" class="total">
                    <div>
                        <button id="moolamsmall35" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('moolam', '35')">मूलम्</button>
                        <button id="padasmall35" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '35')">पदविभागः</button>
                        <button id="anvayasmall35" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '35')">अन्वयः</button>
                        <button id="pratismall35" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '35')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall35" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '35')">तात्पर्यम्</button>
                        <button id="vyakyaasmall35" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('vyakyaa', '35')">वाक्याभ्यासः</button>
                        <button id="prasnaasmall35" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prasnaa', '35')">प्रश्नाः</button>
                    </div>
                    <div class="title">
                        35.विद्वत्त्वं च नृपत्वं च 
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम् </td>
                            <td>विद्वत्त्वं च नृपत्वं च नैव तुल्ये कदाचन।<br> (पाठ. तुल्यं) स्वदेशे पूज्यते राजा विद्वान्‌ सर्वत्र पूज्यते॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>विद्वत्त्वं च नृपत्वं च न एव तुल्ये कदाचन। स्वदेशे पूज्यते राजा विद्वान्‌ सर्वत्र पूज्यते॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>विद्वत्त्वं च नृपत्वं च कदाचन न एव तुल्ये। राजा स्वदेशे पूज्यते। विद्वान्‌ (तु) सर्वत्र पूज्यते॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>विद्वत्त्वं च = पाण्डित्यं च; scholarship;<br> नृपत्वं च = राजत्वं च; kinghood;<br> कदाचन = कदापि; never;<br> न एव तुल्ये = न समाने; not comparable;<br> राजा = नृपः; king;<br> स्वदेशे = स्वस्य प्रदेशे; in own country;<br> पूज्यते = आद्रियते, आराध्यते; is respected;<br> विद्वान्‌ = पण्डितः; scholar;<br> सर्वत्र = सर्वेषु स्थलेषु; everywhere</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>पाण्डित्यं राजत्वं च कदापि न समाने। राजा स्वस्य देशे एव पूज्यते। पण्डितः सर्वैः सम्मान्यते। <br>Scholarship and kinghood are never comparable.A king is worshipped in his own country whereas a scholar is respected everywhere.</td>
                        </tr>
                        <tr class="prasnaa">
                            <td style="width: 90px">प्रश्नाः </td>
                            <td>१.के न तुल्ये?  <br>२.राजा कुत्र पूज्यते?  <br>३.------सर्वत्र पूज्यते । (रिक्तस्थानं पूरयत।)   <br>४.‘विद्वत्त्वं’ इत्यस्य पदविश्लेषणं वदत?  <br>५.‘स्वदेशे’ इत्यत्र केन सप्तमी?</td>
                        </tr>
                        

                    </table>
                </div>
                    
                <div id="36" class="total">
