                        <button id="anvayasmall36" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '36')">अन्वयः</button>
                        <button id="pratismall36" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '36')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall36" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '36')">तात्पर्यम्</button>
                        <button id="vyakyaasmall36" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('vyakyaa', '36')">वाक्याभ्यासः</button>
                        <button id="prasnaasmall36" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prasnaa', '36')">प्रश्नाः</button>
                    </div>
                    <div class="title">
                        36.न चोरहार्यं 
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम् </td>
                            <td>न चोरहार्यं न च राजहार्यं न भ्रातृभाज्यं न च भारकारि।<br> व्यये कृते वर्धत एव नित्यं विद्याधनं सर्वधनप्रधानम् ॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>सुलभः।</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>न चोरहार्यं न च राजहार्यं न भ्रातृभाज्यं न च भारकारि। व्यये कृते वर्धते एव नित्यम्। विद्याधनं सर्वधनप्रधानम् ॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>न चोरहार्यं = चोरैः हर्तुं न शक्यते; not stealable by thieves;<br> न च राजहार्यं = राज्ञा स्वीकर्तुं न शक्यते; not seizable by kings;<br> न भ्रातृभाज्यं = भ्रातृषु विभङ्क्तुं न शक्यते; not divisible among brothers;<br> न च भारकारि = भारं न भवति; not heavy;<br> व्यये कृते = विनियोगे कृते; when spent;<br> वर्धत एव = वर्धते; only grows;<br> नित्यं = सर्वदा; always;<br> विद्याधनं = ज्ञानं नामकं धनं; wealth of learning;<br> सर्वधनप्रधानम् = सर्वेषु धनेषु मुख्यं; prime-most among all wealth</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>विद्या नाम धनं चोरैः वा राज्ञा वा, केनापि हर्तुं न शक्यते। तस्य भारः अपि नास्ति। कस्मैचिदपि दीयते चेत् अस्मासु तत् वर्धते। अतः तत् धनं सर्वधनेषु मुख्यं वर्तते। <br>The wealth of knowledge cannot be stolen by thieves, cannot be seized by kings, cannot be divided amongst brothers, and is not heavy to carry. The more you spend, the more it grows . It is the most important among all kinds of wealth.</td>
                        </tr>
                        <tr class="prasnaa">
                            <td style="width: 90px">प्रश्नाः </td>
                            <td>१.किं सर्वधनप्रधानम्? <br>२.विद्यालक्षणानि वदत? <br>३.‘व्यये कृते’ इत्यत्र सप्तमीविभक्तिः कथम्? <br>४.‘चोरहार्यं’ इत्यत्र समासविग्रहं वदत? <br>५.‘भारकारि’ इत्यत्र समासविग्रहं वदत?  <br>६.‘सर्वधनप्रधानम्’ इत्यत्र समासविग्रहं वदत?</td>
                        </tr>
                        

                    </table>
                </div>
                    
                <div id="37" class="total">
                    <div>
