                        <button id="padasmall37" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '37')">पदविभागः</button>
                        <button id="anvayasmall37" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '37')">अन्वयः</button>
                        <button id="pratismall37" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '37')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall37" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '37')">तात्पर्यम्</button>
                        <button id="vyakyaasmall37" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('vyakyaa', '37')">वाक्याभ्यासः</button>
                        <button id="prasnaasmall37" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prasnaa', '37')">प्रश्नाः</button>
                    </div>
                    <div class="title">
                        37.विद्या मित्रं प्रवासेषु 
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम् </td>
                            <td>विद्या मित्रं प्रवासेषु भार्या मित्रं गृहेषु च ।<br> व्याधितस्यौषधं मित्रं धर्मो मित्रं मृतस्य च ॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>विद्या मित्रं प्रवासेषु भार्या मित्रं गृहेषु च ।व्याधितस्य औषधं मित्रं धर्मः मित्रं मृतस्य च ॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>प्रवासेषु विद्या मित्रं (भवति)। गृहेषु च भार्या मित्रं (भवति)।व्याधितस्य औषधं मित्रं (भवति)।मृतस्य चधर्मः मित्रं (भवति)।</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>प्रवासेषु = विदेशेषु; when in foreign country (lit. out of home place);<br> विद्या = ज्ञानं; learning;<br> मित्रं = सुहृत्; friend;<br> गृहेषु च = गेहेषु; at home(s);<br> भार्या = पत्नी; wife;<br> व्याधितस्य = रुग्णस्य, रोगपीडित्स्य; of the ill;<br> औषधं = रोगपरिहारकं द्रव्यं; medicine;<br> मृतस्य च = गतप्राणस्य; of the dead;<br> धर्मः = (अत्र)सत्कार्याणि कृत्वा अर्जितं पुण्यं; (religious) merit</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>विदेशेषु ज्ञानं मित्रं, गेहे सुहृत् पत्नी, रुग्णस्य मित्रं रोगपरिहारकं द्रव्यं, मृतस्य स्नेहितः धर्मः भवति (मृते परलोकं गते सति तत्कृतं पुण्यमाश्रित्य स्वर्गनरकादिः निर्णीयते)। <br>Knowledge is (one’s) friend in the foreign countries, wife is the friend at home, medicine is sick man's friend and religious merit is the friend after death.(A dead soul’sreaching of the next world is decided on the basis of religious merit.) </td>
                        </tr>
                        <tr class="prasnaa">
                            <td style="width: 90px">प्रश्नाः </td>
                            <td>१.विद्या कुत्र मित्रम्? <br>२.गृहेषु का मित्रम्? <br>३.‘व्याधित’ शब्दस्य पदविश्लेषणं वदत? <br>४.‘व्याधितस्यौषधं’ इत्यत्र सन्धिः विभज्यताम्। <br>५.------ औषधं मित्रं। (रिक्तस्थानं पूरयत।)</td>
                        </tr>
                        

                    </table>
                </div>
                    
                <div id="38" class="total">
                    <div>
