                    </div>
                    <div class="title">
                        38.अयं निजः परो वेति
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम् </td>
                            <td>अयं निजः परो वेति गणना लघुचेतसाम् ।<br>  उदारचरितानां तुवसुधैव कुटुम्बकम् ॥ </td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>अयं निजः परः वा इति गणना लघुचेतसाम् । उदारचरितानां तुवसुधा एव कुटुम्बकम् ॥ </td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>अयं निजः परो वा इति लघुचेतसाम् गणना (भवति)। उदारचरितानां तुवसुधा एव कुटुम्बकम् (भवति)। </td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>अयं = एषः; This person (masculine pronoun);<br> निजः = स्वः; one’s own, belongs to oneself;<br> परः वा = अस्वः, अन्यः; other, non-related;<br> इति = एवं; thus;<br> लघुचेतसाम् = अल्पचित्तानां, अधमानां; of the low-minded people;<br> गणना = मतम्; counting, considering, (here) believing;<br> उदारचरितानांतु = उत्तमजनानां तु; of the noble minded, great characters, but;<br> वसुधा एव = लोकः एव; earth, (here) world;<br> कुटुम्बकम् = स्वस्य गृहजनाः; family</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>एषः मम जनः, एषः अन्यः इति नीचजनाः चिन्तयन्ति। ये महापुरुषाः तेषां तु सम्पूर्णा भूमिः एव स्वस्य गृहमिव भवति। <br>He is mine, he is another, not mine-such are thoughts of narrow minded people. For the noble minded the whole world is a family.</td>
                        </tr>
                        <tr class="prasnaa">
                            <td style="width: 90px">प्रश्नाः </td>
                            <td>१.लघुचेतसांकीदृशी गणना? <br>२.उदारचरितानांकीदृशी गणना?  <br>३.‘वसुधैव’ इत्यत्र सन्धिः विभज्यताम्।  <br>४.‘उदारचरितानां’ इत्यत्र समासविग्रहं वदत?  <br>५.‘लघुचेतसाम्’ इत्यस्य पदविश्लेषणं वदत? <br>६.उदारचरितानां तु ------ ------। (रिक्तस्थानं पूरयत।)</td>
                        </tr>
                        

                    </table>
                </div>
                    
                <div id="39" class="total">
                    <div>
