                        <button id="padasmall39" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '39')">पदविभागः</button>
                        <button id="anvayasmall39" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '39')">अन्वयः</button>
                        <button id="pratismall39" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '39')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall39" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '39')">तात्पर्यम्</button>
                        <button id="vyakyaasmall39" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('vyakyaa', '39')">वाक्याभ्यासः</button>
                        <button id="prasnaasmall39" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prasnaa', '39')">प्रश्नाः</button>
                    </div>
                    <div class="title">
                        39.   चिन्तायाश्च चितायाश्च 
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम् </td>
                            <td>चिन्तायाश्च चितायाश्च बिन्दुमात्रं विशिष्यते ।<br>  चिता दहति निर्जीवं चिन्ता दहति जीवितम् ॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>चिन्तायाः (चिंतायाः)  च चितायाः च बिन्दुमात्रं विशिष्यते चिता दहति निर्जीवं चिन्ता दहति जीवितम् ॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>चिन्तायाः (चिंतायाः) च चितायाः च बिन्दुमात्रं विशिष्यते। चिता निर्जीवं दहति। चिन्ता जीवितम् दहति॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>चिन्तायाः च = मनःपरिदेवनायाः; of the sorrow/worry;<br> चितायाः च = शवदाहाधार-चुल्ली; of the funeral pile, pyre;<br> बिन्दुमात्रं = केवलम् अनुस्वारः; only a nasal sound;<br> विशिष्यते = अधिकं भवति; differs, is distinct;<br> निर्जीवं = विगतप्राणं; the dead, life-less;<br> दहति = भस्मीकरोति; burns;<br> जीवितम् = प्राणयुक्तं; the living</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>चितायाः, चिन्तायाश्च (चिंतायाश्च) मध्ये केवलम् अनुस्वार एव भेदः। चिता मृतं दहति। चिन्ता (चिंता) चैतन्यशीलं दहति। <br>The difference between चिता (funeral pyre) and चिन्ता (चिंता)(sorrow) is just a nasal. While funeral pyre burns one dead, sorrow/worry burns one alive.</td>
                        </tr>
                        <tr class="prasnaa">
                            <td style="width: 90px">प्रश्नाः </td>
                            <td>१.बिन्दुमात्रंकुत्र विशिष्यते? <br>२.चिता चिन्ता कं च दहतः? <br>३.‘चिन्तायाश्च’ इत्यत्र सन्धिः विभज्यताम्।  <br>४.------ दहति निर्जीवं। (रिक्तस्थानं पूरयत।) <br>५.चिन्ता दहति ------। (रिक्तस्थानं पूरयत।) <br>६.‘बिन्दुमात्रं’ इत्यस्य पदविश्लेषणं वदत?</td>
                        </tr>
                        

                    </table>
                </div>
                    
