                        <button id="padasmall40" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '40')">पदविभागः</button>
                        <button id="anvayasmall40" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '40')">अन्वयः</button>
                        <button id="pratismall40" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '40')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall40" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '40')">तात्पर्यम्</button>
                        <button id="vyakyaasmall40" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('vyakyaa', '40')">वाक्याभ्यासः</button>
                        <button id="prasnaasmall40" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prasnaa', '40')">प्रश्नाः</button>
                    </div>
                    <div class="title">
                        40.अन्नदानं महादानम् 
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम् </td>
                            <td>अन्नदानं महादानं विद्यादानमतः परम्।<br> अन्नेन क्षणिका प्रीतिः यावज्जीवं च विद्यया॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>अन्नदानं महादानं विद्यादानम् अतः परम्। अन्नेन क्षणिका प्रीतिः यावत्-जीवं च विद्यया॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>अन्नदानं महादानम्। अतः परं विद्यादानम् । अन्नेन प्रीतिःक्षणिका (भवति)। विद्यया च यावज्जीवम् (भवति)॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>अन्नदानं = खाद्यपदार्थस्य परेभ्यः वितरणम्; giving/ distributing food (in charity eg. feeding the poor);<br> महादानम् = उत्तमं, उत्कृष्टं च प्रदानं; great charity;<br> अतः परम् = इतोऽप्यधिकम्; even more;<br> विद्यादानम् = ज्ञानस्य वितरणम्; giving of knowledge (teaching);<br> अन्नेन = भक्ष्येण; by food;<br> क्षणिका = तत्क्षणे जायमाना; momentary;<br> प्रीतिः = आनन्दः, तृप्तिः; happiness, satisfaction;<br> विद्यया च = ज्ञानेन च; by knowledge, learning;<br> यावज्जीवम् = आजीवनम्, प्राणधारणकालं यावत्; all life</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>भोज्यपदार्थस्य दानाद् अपि उत्तमं ज्ञानस्य दानमिति (तथ्यम्)। कुतः? खादनेन (बुभुक्षा शमनेन च) तात्कालिकी तृप्तिः जायते। परं तु विद्यार्जनेन (अज्ञाननाशः भवति, येन) शाश्वतानन्दः भवति। <br>Giving food is a great charity; but giving knowledge is a greater one. From the food we get momentary satisfaction. But from knowledge, it lasts the whole life.</td>
                        </tr>
                        <tr class="prasnaa">
                            <td style="width: 90px">प्रश्नाः </td>
                            <td>१.किं महादानम्? <br>२.ततः परं किम्? <br>३.------ च विद्यया। (रिक्तं स्थानं पूरयत)।   <br>४.‘यावज्जीवं’ इत्यत्र सन्धिः विभज्यताम्। <br>५.‘महादानम्’ इत्यत्र समासविग्रहं वदत? <br>६.‘क्षणिका’ इत्यस्य पदविश्लेषणं वदत?</td>
                        </tr>
                        

                    </table>
                </div>
                    
