                        <button id="padasmall41" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '41')">पदविभागः</button>
                        <button id="anvayasmall41" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '41')">अन्वयः</button>
