                    <div class="title">
                        41.भाषासु मुख्या मधुरा 
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम् </td>
                            <td>भाषासु मुख्या मधुरा दिव्या गीर्वाणभारती।<br> तस्यां हि काव्यं मधुरं तस्मादपि सुभाषितम्॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>सुलभः</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>भाषासु मुख्या मधुरा दिव्या गीर्वाणभारती। तस्यां हि काव्यं मधुरं तस्माद् अपि सुभाषितम् ॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>भाषासु = व्यक्तासु वाक्षु; among (all) languages;<br> मुख्या = प्रथमगण्या; important;<br> मधुरा = (अत्र) स्वादु; sweet;<br> दिव्या = दैवगुणोपेता; divine;<br> गीर्वाणभारती = देवतानां भाषा; language of gods;<br> तस्यां हि = तत्र; in that (language/literature);<br> काव्यं = कविकृतिः; poetry;<br> तस्मात् अपि = तत्रापि; more than that (compared to that);<br> सुभाषितम् = सुष्ठु भाषितम्; good saying</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>व्यक्तावाक्षु प्रथमा, स्वादु, दिव्यगुणयुक्ता च देवभाषा वर्तते। तत्र कविकृतिः मधुरा भवति। तत्रापि सुभाषितं अति मधुरं भवति।  <br>Of all languages, Sanskrit is the most important, sweet and divine. Among her (literature), poetic works are sweet; more sweeter are the good sayings.</td>
                        </tr>
                        <tr class="prasnaa">
                            <td style="width: 90px">प्रश्नाः </td>
                            <td>१.गीर्वाणभारती कीदृशी? <br>२.तस्मादपि मधुरं किम्? <br>३.तस्यां हि ------ मधुरं। (रिक्तस्थानं पूरयत।) <br>४.‘गीर्वाणभारती’ इत्यत्र समासविग्रहं वदत? <br>५.‘तस्मादपि’ इत्यत्र पञ्चमीविभक्तिः कथम्? <br>६.भाषासु मुख्या मधुरा- इत्यत्र सप्तमीविभक्तिः कथम्?</td>
                        </tr>
                        

                    </table>
                </div>
                    
