                        <button id="padasmall42" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '42')">पदविभागः</button>
                        <button id="anvayasmall42" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '42')">अन्वयः</button>
