                    </div>
                    <div class="title">
                        42.नाभिषेको न संस्कारः
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम् </td>
                            <td>नाभिषेको न संस्कारः सिंहस्य क्रियते मृगैः ।<br> नाभिषेको न संस्कारः सिंहस्य क्रियते मृगैः </td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>न अभिषेकः न संस्कारः सिंहस्य क्रियते मृगैः । विक्रम–अर्जित–राज्यस्य स्वयम् एव मृगेन्द्रता ॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>मृगैः सिंहस्य अभिषेकः न (क्रियते)।संस्कारः (अपि) न क्रियते । (स्व)विक्रम–अर्जित–राज्यस्य स्वयम् एव मृगेन्द्रता ॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>मृगैः = वन्यपशुभिः; by animals;<br> सिंहस्य = मृगराजस्य; of lion;<br> अभिषेकः = सिंहासन-अधिष्ठानवेलायां विशेषस्नानं; coronation;<br> संस्कारः = विशेषक्रिया, शुद्धीकरणम्; A purificatory rite, a sacred rite or ceremony;<br> न क्रियते = न आचर्यते; is not done;<br> विक्रम–अर्जित–राज्यस्य = पराक्रमेण विजितस्य शासन-प्रदेशस्य; of the kingdom earned by prowess, valour;<br> स्वयम् एव = आत्मना एव; by self (here. self-declared);<br> मृगेन्द्रता = वन्यपशूनाम् आधिपत्यम्; kingship of animals</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td><br></td>
                        </tr>
                        <tr class="prasnaa">
                            <td style="width: 90px">प्रश्नाः </td>
                            <td>१.सिंहस्य किं न क्रियते? <br>२.कस्य स्वयमेव मृगेन्द्रता? <br>३.‘विक्रमार्जितराज्यस्य’ इत्यत्र समासविग्रहं वदत?  <br>४.‘मृगेन्द्रता’ इत्यस्य पदविश्लेषणं वदत? <br>५.स्वयमेव ------। (रिक्तस्थानं पूरयत।)</td>
                        </tr>
                        

                    </table>
                </div>
                    
                <div id="43" class="total">
                    <div>
                        <button id="moolamsmall43" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('moolam', '43')">मूलम्</button>
                        <button id="padasmall43" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '43')">पदविभागः</button>
                        <button id="anvayasmall43" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '43')">अन्वयः</button>
                        <button id="pratismall43" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '43')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall43" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '43')">तात्पर्यम्</button>
                        <button id="vyakyaasmall43" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('vyakyaa', '43')">वाक्याभ्यासः</button>
                        <button id="prasnaasmall43" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prasnaa', '43')">प्रश्नाः</button>
                    </div>
                    <div class="title">
                        43.मनस्येकं वचस्येकं 
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम् </td>
                            <td>मनस्येकं वचस्येकं कर्मण्येकं महात्मनाम् ।<br>  मनस्यन्यद् वचस्यन्यत् कर्मण्यन्यद्दुरात्मनाम् ॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>मनसि एकं, वचसि एकं, कर्मणि एकंमहात्मनाम् ।मनसि अन्यत्, वचसि अन्यत्, कर्मणि अन्यत् दुरात्मनाम्॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>महात्मनांमनसि एकं, वचसि एकं, कर्मणि (च) एकं (भवति) ।दुरात्मनांमनसि अन्यत्, वचसि अन्यत्, कर्मणि (च) अन्यत् (भवति) ॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>मनसि = हृदये; in mind;<br> एकं = समानं; one (here. same);<br> वचसि = वाचि; in word;<br> कर्मणि = आचरणे; in work, deed, action;<br> महात्मनाम् = महापुरुषाणां; of the noble people;<br> अन्यत् = असमानं; another (here. different);<br> दुरात्मनाम् = असत्पुरुषाणां; of the wicked people</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>महापुरुषाणां हृदि, वचनेषु, कर्मसु च समानत्वं भवति। दुष्टानां पुनः मनसि अन्यत् भवति, तेषां वचनानि असम्बद्धानि भवन्ति, तेषां आचरणं च तद्भिन्नं भवति।   <br>Virtuous people have the same thing in their mind, in their words and in their actions. Wicked people have one thing on their mind, another in the speech and a different thing in their actions. - samayochitapadyamAlikA</td>
                        </tr>
                        <tr class="prasnaa">
                            <td style="width: 90px">प्रश्नाः </td>
                            <td>१.महात्मानः कीदृशाः? <br>२.दुरात्मानः कीदृशाः? <br>३.‘मनस्येकं’ इत्यत्र सन्धिः विभज्यताम्।  <br>४.‘कर्मण्यन्यद्दुरात्मनाम्’ इत्यत्र सन्धिः विभज्यताम्।  <br>५.कर्मण्येकं ------। (रिक्तस्थानं पूरयत।)</td>
                        </tr>
                        

                    </table>
                </div>
                    
                <div id="44" class="total">
                    <div>
                        <button id="moolamsmall44" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('moolam', '44')">मूलम्</button>
                        <button id="padasmall44" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '44')">पदविभागः</button>
                        <button id="anvayasmall44" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '44')">अन्वयः</button>
                        <button id="pratismall44" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '44')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall44" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '44')">तात्पर्यम्</button>
                        <button id="vyakyaasmall44" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('vyakyaa', '44')">वाक्याभ्यासः</button>
                        <button id="prasnaasmall44" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prasnaa', '44')">प्रश्नाः</button>
                    </div>
                    <div class="title">
                        44.वृथा वृष्टिः समुद्रेषु 
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम् </td>
                            <td>वृथा वृष्टिः समुद्रेषु वृथा तृप्तेषु भोजनम् ।<br> (पाठ. तृप्तस्य) वृथा दानं धनाढ्येषु वृथा दीपो दिवापि च ॥ (पाठ. समृद्धस्य) (पाठ. वृथा शूरे विभूषणम्)</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>(सुलभः)</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>समुद्रेषु वृष्टिः वृथा।तृप्तेषु भोजनंवृथा। धनाढ्येषु दानं वृथा।दिवा अपि च दीपः वृथा ॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>वृथा = निरर्थकम्; waste, useless, futile;<br> वृष्टिः = वर्षाः; rain;<br> समुद्रेषु = उदधिषु; among seas;<br> तृप्तेषु = सन्तुष्टजनेषु; for the satisfied (with food, no longer hungry);<br> भोजनम् = अन्न(दान)म्; (giving) food, feeding;<br> दानं = वितरणम्; charity;<br> धनाढ्येषु = धनिकेषु; rich, wealthy;<br> दीपः = वर्त्तिस्थ-ज्वलद्-अग्निशिखा; lamp;<br> दिवा अपि च = दिनसमये; during day time</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>उदधौ वर्षाणां पातेन न कोऽपि लाभः। ये (पूर्वमेव अन्नेन बुभुक्षाशान्त्या च) तुष्टाः, तेभ्यः भोजनवितरणेन किम्? धनिकजनेभ्यः (धन)दानं व्यर्थकार्यम्। तथैव दिनसमये (सूर्यप्रकाशे सति) दीपज्वलनं निरर्थकम्।  <br>Rain over the ocean, [offering] food for one who has eaten, charity to the wealthy and [lighting] lamp in daylight—all are of no use. (पाठ. समृद्धस्य) = सम्पत्तियुक्तस्य; of the prosperous; (पाठ. वृथा शूरे विभूषणम्) = पराक्रमशालिनः आभूषणं निरर्थकम्; useless is ornament for warrior; (पाठ. तृप्तस्य) = सन्तुष्टस्य; of the satisfied</td>
                        </tr>
                        <tr class="prasnaa">
                            <td style="width: 90px">प्रश्नाः </td>
                            <td>१.समुद्रेषु का वृथा? <br>२.भोजनं कुत्र वृथा? <br>३.‘तृप्तेषु’ इत्यत्र सप्तमीविभक्तिः कथम्?  <br>४.वृथा दानं ------। (रिक्तस्थानं पूरयत।)  <br>५.‘धनाढ्येषु’ इत्यत्र समासविग्रहं वदत?</td>
                        </tr>
                        

                    </table>
                </div>
                    
                <div id="45" class="total">
                    <div>
                        <button id="moolamsmall45" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('moolam', '45')">मूलम्</button>
                        <button id="padasmall45" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '45')">पदविभागः</button>
                        <button id="anvayasmall45" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '45')">अन्वयः</button>
                        <button id="pratismall45" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '45')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall45" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '45')">तात्पर्यम्</button>
                        <button id="vyakyaasmall45" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('vyakyaa', '45')">वाक्याभ्यासः</button>
                        <button id="prasnaasmall45" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prasnaa', '45')">प्रश्नाः</button>
                    </div>
                    <div class="title">
                        45.ये च मूढतमाः लोके
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम् </td>
                            <td>ये च मूढतमा लोके ये च बुद्धेः परं गताः ।<br> त एव सुखमेधन्ते मध्यमः क्लिश्यते जनः ॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>ये च मूढतमाः लोके ये च बुद्धेः परं गताः । ते एव सुखम् एधन्ते मध्यमः क्लिश्यते जनः ॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>ये च मूढतमाः लोके ये च बुद्धेः परं गताः । ते एव सुखम् एधन्ते। मध्यमः जनः क्लिश्यते ॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>ये च = ये जनाः; those who (are);<br> मूढतमाः = अत्यन्तं जडाः; most ignorant;<br> लोके = संसारे; in the world;<br> बुद्धेः = मतेः; in thinking, intellect [lit. of];<br> परं = सीमापरिच्छिन्नं; Beyond, further, on the other side of;<br> गताः = प्राप्ताः; went, reached;<br> ते एव = ते जनाः एव; only those;<br> सुखम् = आनन्दं; happy;<br> एधन्ते = प्राप्नुवन्ति; they prosper, become happy, live in comfort;<br> मध्यमः = द्वयोः स्थित्योः मध्यभवः,नातिजडः, नातिविवेकी; medium;<br> जनः = नरः, पुरुषः; people;<br> क्लिश्यते = कष्टमनुभवति; suffer</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>ये जनाः अत्यन्तं जडाः, ये च विवेकशीलतायाः सीमानं प्राप्ताः- एतौ द्वौ प्रकारकौ सुखं प्राप्नुवन्ति। यः मध्यस्थितौ अस्ति (नाधिकः विवेकी, न अशेषं जडः) सः क्लेशमनुभवति।  <br>Those who are totally foolish and those of superior in intellect -[both] prosper happily in this world. The mediocres [always] suffers. [The foolish do not realize the gravity of a problem and can therefore remain indifferent while the wise manage to find a solution to it. Mediocres neither can solve problem nor be ignorant of it.]</td>
                        </tr>
                        <tr class="prasnaa">
                            <td style="width: 90px">प्रश्नाः </td>
                            <td>१.के सुखमेधन्ते? <br>२.कः क्लिश्यते? <br>३.‘मूढतमाः’ इत्यस्य पदविश्लेषणं वदत?  <br>४.ये च ------ परं गताः। (रिक्तस्थानं पूरयत।) <br>५.‘सुखम् एधन्ते’ इत्यत्र द्वितीयाविभक्तिः कथम्?</td>
                        </tr>
                        

                    </table>
                </div>
                    
                <div id="46" class="total">
                    <div>
                        <button id="moolamsmall46" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('moolam', '46')">मूलम्</button>
                        <button id="padasmall46" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '46')">पदविभागः</button>
                        <button id="anvayasmall46" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '46')">अन्वयः</button>
                        <button id="pratismall46" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '46')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall46" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '46')">तात्पर्यम्</button>
                        <button id="vyakyaasmall46" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('vyakyaa', '46')">वाक्याभ्यासः</button>
                        <button id="prasnaasmall46" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prasnaa', '46')">प्रश्नाः</button>
                    </div>
                    <div class="title">
                        46.मूर्खो न हि ददात्यर्थं 
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम् </td>
                            <td>मूर्खो न हि ददात्यर्थं नरो दारिद्र्यशङ्कया ।<br> प्राज्ञस्तु वितरत्यर्थं नरो दारिद्र्यशङ्कया ॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>मूर्खः न हि ददाति अर्थं नरः दारिद्र्यशङ्कया ।प्राज्ञः तु वितरति अर्थं नरः दारिद्र्यशङ्कया ॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>मूर्खःनरः दरिद्रयशङ्कया अर्थं न हि ददाति।प्राज्ञः नरः तु दारिद्र्यशङ्कया अर्थंवितरति ॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>मूर्खःनरः = बुद्धिहीनःअविवेकी किन्तु स्वं यः बुद्धिमान् मन्यते सः, पण्डितंमन्यः; a fool;<br> दरिद्र्यशङ्कया = दारिद्र्यं घटिष्यते इति भीत्या; by fear of poverty (lit. because of doubt, apprehension of getting poor);<br> अर्थं = धनं, वित्तं; money;<br> न हि ददाति = न (अन्येभ्यः) वितरति; does not give;<br> प्राज्ञः नरः तु = बुद्धिमान्, विवेकी तु; the wise person;<br> वितरति = (परेभ्यः) ददाति; gives</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>अर्धज्ञः ‘दरिद्रो भविष्यामी’ति भयात् धनं न वितरति। विवेकशाली तु दरिद्रो भविष्यामी’ति भयात् धनं वितरति। (अत्र दानेन पुण्यलाभस्य अत्र महत्त्वम्। अविवेकी अस्मिन् जन्मनि लाभं चिन्तयति। बुद्धिमान् अपरजन्मनि पुण्यलाभो भवत्त्विति दानं करोति।) <br>A fool does not give money [in charity] out of fear that he may become poor [in future]; wise gives away money because of same fear. {Intention- Merit that one gains by giving money to needy people is meant here.} </td>
                        </tr>
                        <tr class="prasnaa">
                            <td style="width: 90px">प्रश्नाः </td>
                            <td>१.मूर्खः किं करोति?  <br>२.प्राज्ञः कुतः अर्थं ददाति?  <br>३.‘दारिद्र्यशङ्कया’ इत्यत्र समासविग्रहं वदत?  <br>४.‘प्राज्ञस्तु’ इत्यत्र सन्धिः विभज्यताम्। <br>५.‘ददात्यर्थं’ इत्यत्र सन्धिः विभज्यताम्।  <br>६.प्राज्ञस्तु ------। (रिक्तस्थानं पूरयत।)</td>
                        </tr>
                        

                    </table>
                </div>
                    
