                    </div>
                    <div class="title">
                        47.वज्रादपि कठोराणि 
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम् </td>
                            <td>वज्रादपि कठोराणि मृदूनि कुसुमादपि ।<br> लोकोत्तराणां चेतांसि को हि विज्ञातुमर्हति ॥ (पाठ. को नु)</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>वज्रात् अपि कठोराणि मृदूनि कुसुमाद् अपि लोकोत्तराणां चेतांसि को हि विज्ञातुम् अर्हति ॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>लोकोत्तराणां चेतांसि वज्रात् अपि कठोराणि, कुसुमाद् अपि मृदूनि। को हि विज्ञातुम् अर्हति ॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>लोकोत्तराणां = उत्तमजनानां; people apart from the world, extra ordinary, special, great;<br> चेतांसि = मनांसि; minds;<br> वज्रात् अपि = मूल्यवत्-शिलायाः अपि; than the Indra’s thunderbolt;<br> कठोराणि = परुषाणि, अमृदूनि; tough, strong, hard;<br> कुसुमाद् अपि = प्रसूनात् अपि; than flower;<br> मृदूनि = सौम्यानि, अपरुषाणि; soft;<br> को हि = कः हि; who indeed;<br> विज्ञातुम् = अवगन्तुं, अवबोद्धुं; to know, understand;<br> अर्हति = पारयति; can, is able</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>(स्वस्य विषये) वज्रादपि कठोरम्, (अन्येषां विषये) कुसुमादपि मृदु मनः येषां पुरुषश्रेष्ठानां भवति तादृशानां मनसः अवगमने कः समर्थः ?  <br>Minds of great people are harder than [Indra’s] thunderbolt, [yet] softer than flower. Who in this world is capable of understanding them?</td>
                        </tr>
                        <tr class="prasnaa">
                            <td style="width: 90px">प्रश्नाः </td>
                            <td>१.लोकोत्तराणांचेतांसि कीदृशानि? <br>२.‘लोकोत्तराणां’ इत्यत्र समासविग्रहं वदत?  <br>३.मृदूनि ------। (रिक्तस्थानं पूरयत।) <br>४.को हि ------। (रिक्तस्थानं पूरयत।) <br>५.‘कुसुमादपि’ इत्यत्र पञ्चमीविभक्तिः कथम्?  <br>६.‘विज्ञातुम्’ इत्यस्य पदविश्लेषणं वदत?</td>
                        </tr>
                        

                    </table>
                </div>
                    
