                        <button id="anvayasmall48" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '48')">अन्वयः</button>
                        <button id="pratismall48" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '48')">प्रतिपदार्थः</button>
