                        <button id="prasnaasmall48" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prasnaa', '48')">प्रश्नाः</button>
                    </div>
                    <div class="title">
                        48.सुखस्य दुःखस्य न कोऽपि 
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम् </td>
                            <td>सुखस्य दुःखस्य न कोऽपि दाता परो ददातीति कुबुद्धिरेषा ।<br> (पाठ. कुबुद्धिरेव सा); अहं करोमीति वृथाभिमानः स्वकर्मसूत्रे ग्रथितो हि लोकः॥ (पाठ. पुरातनं कर्म तदेव भुज्यते शरीर हे निस्तर यत्त्वया कृतम् </td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>सुखस्य दुःखस्य न कः अपि दातापरः ददाति इति कुबुद्धिः एषा । अहं करोमि इति वृथा अभिमानःस्वकर्मसूत्रे ग्रथितः हि लोकः।</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>सुखस्य दुःखस्य दाता न कः अपि (भवति)।परः(सुखदःखौ) ददाति इति एषा कुबुद्धिः (वर्तते)।अहं करोमि इति वृथा अभिमानः। लोकःस्वकर्मसूत्रे ग्रथितः हि ।</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>सुखस्य = आनन्दस्य; of pleasure, happiness;<br> दुःखस्य = मनःपीडायाः; of pain, misery;<br> दाता = यः ददाति सः, (अत्र) कारकः; giver (?cause);<br> न कः अपि = न कः अपि नरः; no one;<br> परः = अन्यः, अतरः; other;<br> ददाति = (अत्र) कारयति; gives;<br> इति = एवं; thus;<br> एषा कुबुद्धिः = दोषपूर्णचिन्तनम्; this is wrong thinking;<br> अहं = स्वयं ,  करोमि = (अत्र) कारणं भवामि; (am) doing;<br> वृथा = निरर्थकः; futile, waste;<br> अभिमानः = गर्वः, अहंकारः; self–pride, self–conceit;<br> लोकः = संसारः, विश्वं; world;<br> स्वकर्मसूत्रे = स्वकीयाचरणस्य फलपरम्परया; in the series of self–done–deeds;<br> ग्रथितः हि = निर्बद्धः; is held/tied together</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>सुखस्य दुःखस्य कारकाः नान्याः। अन्यः कोपि (सुखदःखौ) कारयति इति एषा असाधुबुद्धिः।‘अहं करोमि’ इति व्यर्थःगर्वः। जगत् स्वकर्मतन्तौ ग्रथितः । <br>There is no other one who gives us pleasure or pain. The thinking that someone else gives it is totally wrong. The feeling ‘I do’ (I’m the doer) is self–conceit. The world is bonded with the self–‘karma’ [deeds of one’s previous birth]  (Whatever happens with us is an effect of our previous birth behaviour).</td>
                        </tr>
                        <tr class="prasnaa">
                            <td style="width: 90px">प्रश्नाः </td>
                            <td>१.का कुबुद्धिः? <br>२.किमिति वृथाभिमानः?  <br>३.लोकः कुत्र ग्रथितः? <br>४.‘कुबुद्धिरेषा’ इत्यत्र सन्धिः विभज्यताम्। <br>५.‘स्वकर्मसूत्रे’ इत्यत्र समासविग्रहं वदत?  <br>६.------ ------ न कोऽपि दाता। (रिक्तस्थानं पूरयत।); पुरातनं कर्म तदेव भुज्यते शरीर हे निस्तर यत्त्वया कृतम् । पुरातनं =; old; कर्म =; deed(s); तद् एव =; that only; भुज्यते =; is experienced, suffered, endured; शरीर हे =; O body; निस्तर =; To pass through, cross over, atone; यत् त्वया =; which, by you; कृतम् =; done</td>
                        </tr>
                        

                    </table>
                </div>
                    
