                        <button id="vyakyaasmall49" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('vyakyaa', '49')">वाक्याभ्यासः</button>
                        <button id="prasnaasmall49" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prasnaa', '49')">प्रश्नाः</button>
                    </div>
                    <div class="title">
                        49.बोद्धारो मत्सरग्रस्ताः 
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम् </td>
                            <td>बोद्धारो मत्सरग्रस्ताः प्रभवः स्मयदूषिताः।<br> अबोधोपहताश्चान्ये जीर्णमङ्गे सुभाषितम्॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>बोद्धारः मत्सरग्रस्ताः प्रभवः स्मयदूषिताः। अबोध–उपहताः च अन्ये जीर्णम् अङ्गे सुभाषितम्॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>बोद्धारः मत्सरग्रस्ताः। प्रभवः स्मयदूषिताः। अन्ये अबोध–उपहताः च। सुभाषितम् अङ्गे जीर्णम् ॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>बोद्धारः = पण्डिताः; scholars;<br> मत्सरग्रस्ताः = परोत्कर्षासहाः; filled with jealousy;<br> प्रभवः = पालकाः, अधिपाः; rulers;<br> स्मयदूषिताः = गर्वभावेनयुक्ताः; spoilt by arrogance;<br> अन्ये = इतरे; others;<br> अबोध–उपहताः च = अनवगमनशीलाः; struck by non-understanding;<br> सुभाषितम् = सुष्ठु उक्तिः; good saying;<br> अङ्गे = काये; in body;<br> जीर्णम् = शिथलीभूतम्; used up, Worn out, ruined, wasted, decayed, tattered</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>विद्वांसःपरेषां अभिवृद्धिं न सहन्ते। अधिपाःदुरभिमानभावेन संयुताः। इतरेजडधियः। (अतः) सुभाषितम् अन्तःएव शिथिलम् ॥ <br>Learned men are jealous, masters are full of arrogance. Other do not understand, [thus] good quote is decayed in [this] body [i.e. me].</td>
                        </tr>
                        <tr class="prasnaa">
                            <td style="width: 90px">प्रश्नाः </td>
                            <td>१.के मत्सरग्रस्ताः? <br>२.अन्ये कीदृशाः?  <br>३.किमङ्गे जीर्णम्? <br>४.‘अबोधोपहताः’ इत्यस्य पदविश्लेषणं वदत? <br>५.‘स्मयदूषिताः’ इत्यत्र समासविग्रहं वदत? <br>६.------ स्मयदूषिताः। (रिक्तस्थानं पूरयत।)</td>
                        </tr>
                        

                    </table>
                </div>
                    
