                        <button id="vyakyaasmall50" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('vyakyaa', '50')">वाक्याभ्यासः</button>
                        <button id="prasnaasmall50" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prasnaa', '50')">प्रश्नाः</button>
                    </div>
                    <div class="title">
                        50.संसारविषवृक्षस्य 
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम् </td>
                            <td>संसारविषवृक्षस्य द्वे एव मधुरे फले।<br>(पाठ. द्वे फले अमृतोपमे) सुभाषितं च सुस्वादु सद्भिश्च सह सङ्गमः॥ (पाठ. काव्यामृतरसास्वाद आलापः सज्जनैः सह)</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>संसार–विष–वृक्षस्य द्वे एव मधुरे फले। सुभाषितंच सुस्वादु सद्भिः च सह सङ्गमः॥ </td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td></td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>संसार–विष–वृक्षस्य = लोक एव तरुः, तस्य; of the poisonous tree of the world;<br> द्वे एव = द्विसङ्ख्याविशिष्टा एव; two only;<br> मधुरे = स्वादुनी; sweet;<br> फले = वृक्षजात-खाद्यपदार्थ-द्वयं; two fruits;<br> सुभाषितंच = सुष्टु भाषितं च; good saying;<br> सुस्वादु = खादने आनन्दजनकं; tasty;<br> सद्भिः च सह = उत्तमजनैः सह; with noble people;<br> सङ्गमः = साङ्गत्यं; company</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>दूषितस्य जगद्-वृक्षस्य द्वे एव स्वादु फले। सुमधुरं सुभाषितं,सज्जनैः च सह साङ्गत्यम्॥  <br>The poisonous tree of the world has only two tasty fruits- Sweet good saying and company of good people. पाठ. द्वे फले अमृतोपमे = अमृततुल्यं फलद्वयं; two fruits equal to divine nectar (ambrosia)  पाठ. काव्यामृत-रसास्वाद आलापः सज्जनैः सह = काव्यपठनेन जनितः आनन्दः, सत्पुरुषैः सम्भाषणंच; enjoyment of essence of poetic nectar, and speaking with noble people.</td>
                        </tr>
                        <tr class="prasnaa">
                            <td style="width: 90px">प्रश्नाः </td>
                            <td>१.के कस्य कति मधुरे फले? <br>२.‘संसारविषवृक्षस्य’ इत्यत्र समासविग्रहं वदत?  <br>३.‘सद्भिश्च’ इत्यत्र सन्धिः विभज्यताम्। <br>४.‘सद्भिश्च’ इत्यत्र तृतीयाविभक्तिः कथम्? <br>५.------ च सुस्वादु। (रिक्तस्थानं पूरयत।)?</td>
                        </tr>
                        

                    </table>
                </div>
                    
                <div id="51" class="total">
                    <div>
