                        <button id="anvayasmall51" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '51')">अन्वयः</button>
                        <button id="pratismall51" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '51')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall51" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '51')">तात्पर्यम्</button>
                        <button id="vyakyaasmall51" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('vyakyaa', '51')">वाक्याभ्यासः</button>
                        <button id="prasnaasmall51" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prasnaa', '51')">प्रश्नाः</button>
                    </div>
                    <div class="title">
                        51. स्वभावो नोपदेशेन शक्यते कर्तुमन्यथा । सुतप्तमपि पानीयं पुनर्गच्छति शीतताम् ॥
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम् </td>
                            <td>स्वभावः न उपदेशेन शक्यते कर्तुम् अन्यथा ।<br>सुतप्तम् अपि पानीयं पुनः गच्छति शीतताम् ॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td></td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>उपदेशेन स्वभावःअन्यथा कर्तुम् नशक्यते।सुतप्तम् अपि पानीयं पुनः शीतताम् गच्छति ॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>उपदेशेन = अवबोधक-वचनेन; by instruction, teaching, advice;<br> स्वभावः = अन्तःप्रवृत्ति-प्रकृतिः; behaviour, nature;<br> अन्यथा = भिन्नं; otherwise;<br> कर्तुम् = कल्पितुं; to do;<br> नशक्यते = न पार्यते; not possible;<br> सुतप्तम् अपि = उष्णीकृतमपि; even when boiled well, inspite of boiling well;<br> पानीयं = जलं; water;<br> पुनः =; again;<br> शीतताम् = उष्णहीनत्वं; coldness;<br> गच्छति = प्राप्नोति; gets (lit. goes)</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>(नरस्य) प्रकृतिः (सद्वाक्य)अवबोधनेन परिवर्तिर्तुं न शक्यते। वारि (अग्निसंयोगेन) सुष्ठु उष्णीकृतमपि पुनः (वह्निराहित्ये) तापहीनस्थितिं याति। <br>By giving advice, the nature of a person cannot be done otherwise; even after being well boiled, water reverts to [its original state of] coldness.</td>
                        </tr>
                        <tr class="prasnaa">
                            <td style="width: 90px">प्रश्नाः </td>
                            <td>१.किं केन अन्यथा कर्तुं न शक्यते? <br>२.अत्र उपमानं किम्? <br>३.‘पुनर्गच्छति’ इत्यत्र सन्धिः विभज्यताम्। <br>४.‘सुतप्तम्’ इत्यत्र समासविग्रहं वदत?  <br>५.पुनर्गच्छति ------। (रिक्तस्थानं पूरयत।)</td>
                        </tr>
                        

                    </table>
                </div>
                    
                <div id="52" class="total">
                    <div>
