                        <button id="padasmall52" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '52')">पदविभागः</button>
                        <button id="anvayasmall52" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '52')">अन्वयः</button>
                        <button id="pratismall52" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '52')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall52" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '52')">तात्पर्यम्</button>
                        <button id="vyakyaasmall52" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('vyakyaa', '52')">वाक्याभ्यासः</button>
                        <button id="prasnaasmall52" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prasnaa', '52')">प्रश्नाः</button>
                    </div>
                    <div class="title">
                        52.यस्मिन्जीवतिजीवन्ति
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम् </td>
                            <td>यस्मिन् जीवति जीवन्ति बहवः स तु जीवति ।<br> (पाठ. सोऽत्र जीवति) काकोऽपि किं न कुरुते चञ्च्वा स्वोदरपूरणम् ॥ (पाठ. वयांसि किं न)</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>यस्मिन् जीवति जीवन्ति बहवः स तु जीवति । काकः अपि किं न कुरुते चञ्च्वा स्व–उदरपूरणम् ॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>यस्मिन् जीवति जीवन्ति बहवः स तु जीवति । किं काकः अपि चञ्च्वा स्व–उदरपूरणम् न कुरुते ॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>यस्मिन् जीवति = यस्य प्राणधारणेन; while living of whom;<br> जीवन्ति = प्राणान् धरन्ति; live;<br> बहवः = अधिकजनाः; many;<br> स तु = सः नरःतु; that (person) indeed;<br> जीवति = प्राणयुक्तो भवति; lives;<br> किं = (प्रश्नः); what;<br> काकः अपि = पक्षिविशेषः अपि; crow also;<br> चञ्च्वा = मुखेन; by beak;<br> स्व–उदरपूरणम् = जीवननिर्वहणं, बुभुक्षाशान्तिं; filling own stomach;<br> न कुरुते = न विदधाति; does it not do</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>यस्य पुरुषस्य जीवनधारणेन बहूनां जीवनं भवति, (अर्थात् यः अन्येषां जीवनाय साहाय्यको भवति) तस्य जीवनमेव जीवनं नाम। अत्र उपमानं- (क्षुद्रप्राणी) काकः अपि चञ्चुमुपयुज्य स्वस्य बुभुक्षां शमयति। (अर्थात् स्वार्थाय सर्वे जीवन्ति। परार्थाय यः जीवति, तस्य जन्म सफलम्।)  <br>Only such person, indeed, lives, by whose living, live many. Does even a crow not fill its stomach with its beak?</td>
                        </tr>
                        <tr class="prasnaa">
                            <td style="width: 90px">प्रश्नाः </td>
                            <td>१.कः जीवति?  <br>२.काकः किं करोति? <br>३.‘यस्मिन् जीवति’ इत्यत्र सप्तमीविभक्तिः कथम्?  <br>४.‘काकोऽपि’ इत्यत्र सन्धिः विभज्यताम्।  <br>५.‘चञ्च्वा’ इत्यत्र तृतीयाविभक्तिः कथम्? <br>६.‘स्वोदरपूरणम्’ इत्यत्र समासविग्रहं वदत?</td>
                        </tr>
                        

                    </table>
                </div>
                    
                <div id="53" class="total">
                    <div>
                        <button id="moolamsmall53" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('moolam', '53')">मूलम्</button>
                        <button id="padasmall53" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '53')">पदविभागः</button>
                        <button id="anvayasmall53" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '53')">अन्वयः</button>
                        <button id="pratismall53" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '53')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall53" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '53')">तात्पर्यम्</button>
                        <button id="vyakyaasmall53" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('vyakyaa', '53')">वाक्याभ्यासः</button>
                        <button id="prasnaasmall53" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prasnaa', '53')">प्रश्नाः</button>
                    </div>
                    <div class="title">
                        53.यथा चित्तं तथा वाचो 
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम् </td>
                            <td>यथा चित्तं तथा वाचो यथा वाचस्तथा क्रियाः ।<br> (पाठ. तथा वाक्यं) चित्ते वाचि क्रियायां च साधूनामेकरूपता ॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>यथा चित्तं तथा वाचः यथा वाचः तथा क्रियाः । चित्ते वाचि क्रियायां च साधूनाम् एकरूपता ॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td></td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>यथा चित्तं = मनः अनुसृत्य; as the mind;<br> तथा वाचः = अनुगामि वचनं; so the words;<br> तथा क्रियाः = अनुगामीनि कार्याणि; so the deeds;<br> चित्ते = मनसि; in mind;<br> वाचि = वचने; in speech;<br> क्रियायांच = कार्याचरणे; in deeds as well;<br> साधूनाम् = उत्तमजनानां; of the noble;<br> एकरूपता = समानत्वं; one-ness, one form, uniformity</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>मनः अनुगामिनी वाक्, वचोऽनुगामि कार्यं च (साधूनां भवति। तेषां) मनसि, वचने, कर्मणि च सारूप्यं भवति। (ते त्रिकरणशुद्ध्या व्यवहरन्ति इति भावः।)  <br>As the mind is, so the speech; as the speech is, so the deeds; there is uniformity in the mind, speech and action of the noble.</td>
                        </tr>
                        <tr class="prasnaa">
                            <td style="width: 90px">प्रश्नाः </td>
                            <td>१.क्रियाः किमाश्रित्य भवन्ति? <br>२.‘साधूनामेकरूपता’ कुत्र? <br>३.‘वाचस्तथा’ इत्यत्र सन्धिः विभज्यताम्। <br>४.यथा ------ क्रियाः। (रिक्तस्थानं पूरयत।) <br>५.चित्ते वाचि ------ च। (रिक्तस्थानं पूरयत।) <br>६.‘एकरूपता’ इत्यत्र समासविग्रहं वदत।</td>
                        </tr>
                        

                    </table>
                </div>
                    
                <div id="54" class="total">
                    <div>
