                        <button id="padasmall54" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '54')">पदविभागः</button>
                        <button id="anvayasmall54" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '54')">अन्वयः</button>
                        <button id="pratismall54" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '54')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall54" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '54')">तात्पर्यम्</button>
                        <button id="vyakyaasmall54" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('vyakyaa', '54')">वाक्याभ्यासः</button>
                        <button id="prasnaasmall54" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prasnaa', '54')">प्रश्नाः</button>
                    </div>
                    <div class="title">
                        54.विषादप्यमृतं ग्राह्यं 
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम् </td>
                            <td>विषादप्यमृतं ग्राह्यं बालादपि सुभाषितम् ।<br> अमित्रादपि सद्वृत्तं अमेध्यादपि काञ्चनम् ॥ </td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>विषाद् अपि अमृतं ग्राह्यं बालाद् अपि सुभाषितम् । अमित्राद् अपि सद्वृत्तं अमेध्याद् अपि काञ्चनम् ॥ </td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>विषाद् अपि अमृतं ग्राह्यं बालाद् अपि सुभाषितम् (ग्राह्यं)। अमित्राद् अपि सद्वृत्तं (ग्राह्यं)। अमेध्याद् अपि काञ्चनम् (ग्राह्यं) ॥ </td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>विषाद् अपि = गरलात् अपि; even from poison;<br> अमृतं = पीयूषं; divine nectar;<br> ग्राह्यं = स्वीकर्तव्यं; should be accepted, taken;<br> बालाद् अपि = अल्पवयस्कादपि; even from child;<br> सुभाषितम् = सुष्ठु भाषितम्; good saying;<br> अमित्राद् अपि = शत्रोः अपि; even from a foe, enemy;<br> सद्वृत्तं = सुष्ठु प्रवृत्तिं; good conduct;<br> अमेध्याद् अपि = मालिन्यात्अपि; from unholy, filthy, foul, dirty, impure;<br> काञ्चनम् = सुवर्णम्; gold </td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>क्ष्वेलाद् अपि सुधा स्वीकर्तव्या। अप्रौढादपि सुष्ठूक्तं अनुमन्तव्यम्। अरेरपि सद्वर्तनं प्राप्तव्यम्। मलादपि कनकं ग्राह्यम्। <br>Divine nectar should be extracted even from poison. A good saying should be accepted even from a small child. Good character should be accepted even from enemies. Gold should be extracted even from garbage.</td>
                        </tr>
                        <tr class="prasnaa">
                            <td style="width: 90px">प्रश्नाः </td>
                            <td>१.विषादपि किं ग्राह्यम्?  <br>२.सद्वृत्तं कस्मात् ग्राह्यम्? <br>३.बालादपि ------। (रिक्तस्थानं पूरयत।) <br>४.------ काञ्चनम्। (रिक्तस्थानं पूरयत।)  <br>५.‘बालादपि’इत्यत्र सन्धिः विभज्यताम्। <br>६.‘अमित्र’ इत्यत्र समासविग्रहं वदत?</td>
                        </tr>
                        

                    </table>
                </div>
                    
