                        <button id="padasmall55" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '55')">पदविभागः</button>
                        <button id="anvayasmall55" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '55')">अन्वयः</button>
