                    </div>
                    <div class="title">
                        55.अलिरनुसरति परिमलं 
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम् </td>
                            <td>अलिरनुसरति परिमलं लक्ष्मीरनुसरति नयनिपुणम् ।<br> निम्नमनुसरति सलिलं विधिलिखतं बुद्धिरनुसरति ॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>अलिः अनुसरति परिमलं लक्ष्मीः अनुसरति नयनिपुणम् । निम्नम् अनुसरति सलिलं विधिलिखतं बुद्धिः अनुसरति ॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>अलिः परिमलं अनुसरति। लक्ष्मीः नयनिपुणम् अनुसरति। सलिलं निम्नम् अनुसरति। बुद्धिः विधिलिखतं अनुसरति ॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>अलिः = मधुपः; black bee;<br> परिमलं = सुगन्धं; frangrance;<br> अनुसरति = पृष्ठतः गच्छति; follows, goes behind;<br> लक्ष्मीः = श्रीः; Goddess of wealth;<br> नयनिपुणम् = युक्तियुक्तं; morally strong;<br> सलिलं = जलं; water;<br> निम्नम् = अनुत्तुङ्गं स्थानं; slope (low-lying region);<br> बुद्धिः = मतिः; perception;<br> विधिलिखतं = कर्मफलत्वात् प्राप्तं; ordained by destiny (lit. written by fate)</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>भृङ्गः सौरभमनुयाति। धनदेवी उपायवन्तं नरमनुगच्छति। वारि अधःस्तात् स्थितिमनुव्रजति। विवेकः ललाटलिखितमाश्रित्य चलति। <br>Bee follows fragrance; Goddess Lakṣmī goes to the morally strong; water follows slope; the perception follows what is ordained by destiny.</td>
                        </tr>
                        <tr class="prasnaa">
                            <td style="width: 90px">प्रश्नाः </td>
                            <td>१.अलिः किमनुसरति?  <br>२.किं निम्नमनुसरति? <br>३.‘बुद्धिरनुसरति’ इत्यत्र सन्धिः विभज्यताम्। <br>४.लक्ष्मीरनुसरति ------। (रिक्तस्थानं पूरयत।)? <br>५.‘विधिलिखतं’ इत्यत्र समासविग्रहं वदत? <br>६.‘नयनिपुणम्’ इत्यत्र समासविग्रहं वदत?</td>
                        </tr>
                        

                    </table>
                </div>
                    
