                    <div class="title">
                        56.उपदेशो हि मूर्खाणां 
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम् </td>
                            <td>उपदेशो हि मूर्खाणां प्रकोपाय न शान्तये ।<br> पयःपानं भुजङ्गानां केवलं विषवर्धनम् ॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>उपदेशः हि मूर्खाणां प्रकोपाय न शान्तये । पयःपानं भुजङ्गानां केवलं विषवर्धनम् ॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>मूर्खाणां उपदेशः प्रकोपाय हि, न शान्तये । भुजङ्गानां पयःपानं केवलं विषवर्धनम् ॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>उपदेशः = उपबोधः; instruction;<br> मूर्खाणां = अविवेकिनां; of idiots;<br> प्रकोपाय = कोप-उद्दीपनाय; for fury, rage, violent anger;<br> न शान्तये = शमनाय; not for pacification;<br> पयःपानम् = दुग्धपानं; drinking milk;<br> भुजङ्गानां = सर्पाणां; of snake;<br> केवलं = तदेव नान्यत्; only;<br> विषवर्धनम् = गरलस्याधिक्य-कारणम्; causing poisongrowth</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>मूढानाम् उपबोधः निश्चयमेव कोपोपचयाय, न निर्वृतये। सर्पाणांदुग्धपानं केवलं गरलस्य संवर्धकम् ॥  <br>Instruction to the foolish leads to more violent anger than pacification. Snakes’ drinking milkonly serves to increase poison.</td>
                        </tr>
                        <tr class="prasnaa">
                            <td style="width: 90px">प्रश्नाः </td>
                            <td>१.किं प्रकोपाय? <br>२.किं विषवर्धनम्?  <br>३.‘प्रकोपाय’ इत्यत्र चतुर्थीविभक्तिः कथम्?  <br>४.‘विषवर्धनम्’ इत्यत्र समासविग्रहं वदत? <br>५.‘भुजङ्गानां’ इत्यस्य पदविश्लेषणं वदत? <br>६.------ भुजङ्गानां केवलं विषवर्धनम्। (रिक्तस्थानं पूरयत।)?</td>
                        </tr>
                        

                    </table>
                </div>
                    
