                    <div class="title">
                        57.कोऽन्धो योऽकार्यरतः
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम् </td>
                            <td>कोऽन्धो योऽकार्यरतः को बधिरो यो हितानि न शृणोति ।<br> को मूको यः काले प्रियाणि वक्तुं न जानाति ॥ --प्रश्नोत्तररत्नमालिका</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>कः अन्धः यः अकार्यरतः कः बधिरः यः हितानि न शृणोति । कः मूकः यः काले प्रियाणि वक्तुं न जानाति ।</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td></td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>कः = कः नरः; who;<br> अन्धः = दृष्टिहीनः; blind;<br> यः = यः नरः; one who;<br> अकार्यरतः = दुष्ट-पाप-निषिद्ध-हेय-कार्यं यः करोति; rejoices in improper, unworthy or bad act, a criminal or sinful action;<br> बधिरः = श्रवणशक्तिविहीनः; deaf;<br> हितानि = श्रेयस्कराणि वचांसि (उपदेशान्); good/ beneficial words;<br> न शृणोति = नाकर्णयति, आचरति वा; does not listen;<br> मूकः = वक्तुमसमर्थः,व्यक्तवाचः न वक्तुं पारयति यः; dumb;<br> काले = यथासमये; in time;<br> प्रियाणि = मनःप्रसादकारकाणिवचांसि; good words;<br> वक्तुं = भाषितुं; to speak;<br> न जानाति = नावबोधति; does not know</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>(अत्रअन्ध-बधिर-मूकानां नैतिकरीत्या निर्वचनं दीयते।) तादृशः पुरुषः दृष्टिहीनः, यः दुष्कार्याणि आचरति। श्रोतृहीनः तद्विधः यः भद्रप्रदवाक्यानि नावधारयति। स नरः वचनशक्तिहीनः यः समयोचितं मनःप्रशामकवचांसि वक्तुं न जानाति।  <br>Who is blind? He who is involved in bad actions. Who is deaf? He who does not listen to good advice. Who is dumb? He who cannot speak pleasant words at appropriate time.</td>
                        </tr>
                        <tr class="prasnaa">
                            <td style="width: 90px">प्रश्नाः </td>
                            <td>१.अन्धः कः? <br>२.कः मूकः?  <br>३.‘योऽकार्यरतः’ इत्यत्र सन्धिः विभज्यताम्। <br>४.यो ------ न शृणोति। (रिक्तस्थानं पूरयत।)?  <br>५.‘प्रियाणि’इत्यत्र द्वितीयाविभक्तिः कथम्?</td>
                        </tr>
                        

                    </table>
                </div>
                    
