                    <div class="title">
                        58.पूर्वजन्मकृतं कर्म 
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम् </td>
                            <td>पूर्वजन्मकृतं कर्म तद्दैवमिति कथ्यते ।<br> तस्मात् पुरूषकारेण यत्नं कुर्यादतन्द्रितः ॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>पूर्वजन्मकृतं कर्म तद् दैवम् इति कथ्यते ।तस्मात् पुरूषकारेण यत्नं कुर्याद् अतन्द्रितः ॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>पूर्वजन्मकृतं कर्म तद् दैवम् इति कथ्यते ।तस्मात् अतन्द्रितः पुरूषकारेण यत्नं कुर्याद् ॥   </td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>पूर्वजन्मकृतं = गते जन्मनि कृतं; done in previous births (life-times);<br> कर्म = आचरितं; action, deed(s);<br> तद् = तत्कर्म; that;<br> दैवम् = भाग्यं; luck, destiny, fate;<br> इति कथ्यते = एवं उच्यते; thus said;<br> तस्मात् = अतः; therefore;<br> अतन्द्रितः = आलस्येन, निद्रया वा विना; without being sleepy;<br> पुरूषकारेण = मानवप्रयत्नेन; by human effort;<br> यत्नं = प्रयत्नं; trial, attempt, endeavour;<br> कुर्याद् = आचरेत्; should be done</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>गते जन्मनि आचरितं कार्यमेवभाग्यम् इति उच्यते ।अतः पुरूषप्रयत्नेन अविच्छिन्नः प्रयत्नं कुर्यात् ॥  <br>The actions of previous birth are known as daiva (destiny). One should therefore make endeavours by human efforts without relaxation [to undo them].</td>
                        </tr>
                        <tr class="prasnaa">
                            <td style="width: 90px">प्रश्नाः </td>
                            <td>१.किं दैवमिति कथ्यते? <br>२.किं कथं च कुर्यात्? <br>३.‘पूर्वजन्मकृतं’ इत्यत्र समासविग्रहं वदत?  <br>४.‘तद्दैवमिति’ इत्यत्र सन्धिः विभज्यताम्। <br>५.यत्नं कुर्याद् ------। (रिक्तस्थानं पूरयत।)?</td>
                        </tr>
                        

                    </table>
                </div>
                    
