                    <div class="title">
                        59.दानेन तुल्यो विधिरस्ति 
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम् </td>
                            <td>दानेन तुल्यो विधिरस्ति नान्यो लोभाच्च नान्योऽस्ति रिपुः पृथिव्याम् ।<br> (पाठ. लोभान्न चान्योऽस्ति)  विभूषणं शीलसमं न चान्यत् सन्तोषतुल्यं धनमस्ति नान्यत् ॥ </td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>दानेन तुल्यः विधिः अस्ति न अन्यः लोभात्च न अन्यः अस्ति रिपुः पृथिव्याम्। विभूषणं शीलसमं च न अन्यत् सन्तोषतुल्यं धनम् अस्ति न अन्यत् ॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>दानेन तुल्यः विधिः न अन्यःअस्ति।पृथिव्याम् लोभात् च न अन्यः रिपुः अस्ति। शीलसमं विभूषणं न च अन्यत्। सन्तोषतुल्यं धनम् न अन्यत् अस्ति॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>दानेन तुल्यः = (धनादीनां) अस्वकरणेन समः; same as, similar, comparable to charity;<br> विधिः = विहितमाचरणं; ritual;<br> पृथिव्याम् = भूमौ; on earth;<br> लोभात् न अन्यः = अतिलिप्सायाः इतरः; nothing else than greed;<br> रिपुः = शत्रुः; enemy;<br> शीलसमं =; like character;<br> विभूषणं = आभूषणं; jewel, ornament;<br> सन्तोषतुल्यं = सन्तुष्ट्या समं; like happiness;<br> धनम् = वित्तं; money;<br> न अन्यत् = न इतरत्; nothing else;<br> अस्ति = वर्तते; is there</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>(धनकनकादीनाम् अन्येभ्यः) वितरणेन तुल्यं (महत्)कार्यं; अत्याकाङ्क्षायाः अन्यः अरिः; शीलमिव अलङ्कारः; सन्तुष्टिवत् वित्तं चधरायां न विद्यते। <br>There is no ritual equal to charity; there is no enemy other than greed on earth; there is no other ornament similar to good character; there is no other wealth same as contentment.</td>
                        </tr>
                        <tr class="prasnaa">
                            <td style="width: 90px">प्रश्नाः </td>
                            <td>१.केन तुल्यो विधिः नास्ति? <br>२.केन तुल्यं धनं नास्ति? <br>३.विभूषणं ------ न चान्यत् । (रिक्तस्थानं पूरयत।)? <br>४.‘शीलसमं’ इत्यत्र समासविग्रहं वदत? <br>५.‘लोभाच्च’ इत्यत्र सन्धिः विभज्यताम्। <br>६.‘नान्योऽस्ति’ इत्यत्र सन्धिः विभज्यताम्।</td>
                        </tr>
                        

                    </table>
                </div>
                    
                <div id="A" class="total">
                    <div>
