                    </div>
                    <div class="title">
                        a.संरोहत्यग्निना दग्धं 
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम् </td>
                            <td>संरोहत्यग्निना दग्धं वनं परशुना हतम् ।<br> (पाठ. रोहते सायकैर्विद्धं) वाचा दुरुक्तं बीभत्सं न संरोहति वाक्क्षतम् ॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>संरोहति अग्निना दग्धं वनं परशुना हतम् ।वाचा दुरुक्तं बीभत्सं न संरोहति वाक्क्षतम् ॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>वनं अग्निना दग्धं, परशुना हतं संरोहति।वाचा दुरुक्तं बीभत्सं वाक्क्षतम् न संरोहति ॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>वनं = अरण्यं; forest;<br> अग्निना = वह्निना; by fire;<br> दग्धं = ज्वलितं; burnt;<br> परशुना = छेदनपरिकरेण; by axe;<br> हतम् = मारितं; killed, destroyed;<br> संरोहति = प्रवर्धते; grows well;<br> वाचा = वचसा; by words;<br> दुरुक्तं = पीडाकारिवचनं; offensive speech, reproach, abuse, censure;<br> बीभत्सं = व्यवस्थाभङ्गः, दुष्परिणामः; loathsome;<br> वाक्क्षतम् = वचसा; wounded by words</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>पावकेन भस्मीकृतमपि, परशुना छिन्नमपि काननं पुनः प्ररोहति; किन्तु वाचा आहतं दुर्घटितं पुनः न साधु भवति।  <br>The forest burnt by fire or destroyed by axe grows again; but the mind wounded by [harsh] words will never be healed. पाठभेदः-- रोहते सायकैर्विद्धं वनं परशुना हतम् । वाचा दुरुक्तं बीभत्सं न संरोहति वाक्क्षतम् ॥महाभारतम्. १३.१०८.५८॥ पाठ. रोहते सायकैर्विद्धं - pāṭha. rohate sāyakairviddhaṃ; रोहते =; grows; सायकैः =; by arrows; विद्धं =; Pierced, penetrated; wounded, stabbed </td>
                        </tr>
                        <tr class="prasnaa">
                            <td style="width: 90px">प्रश्नाः </td>
                            <td>१.किं संरोहति? <br>२.किं न संरोहति? <br>३.‘संरोहत्यग्निना’ इत्यत्र सन्धिः विभज्यताम्।  <br>४.‘वाक्क्षतम्’ इत्यत्र समासविग्रहं वदत?  <br>५.‘बीभत्सं’ इत्यस्य पदविश्लेषणं वदत?  <br>६.‘वाचा’ इत्यत्र तृतीयाविभक्तिः कथम्?</td>
                        </tr>
                        

                    </table>
                </div>
                    
                <div id="60" class="total">
                    <div>
                        <button id="moolamsmall60" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('moolam', '60')">मूलम्</button>
                        <button id="padasmall60" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '60')">पदविभागः</button>
                        <button id="anvayasmall60" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '60')">अन्वयः</button>
                        <button id="pratismall60" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '60')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall60" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '60')">तात्पर्यम्</button>
                        <button id="vyakyaasmall60" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('vyakyaa', '60')">वाक्याभ्यासः</button>
                        <button id="prasnaasmall60" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prasnaa', '60')">प्रश्नाः</button>
                    </div>
                    <div class="title">
                        60.अहो दुर्जनसंसर्गात् 
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम् </td>
                            <td>अहो दुर्जनसंसर्गात् मानहानिः पदे पदे ।<br> पावको लोहसङ्गेन मुद्गरैरभिताड्यते ॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>अहो, दुर्जनसंसर्गात् मानहानिः पदे पदे । पावकः लोहसङ्गेन मुद्गरैः अभिताड्यते ॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>अहो, दुर्जनसंसर्गात् पदे पदे मानहानिः। पावकः लोहसङ्गेन मुद्गरैः अभिताड्यते ॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>अहो = धिक्; oh;<br> दुर्जनसंसर्गात् = दुष्टजनानां साङ्गत्यात्; by association of wicked;<br> पदे पदे = सर्वदा, सर्वत्र; in every step;<br> मानहानिः = आत्माभिमानस्य क्षतिः; humiliation, mortification, insult, indignity;<br> पावकः = अग्निः; fire;<br> लोहसङ्गेन = अयःसाङ्गत्येन; in (lit. by) company of iron;<br> मुद्गरैः = द्रुघणैः, अयोघनैः; by hammers;<br> अभिताड्यते = अभिहन्यते; is beat, hit</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>धिक्, कुबुद्धीनां सङ्गतौ गते सति, पदे पदे आत्मसंमाननस्य अपायः घटते। अयःपिण्डेन साकं भूत्वा वह्निरपि लोष्ठभेदकैः निहन्यते। <br>There is insult at every step when in company of wicked. Fire is hit well with hammers when it associates with iron.</td>
                        </tr>
                        <tr class="prasnaa">
                            <td style="width: 90px">प्रश्नाः </td>
                            <td>१.केन मानहानिः? <br>२.कः केन कैः अभिताड्यते? <br>३.‘दुर्जनसंसर्गात्’ इत्यत्र समासविग्रहं वदत? <br>४.‘मुद्गरैरभिताड्यते’ इत्यत्र सन्धिः विभज्यताम्। <br>५.दुर्जनसंसर्गात् ------ पदे पदे। (रिक्तस्थानं पूरयत।)? <br>६.‘पावकः’ इत्यस्य पदविश्लेषणं वदत?</td>
                        </tr>
                        

                    </table>
                </div>
                    
                <div id="61" class="total">
                    <div>
