                        <button id="padasmall61" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '61')">पदविभागः</button>
                        <button id="anvayasmall61" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '61')">अन्वयः</button>
                        <button id="pratismall61" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '61')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall61" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '61')">तात्पर्यम्</button>
                        <button id="vyakyaasmall61" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('vyakyaa', '61')">वाक्याभ्यासः</button>
                        <button id="prasnaasmall61" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prasnaa', '61')">प्रश्नाः</button>
                    </div>
                    <div class="title">
                        61.माता मित्रं पिता चेति 
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम् </td>
                            <td>माता मित्रं पिता चेति स्वभावात् त्रितयं हितम् ।<br> कार्यकारणतश्चान्ये भवन्ति हितबुद्धयः ॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>माता मित्रं पिता च इति स्वभावात् त्रितयं हितम् ।कार्यकारणतः च अन्ये भवन्ति हितबुद्धयः ॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>माता मित्रं पिता च इति स्वभावात् त्रितयं हितम् । अन्ये च कार्यकारणतः हितबुद्धयः भवन्ति ॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>माता = अम्बा; mother;<br> मित्रं = सखा; friend;<br> पिता = जनकः; father;<br> च इति = च; and thus;<br> स्वभावात् = प्रकृत्या; by nature;<br> त्रितयं = त्रयः; three-some;<br> हितम् = श्रेयः; benefit, welfare;<br> अन्ये च = इतरे; and others;<br> कार्यकारणतः = व्यापारकारणेन; on purpose of [some] work;<br> हितबुद्धयः = उपकारपराः; having sense of welfare, a well-wisher;<br> भवन्ति = वर्तन्ते; they are</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>जननी-जनकौ, सुहृदश्च (अकृत्रिमं) प्रकृत्या श्रेयःकारकाः भवन्ति। इतरे सर्वे केनचित् कार्यादिव्याजेन अनुग्रहपराः भवन्ति। <br>Mother, father, and friend- these three are benefitial by nature; others become well wishers on purpose of [some] work.</td>
                        </tr>
                        <tr class="prasnaa">
                            <td style="width: 90px">प्रश्नाः </td>
                            <td>१.किं त्रितयं हितम्? <br>२.अन्ये कीदृशाः?  <br>३.‘कार्यकारणतश्चान्ये’ इत्यत्र सन्धिः विभज्यताम्।  <br>४.‘हितबुद्धयः’ इत्यत्र समासविग्रहं वदत? <br>५.‘कार्यकारणतः’ इत्यत्र समासविग्रहं वदत?  <br>६.‘स्वभावात्’ इत्यस्य पदविश्लेषणं वदत?</td>
                        </tr>
                        

                    </table>
                </div>
                    
                <div id="62" class="total">
                    <div>
                        <button id="moolamsmall62" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('moolam', '62')">मूलम्</button>
                        <button id="padasmall62" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '62')">पदविभागः</button>
                        <button id="anvayasmall62" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '62')">अन्वयः</button>
                        <button id="pratismall62" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '62')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall62" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '62')">तात्पर्यम्</button>
                        <button id="vyakyaasmall62" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('vyakyaa', '62')">वाक्याभ्यासः</button>
                        <button id="prasnaasmall62" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prasnaa', '62')">प्रश्नाः</button>
                    </div>
                    <div class="title">
                        62.विवेकः सह संपत्त्या 
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम् </td>
                            <td>विवेकः सह सम्पत्त्या विनयो विद्यया सह ।<br> प्रभुत्वं प्रश्रयोपेतं चिह्नमेतन्महात्मनाम् ॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>विवेकः सह सम्पत्त्या विनयः विद्यया सह । प्रभुत्वं प्रश्रय–उपेतं चिह्नम् एतत् महात्मनाम् ॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>विवेकः सम्पत्त्या सह, विनयः विद्यया सह, प्रभुत्वं प्रश्रय–उपेतं, एतत् महात्मनाम् चिह्नम्॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>विवेकः = याथार्थ्येन वस्तु-स्वरूपावधारणं; discriminating (between two things), consideration;<br> सम्पत्त्या सह = धनातिरिच्येन साकं; along with wealth;<br> विनयः = अगर्वः; humbleness;<br> विद्यया सह = ज्ञानेन साकं; along with learning;<br> प्रभुत्वं = अधिकारः; command, power;<br> प्रश्रय–उपेतं = सौजन्ययुक्तं; endowed with respect, courtesy, civility, politeness;<br> एतत् = इदं; this;<br> महात्मनाम् = उत्तमजनानां; of great people;<br> चिह्नम् = लक्षणम्; mark, symbol</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>धनाधिक्येन सह विवेचनं, ज्ञानेन साकं निरभिमानित्वं, आधिपत्येन सार्धं अनौद्धत्यं च सत्पुरुषाणां लक्ष्म भवति। <br>Consideration with wealth, humbleness with scholarship, (and) power with politeness- these are the indications of the noble.</td>
                        </tr>
                        <tr class="prasnaa">
                            <td style="width: 90px">प्रश्नाः </td>
                            <td>१.सम्पत्त्या कोऽपेक्षितः? <br>२.विनयः केनापेक्षितः? <br>३.किं महात्मनां चिह्नम्?  <br>४.प्रभुत्वं ------। (रिक्तस्थानं पूरयत।) ?  <br>५.‘चिह्नमेतन्महात्मनाम्’ इत्यत्र सन्धिः विभज्यताम्।  <br>६.‘प्रश्रयोपेतं’ इत्यत्र समासविग्रहं वदत?</td>
                        </tr>
                        

                    </table>
                </div>
                    
