                        <button id="padasmall63" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '63')">पदविभागः</button>
                        <button id="anvayasmall63" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '63')">अन्वयः</button>
