                    </div>
                    <div class="title">
                        63.षड् दोषाः पुरूषेणेह 
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम् </td>
                            <td>षड्दोषाः पुरूषेणेह हातव्या भूतिमिच्छता ।<br> निद्रा तन्द्रा भयं क्रोध आलस्यं दीर्घसूत्रता ॥ (पाठ. तन्द्रीर्भयं)</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>षड्-दोषाः पुरूषेण इह हातव्या भूतिम् इच्छता ।निद्रा तन्द्रा भयं क्रोधः आलस्यं दीर्घसूत्रता ॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>भूतिम् इच्छता पुरूषेण इह षड्-दोषाः हातव्या ।निद्रा तन्द्रा भयं क्रोधः आलस्यं दीर्घसूत्रता ॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>भूतिम् = विभवं; prosperity;<br> इच्छता = प्राप्तुकामेन; by the one who desires;<br> पुरूषेण = नरेण; by the man;<br> इह = अत्र, तावत्; here;<br> षड्-दोषाः = षट्-सङ्ख्यामिताः अपचयाः; six faults, defects, weak points;<br> हातव्या = निरोद्धव्याः; should be killed;<br> निद्रा = शयनं; sleep;<br> तन्द्रा = ईषन्निद्रा; sluggishness, indisposed to action or exertion. lacking in energy, lazy, indolent;<br> भयं = भीतिः; fear;<br> क्रोधः = कोपः; anger, rage;<br> आलस्यं = मन्दत्वं; laziness;<br> दीर्घसूत्रता = अव्यवसायशीलत्वं; keeping works pending (working slowly, slow, dilatory, procrastinating)</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>यः वैभवमिच्छति, तेन नरेण तावत् षड्-दोषाः अपाकर्तव्याः।ते दोषाः-- (अति)शयनं, कार्यद्वेषः,धैर्यराहित्यं,शान्तिराहित्यं, मन्दत्वं, चिरक्रियता च।  <br>One, who wishes to prosper in this world, should get rid of the following six faults too much sleep, lethargy, fear, anger, laziness, and procrastination.</td>
                        </tr>
                        <tr class="prasnaa">
                            <td style="width: 90px">प्रश्नाः </td>
                            <td>१.के षड्दोषाः?  <br>२.षड्दोषाः केन हातव्याः? <br>३.‘षड्दोषाः’ इत्यत्र सन्धिः विभज्यताम्।  <br>४.‘दीर्घसूत्रता’ इत्यत्र समासविग्रहं वदत? <br>५.षड्दोषाः ------ हातव्याः। (रिक्तस्थानं पूरयत।)?  <br>६.‘पुरुषेण’ इत्यत्र तृतीयाविभक्तिः कथम्?</td>
                        </tr>
                        

                    </table>
                </div>
                    
                <div id="64" class="total">
                    <div>
