                        <button id="padasmall64" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '64')">पदविभागः</button>
                        <button id="anvayasmall64" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '64')">अन्वयः</button>
                        <button id="pratismall64" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '64')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall64" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '64')">तात्पर्यम्</button>
                        <button id="vyakyaasmall64" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('vyakyaa', '64')">वाक्याभ्यासः</button>
                        <button id="prasnaasmall64" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prasnaa', '64')">प्रश्नाः</button>
                    </div>
                    <div class="title">
                        64.विद्या ददाति विनयं 
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम् </td>
                            <td>विद्या ददाति विनयं विनयाद्याति पात्रताम् ।<br> पात्रत्वाद्धनमाप्नोति धनाद्धर्मस्ततः सुखम् ॥ </td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>विद्या ददाति विनयं विनयात् याति पात्रताम् ।पात्रत्वात् धनम् आप्नोति धनात् धर्मः ततः सुखम् ॥ </td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>विद्या विनयं ददाति। विनयात् पात्रताम् याति।पात्रत्वात् धनम् आप्नोति। धनात् धर्मः ततः सुखम् (च आप्नोति)॥ </td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>विद्या = ज्ञानं; education;<br> विनयं = अगर्वः; humbleness;<br> ददाति = प्रददाति; gives, bestows;<br> विनयात् = अगर्वात्; from humbleness;<br> पात्रताम् = योग्यतां; eligibility;<br> याति = प्राप्नोति; reaches;<br> पात्रत्वात् = योग्यतायाः; from eligibility;<br> धनम् = वित्तं; money;<br> आप्नोति = अर्जति; obtains;<br> धनात् = वित्तात्; from money;<br> धर्मः = पुण्यकर्माणि; merit;<br> ततः = तस्मात्; thence, from that;<br> सुखम् = आनन्दं; happiness</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>ज्ञानेनअगर्वम्, अगर्वेण योग्यतां, योग्यतायाःवित्तं, वित्तेन धर्माचरणं, धर्माचरणेन च आनन्दं प्राप्नोति नरः ।  <br>Knowledge brings in humbleness; by humbleness one reaches eligibility; by eligibility, one obtains wealth; wealth brings in [ability to do] good deeds/merit [helps in indulging in (religious) meritorious activities]; from that arises happiness.</td>
                        </tr>
                        <tr class="prasnaa">
                            <td style="width: 90px">प्रश्नाः </td>
                            <td>१.विद्या किं ददाति?  <br>२.केन सुखमाप्नोति?  <br>३.‘पात्रत्वाद्धनमाप्नोति’ इत्यत्र सन्धिः विभज्यताम्।  <br>४.‘धनाद्धर्मस्ततः’इत्यत्र सन्धिः विभज्यताम्।   <br>५.‘विनयात्’ इत्यत्र पञ्चमीविभक्तिः कथम्?  <br>६.------ पात्रताम्। (रिक्तस्थानं पूरयत।)?</td>
                        </tr>
                        

                    </table>
                </div>
                    
                <div id="65" class="total">
                    <div>
