                        <button id="padasmall65" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '65')">पदविभागः</button>
                        <button id="anvayasmall65" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '65')">अन्वयः</button>
                        <button id="pratismall65" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '65')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall65" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '65')">तात्पर्यम्</button>
                        <button id="vyakyaasmall65" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('vyakyaa', '65')">वाक्याभ्यासः</button>
                        <button id="prasnaasmall65" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prasnaa', '65')">प्रश्नाः</button>
                    </div>
                    <div class="title">
                        65.न विश्वसेत् कुमित्रे 
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम् </td>
                            <td>न विश्वसेत् कुमित्रे च मित्रे चापि न विश्वसेत्।<br> (पाठ. अविश्वस्ते) कदाचित् कुपितं मित्रं गुप्तं दोषं प्रकाशयेत्॥ </td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>न विश्वसेत् कुमित्रे च मित्रे च अपि न विश्वसेत्। कदाचित् कुपितं मित्रं गुप्तं दोषं प्रकाशयेत्॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>कुमित्रे न विश्वसेत्। (न) च मित्रे च अपि विश्वसेत्। कदाचित् कुपितं मित्रं गुप्तं दोषं प्रकाशयेत्॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>कुमित्रे = दुष्टमित्रे; in bad friend;<br> न विश्वसेत् = विश्वासं न कुर्यात्; should not trust in;<br> मित्रे = (सन्)मित्रे; in friend;<br> च अपि = च; also, as well;<br> कदाचित् = कस्मिंश्चित् समये; at some time or other;<br> कुपितं = कोपं प्राप्तं; angry;<br> गुप्तं = गुह्यविषयं, रहस्यं; private, secret;<br> दोषं = असाध्वंशं, प्रमादघटितं वा; fault, defect;<br> प्रकाशयेत् = अन्यान् वदेत्; disclose, unfold, bring out</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>दुष्टे सखायां न विश्वासः कार्यः। सन्मित्रोऽपिन विश्वासयोग्यः। कदाचित् यदि मित्रं कुपितं भवति, तेन गोपनीयविषयाः, अपराधाः प्रकाशिता भवेयुः॥  <br>One should not trust in bad friend and not even a friend as well. At some point of time, the angry friend might disclose [our] secret faults.</td>
                        </tr>
                        <tr class="prasnaa">
                            <td style="width: 90px">प्रश्नाः </td>
                            <td>१.कस्मिन् कस्मिन् न विश्वसेत्?  <br>२.कुतः न विश्वसेत्?  <br>३.‘प्रकाशयेत्’ इत्यस्य पदविश्लेषणं वदत?    <br>४.मित्रे चापि न ------। (रिक्तस्थानं पूरयत।)?  <br>५.‘कुमित्रे’ इत्यत्र केन सप्तमी?</td>
                        </tr>
                        

                    </table>
                </div>
                    
                <div id="66" class="total">
                    <div>
                        <button id="moolamsmall66" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('moolam', '66')">मूलम्</button>
                        <button id="padasmall66" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '66')">पदविभागः</button>
                        <button id="anvayasmall66" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '66')">अन्वयः</button>
                        <button id="pratismall66" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '66')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall66" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '66')">तात्पर्यम्</button>
                        <button id="vyakyaasmall66" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('vyakyaa', '66')">वाक्याभ्यासः</button>
                        <button id="prasnaasmall66" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prasnaa', '66')">प्रश्नाः</button>
                    </div>
                    <div class="title">
                        66.शाठ्येन मित्रं कपटेन 
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम् </td>
                            <td>शाठ्येन मित्रं कपटेन धर्मं परोपतापेन समृद्धभावम् ।<br> सुखेन विद्यां परुषेण नारीं वाञ्छन्ति ये नूनमपण्डितास्ते ॥ -सुभाषितसुधानिधिः</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>शाठ्येन मित्रं कपटेन धर्मं परोपतापेन समृद्धभावम् । सुखेन विद्यां परुषेण नारीं वाञ्छन्ति ये नूनम् अपण्डिताः ते॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>ये शाठ्येन मित्रं (वाञ्छन्ति), कपटेन धर्मं (वाञ्छन्ति), परोपतापेन समृद्धभावम् (वाञ्छन्ति) सुखेन विद्यां  (वाञ्छन्ति) परुषेण नारीं वाञ्छन्ति, ते नूनम् अपण्डिताः ॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>ये = ये जनाः; those who;<br> शाठ्येन = धूर्तत्वेन; by deceit, fraud;<br> मित्रं = सुहृत्; friend;<br> कपटेन = छलेन; by trick, cheating;<br> धर्मं = पुण्याचरणं; merit;<br> परोपतापेन = इतरेषां पीडनेन; by causing trouble, distress, pain, sorrow to others;<br> समृद्धभावम् = सम्पत्तिं; Prosperity, abundance;<br> सुखेन = आनन्देन; by comfort;<br> विद्यां = ज्ञानं; knowledge;<br> परुषेण = रूक्षव्यवहारेण; by hardness, roughness;<br> नारीं = महिलां; woman;<br> वाञ्छन्ति = इच्छन्ति; (they) desire;<br> ते = ते जनाः; they;<br> नूनम् = निश्चयं; certainly;<br> अपण्डिताः = अविवेकिनः; foolish, ignorant</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>ये जनाः वञ्चनया सखायं प्राप्तुमिच्छन्ति, दम्भेन (प्रतारणेन) शुभादृष्टम्, अन्येषाम् अशुभकरणेन अतिशयसम्पत्तिं, सुखमुषित्वा विद्यां, निष्ठुरतया स्त्रियं च लब्धुमिच्छन्ति, ते जनाः निश्चयेन मूर्खाः।  <br>They are fools- who desire to get friend by deceit, earn dharma by cheating, achieve prosperity by troubling others, attain learning by comfort, win woman by harshness.</td>
                        </tr>
                        <tr class="prasnaa">
                            <td style="width: 90px">प्रश्नाः </td>
                            <td>१.के अपण्डिताः? <br>२.अपण्डिताः केन समृद्धभावं वाञ्छन्ति? <br>३.‘शाठ्येन’ इत्यत्र तृतीयाविभक्तिः कथम्?  <br>४.‘समृद्धभावम्’ इत्यत्र समासविग्रहं वदत? <br>५.‘नूनमपण्डितास्ते’ इत्यत्र सन्धिः विभज्यताम्। <br>६.------ ये नूनमपण्डितास्ते। (रिक्तस्थानं पूरयत।)?</td>
                        </tr>
                        

                    </table>
                </div>
                    
                <div id="67" class="total">
                    <div>
                        <button id="moolamsmall67" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('moolam', '67')">मूलम्</button>
                        <button id="padasmall67" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '67')">पदविभागः</button>
                        <button id="anvayasmall67" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '67')">अन्वयः</button>
                        <button id="pratismall67" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '67')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall67" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '67')">तात्पर्यम्</button>
                        <button id="vyakyaasmall67" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('vyakyaa', '67')">वाक्याभ्यासः</button>
                        <button id="prasnaasmall67" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prasnaa', '67')">प्रश्नाः</button>
                    </div>
                    <div class="title">
                        67.सन्तोषः परमो लाभः 
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम् </td>
                            <td>सन्तोषः परमो लाभः सत्सङ्गः परमा गतिः।<br> विचारः परमं ज्ञानं शमो हि परमं सुखम्॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>सन्तोषः परमः लाभः सत्सङ्गः परमा गतिः। विचारः परमं ज्ञानं शमः हि परमं सुखम्॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td></td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>सन्तोषः = सन्तुष्टिः; Satisfaction, contentment;<br> परमः = उन्नतः, उत्कृष्टः; greatest, utmost;<br> लाभः = उपकारः; acquisition, obtaining, gain;<br> सत्सङ्गः = उत्तमानां सङ्गतिः; company of the good;<br> गतिः = मार्गः; means, expedient, course, alternative;<br> विचारः = चिन्तनं; Reflection, deliberation, thought, consideration;<br> ज्ञानं = अवबोधः; knowledge;<br> शमः = शान्तिः; Quiet, tranquility, calmness;<br> हि = अवश्यं; indeed;<br> सुखम् = आनन्दः; happiness, comfort</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>सन्तुष्टिः उत्कृष्टः लाभः; सतां साहचर्यं उत्तमो गमनमार्गः; चिन्तनं सर्वोन्नतं समधिगमः; शान्तिः परमं सुखम्।  <br>Satisfaction is the highest gain; company of the good- utmost means.Thinking [deep] is the supreme wisdom, and calmness, the excellent enjoyment.</td>
                        </tr>
                        <tr class="prasnaa">
                            <td style="width: 90px">प्रश्नाः </td>
                            <td>१.कः परमो लाभः?  <br>२.कः परमा गतिः?  <br>३.------ परमं ज्ञानं। (रिक्तस्थानं पूरयत।)?  <br>४.‘सत्सङ्गः’ इत्यस्य पदविश्लेषणं वदत? <br>५.शमो हि परमं सुखम्—अत्र लिङ्गप्रयोगविशेषं वदत?</td>
                        </tr>
                        

                    </table>
                </div>
                    
