                    </div>
                    <div class="title">
                        68.कुलं वित्तं श्रुतं 
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम् </td>
                            <td>कुलं वित्तं श्रुतं रूपं शौर्यं दानम् तपस्तथा।<br> प्राधान्येन मनुष्याणां सप्तैते मदहेतवः॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>कुलं वित्तं श्रुतं रूपं शौर्यं दानम् तपः तथा। प्राधान्येन मनुष्याणाम् सप्त एतेमदहेतवः॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>कुलं वित्तं श्रुतं रूपं शौर्यं दानम् तथा तपः- प्राधान्येन एते सप्त मनुष्याणाम् मदहेतवः॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>कुलं = कुटुम्बः, वंशः; family, clan;<br> वित्तं = अर्थः, धनं; money;<br> श्रुतं = ज्ञानं; knowledge;<br> रूपं = सौन्दर्यं; beauty;<br> शौर्यं = वीरत्वं; valour;<br> दानम् = वितरणं; charity;<br> तपः = कायक्लेशनपूर्वकः इष्टसिद्ध्यर्थकः प्रयत्नः; penance;<br> तथा = तत्समानं, इव; and;<br> प्राधान्येन = मुख्यरूपेण; chiefly;<br> मनुष्याणाम् = नराणाम्; of men;<br> सप्त एते = सप्तसङ्ख्याविशिष्टाः; these seven;<br> मदहेतवः = गर्वस्य अथवा हर्षकारणानि; causes of arrogance, Intoxication</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>(उत्तम)वंशः (तत्र जन्मलाभः), (प्रभूतं)धनं, (विपुलं) ज्ञानं, (अतिशयितं) लावण्यं, (अत्यर्थः) पराक्रमः, (भूयिष्ठं धनादीनां) अस्वकरणं, (महत् च) तपस्या— इत्येते नरे आमोदस्य कारणानि भवन्ति।  <br>Family, wealth, education, beauty, valour, charity and penance are primarily the seven reasons for arrogance of the people.</td>
                        </tr>
                        <tr class="prasnaa">
                            <td style="width: 90px">प्रश्नाः </td>
                            <td>१.के केषां मदहेतवः?  <br>२.‘सप्तैते’ इत्यत्र सन्धिः विभज्यताम्।  <br>३.‘प्राधान्येन’ इत्यत्र तृतीयाविभक्तिः कथम्? <br>४.‘मदहेतवः’ इत्यत्र समासविग्रहं वदत?  <br>५.------ सप्तैते मदहेतवः। (रिक्तस्थानं पूरयत।)?  <br>६.‘तपस्तथा’ इत्यत्र सन्धिः विभज्यताम्।</td>
                        </tr>
                        

                    </table>
                </div>
                    
                <div id="69" class="total">
                    <div>
