                        <button id="padasmall69" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '69')">पदविभागः</button>
                        <button id="anvayasmall69" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '69')">अन्वयः</button>
                        <button id="pratismall69" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '69')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall69" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '69')">तात्पर्यम्</button>
                        <button id="vyakyaasmall69" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('vyakyaa', '69')">वाक्याभ्यासः</button>
                        <button id="prasnaasmall69" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prasnaa', '69')">प्रश्नाः</button>
                    </div>
                    <div class="title">
                        69.अभ्यासाद्धार्यते विद्या 
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम् </td>
                            <td>अभ्यासाद्धार्यते विद्या कुलं शीलेन धार्यते।<br> गुणैर्मित्राणि धार्यन्ते अक्ष्णा क्रोधश्च धार्यते॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>अभ्यासात् धार्यते विद्या कुलं शीलेन धार्यते। गुणैः मित्राणि धार्यन्ते अक्ष्णा क्रोधः च धार्यते॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>अभ्यासात् विद्या धार्यते। कुलं शीलेन धार्यते। गुणैः मित्राणि धार्यन्ते। अक्ष्णा क्रोधः च धार्यते॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>अभ्यासात् = पुनः पुनः आचरणात्; by practice;<br> विद्या = ज्ञानं; knowledge;<br> धार्यते = अवलम्ब्यते; is maintained, preserved, sustained;<br> कुलं = कुटुम्बः, वंशः; family, clan;<br> शीलेन = चरित्रेण; by (good) character;<br> गुणैः = आन्तरिक/अन्तःप्रवृत्तिलक्षणैः; by (good) qualities;<br> मित्राणि = सुहृदः; friends;<br>  अक्ष्णा = चक्षुषा; by eye;<br> क्रोधः = कोपोद्वेगः; anger</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>पौनः पुन्येन अनुष्ठानेन (अर्जितं)ज्ञानम् आधीयते। वंशः सच्चरित्रेन आश्रियते। सखायः स्वभावलक्षणैः परिगृह्यन्ते। कोपः नयनेन धार्यते।  <br>Knowledge is sustained by practice; family or clan runs by conduct; friendship is kept by good qualities; anger is held by eye.</td>
                        </tr>
                        <tr class="prasnaa">
                            <td style="width: 90px">प्रश्नाः </td>
                            <td>१.का अभ्यासाद्धार्यते?  <br>२.अक्ष्णा कः धार्यते?  <br>३.‘धार्यन्ते’ इत्यस्य पदविश्लेषणं वदत?  <br>४.‘अभ्यासाद्धार्यते’ इत्यत्र सन्धिः विभज्यताम्।  <br>५.‘गुणैर्मित्राणि’ इत्यत्र सन्धिः विभज्यताम्।  <br>६.‘अक्ष्णा’ इत्यत्र तृतीयाविभक्तिः कथम्?</td>
                        </tr>
                        

                    </table>
                </div>
                    
                <div id="70" class="total">
