                        <button id="padasmall70" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '70')">पदविभागः</button>
                        <button id="anvayasmall70" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '70')">अन्वयः</button>
                        <button id="pratismall70" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '70')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall70" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '70')">तात्पर्यम्</button>
                        <button id="vyakyaasmall70" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('vyakyaa', '70')">वाक्याभ्यासः</button>
                        <button id="prasnaasmall70" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prasnaa', '70')">प्रश्नाः</button>
                    </div>
                    <div class="title">
                        70.लोभमूलानि पापानि 
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम् </td>
                            <td>लोभमूलानि पापानि सङ्कटानि तथैव च ।<br> लोभात्प्रवर्तते वैरं अतिलोभात् विनश्यति ॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>लोभमूलानि पापानि सङ्कटानि तथैव च ।लोभात् प्रवर्तते वैरं अतिलोभात् विनश्यति ॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>लोभमूलानि पापानि सङ्कटानि तथैव च ।लोभात् प्रवर्तते वैरं अतिलोभात् विनश्यति ॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>लोभमूलानि = अतिलिप्सा-कृतानि; caused by greed, avarice. (lit. having roots in covetousness);<br> पापानि = दुरितानि; Sins, crimes, vices;<br> सङ्कटानि = विषमस्थितयः; difficulties, risks, perils, dangers;<br> तथैव च = तत्समानं; also, similarly;<br> लोभात् = अत्याकाङ्क्षातः; from greed;<br> वैरं = शत्रुभावः; enmity;<br> प्रवर्तते = प्ररोहति; arises, happens, begins;<br> अतिलोभात् = अतिशयित-लौल्यात्; because of extreme greed;<br> विनश्यति = क्षयं गच्छति; one perishes, is destroyed</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>पातकानि, कष्टस्थितयः च अतिलिप्साकारणेन भवन्ति। लुब्धत्वात् अरिभावः जायते। अतिगृध्नत्वेन (नरः) विनाशमेति।  <br>Sins and adversities are caused by greed.Enmity arises from greed. And one is destroyed because of extreme greed. </td>
                        </tr>
                        <tr class="prasnaa">
                            <td style="width: 90px">प्रश्नाः </td>
                            <td>१.कानि लोभमूलानि?  <br>२.अतिलोभात् किं भवति?  <br>३.------ प्रवर्तते वैरं। (रिक्तस्थानं पूरयत।)?  <br>४.‘लोभात्’ इत्यत्र पञ्चमीविभक्तिः कथम्? <br>५.‘लोभमूलानि’ इत्यत्र समासविग्रहं वदत? <br>६.‘सङ्कटानि’ इत्यस्य पदविश्लेषणं वदत?</td>
                        </tr>
                        

                    </table>
                </div>
                    
                <div id="71" class="total">
                    <div>
                        <button id="moolamsmall71" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('moolam', '71')">मूलम्</button>
                        <button id="padasmall71" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '71')">पदविभागः</button>
                        <button id="anvayasmall71" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '71')">अन्वयः</button>
                        <button id="pratismall71" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '71')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall71" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '71')">तात्पर्यम्</button>
                        <button id="vyakyaasmall71" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('vyakyaa', '71')">वाक्याभ्यासः</button>
                        <button id="prasnaasmall71" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prasnaa', '71')">प्रश्नाः</button>
                    </div>
                    <div class="title">
                        71.एकवर्णं यथा दुग्धं 
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम् </td>
                            <td>एकवर्णं यथा दुग्धं भिन्नवर्णासु धेनुषु ।<br> तथैव धर्मवैचित्र्यं तत्त्वमेकं परं स्मृतम् ॥(पाठ. तथा धर्मस्य वैचित्र्ये [..] पुनः) </td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td></td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>एकवर्णं यथा दुग्धं भिन्नवर्णासु धेनुषु तथा एव धर्म-वैचित्र्यं तत्त्वम् एकं परं स्मृतम् ॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>एकवर्णं = एकरङ्गकं; one colour;<br> यथा = यत्प्रकारकं; same as;<br> दुग्धं = क्षीरं; milk;<br> भिन्नवर्णासु = असदृश-रङ्गकेषु; in different coloured;<br> धेनुषु = गोषु; in cows;<br> तथा एव = वत्; likewise;<br> धर्म-वैचित्र्यं = धर्मस्य वैविध्यं; variety, diversity of dharma ( = prescribed course of conduct, ordinance, customary observances);<br> तत्त्वम् = सारः; true or essential nature;<br> एकं = समानं; one;<br> परं = अत्यन्तोत्कृष्टं; ultimate, highest point;<br> स्मृतम् = उक्तम्; regarded, laid down, recorded, mentioned</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>येन प्रकारेण विविधरङ्गकेषु गोषु पयः एकवर्णकं, तथैव धर्मे वैविध्यं भवति, किन्तु तत्त्वं तु समानं, सर्वोन्नतं च उच्यते। <br>The milk is of the same colour (that comes out from) in different coloured cows; likewise [though] there is diversity in dharma, its essential nature is ultimately regarded one.</td>
                        </tr>
                        <tr class="prasnaa">
                            <td style="width: 90px">प्रश्नाः </td>
                            <td>१.दुग्धं कीदृशम्?  <br>२.धर्मवैचित्र्यं कीदृशम्?  <br>३.‘तथैव’ इत्यत्र सन्धिः विभज्यताम्। <br>४.‘भिन्नवर्णासु’ इत्यत्र समासविग्रहं वदत?    <br>५.------ परं स्मृतम्। (रिक्तस्थानं पूरयत।)?  <br>६.‘वैचित्र्यं’ इत्यस्य पदविश्लेषणं वदत?</td>
                        </tr>
                        

                    </table>
                </div>
                    
                <div id="72" class="total">
                    <div>
                        <button id="moolamsmall72" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('moolam', '72')">मूलम्</button>
                        <button id="padasmall72" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '72')">पदविभागः</button>
                        <button id="anvayasmall72" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '72')">अन्वयः</button>
                        <button id="pratismall72" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '72')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall72" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '72')">तात्पर्यम्</button>
                        <button id="vyakyaasmall72" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('vyakyaa', '72')">वाक्याभ्यासः</button>
                        <button id="prasnaasmall72" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prasnaa', '72')">प्रश्नाः</button>
                    </div>
                    <div class="title">
                        72.ते पुत्रा ये पितुर्भक्ताः 
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम् </td>
                            <td>ते पुत्रा ये पितुर्भक्ताः सः पिता यस्तु पोषकः।<br> तन्मित्रं यत्र विश्वासः सा भार्या यत्र निर्वृतिः॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>ते पुत्राः ये पितुः भक्ताः सः पिता यस्तु पोषकः। तत् मित्रं यत्र विश्वासः सा भार्या यत्र निर्वृतिः॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td></td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>ते पुत्राः ये = तादृशाः जनाः एव पुत्रत्वेन मन्यन्तेयादृशाः; those (are) sons who;<br> पितुः = जनकस्य; of father;<br> भक्ताः = श्रद्धा-सद्भाव-युक्ताः; attentive (to), attached (to) [Lit. devotees];<br> सः पिता = तादृशः एव जनकत्वेन आद्रियते; he (is) father;<br> यः तु = यादृशस्तु; who indeed;<br> पोषकः = पोषयति; One who maintains or nourishes, a supporter;<br>  तत् मित्रं = तादृशं मित्रमिति वक्तुं शक्यते; that is friend;<br> यत्र विश्वासः = यस्मिन्; where there is trust;<br> सा भार्या = तादृशी एव पत्नीत्वेन तिष्ठति; that (lit. she) is a wife;<br> यत्र निर्वृतिः = यस्यां शान्तिः प्राप्यते; satisfaction, tranquillity, rest, repose</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>ये पुत्राः पितरि श्रद्धासद्भावयुक्ताः भवन्ति, ते एव (वस्तुतः) पुत्राः (इति नामभाजः)। यः पिता (पुत्रादीन्) सुष्ठु पोषयति, स एव पितृशब्दाय युक्तः। स एव सुहृत्त्वेन व्यवहायोग्यः यस्मिन् आश्वस्ताः भवामः। सैव जायात्वेन वक्तुं योग्या या (पत्ये) सुखकरी भवति। <br>Sons are those [alone], who are devoted to their father; Father is he [alone] who supports [family]; Friend is that [person alone] where [one can have] trust is; and wife is she where there is tranquillity.</td>
                        </tr>
                        <tr class="prasnaa">
                            <td style="width: 90px">प्रश्नाः </td>
                            <td>१.कः पिता? <br>२.का भार्या?  <br>३.‘पितुर्भक्ताः’ इत्यत्र सन्धिः विभज्यताम्।  <br>४.‘निर्वृतिः’ इत्यस्य पदविश्लेषणं वदत?  <br>५.तन्मित्रं यत्र ------। (रिक्तस्थानं पूरयत।)?</td>
                        </tr>
                        

                    </table>
                </div>
                    
                <div id="73" class="total">
                    <div>
                        <button id="moolamsmall73" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('moolam', '73')">मूलम्</button>
                        <button id="padasmall73" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '73')">पदविभागः</button>
                        <button id="anvayasmall73" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '73')">अन्वयः</button>
                        <button id="pratismall73" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '73')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall73" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '73')">तात्पर्यम्</button>
                        <button id="vyakyaasmall73" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('vyakyaa', '73')">वाक्याभ्यासः</button>
                        <button id="prasnaasmall73" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prasnaa', '73')">प्रश्नाः</button>
                    </div>
                    <div class="title">
                        73.मनसा चिन्तितं 
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम् </td>
                            <td>मनसा चिन्तितं कार्यं वाचा नैव प्रकाशयेत्।<br> (पाठ. वचसा न) मन्त्रेण रक्षयेद् गूढं कार्ये चापि नियोजयेत्॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>मनसा चिन्तितं कार्यं वाचा न एव प्रकाशयेत्। मन्त्रेण रक्षयेद् गूढं कार्ये च अपि नियोजयेत्॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td></td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>मनसा = अन्तरङ्गे; in the mind [Lit. by];<br> चिन्तितं = विचारितं; thought, contemplated;<br> कार्यं = उद्देश्यं, प्रयोजनं; plan, idea [lit. work to be done];<br> वाचा = वचसा; in wordsd [lit. by/ through];<br> न एव प्रकाशयेत् = न प्रकटयेत्; should not reveal;<br> मन्त्रेण = गुप्तभाषणेन; Secret plan or consultation;<br> रक्षयेत् = गोपयेत्; should protect;<br> गूढं = रहस्येन; a secret;<br> कार्ये च अपि = कृतौ च; in action;<br> नियोजयेत् = प्रयोगे विनियोजनं कुर्यात्; should use, employ, expose, put to</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>चित्ते आध्यातां कृतिं वचसा कदापि न प्रकटयेत्। गुप्तभाषणेन रहसि गोपयित्वा प्रयोगे नियुक्तिं कुर्यात्।  <br>One should not reveal [one’s] idea, thought over in mind, through words. That should be protected by keeping a secret and should be exposed only in action.</td>
                        </tr>
                        <tr class="prasnaa">
                            <td style="width: 90px">प्रश्नाः </td>
                            <td>१.किं कया नैव प्रकाशयेत्? <br>२.केन कथं रक्षयेत्?  <br>३.कस्मिन् नियोजयेत्?  <br>४.‘मन्त्रेण’ इत्यत्र तृतीयाविभक्तिः कथम्?  <br>५.कार्ये चापि ------। (रिक्तस्थानं पूरयत।)?  <br>६.‘चिन्तितं’ इत्यस्य पदविश्लेषणं वदत?</td>
                        </tr>
                        

                    </table>
                </div>
                    
                <div id="74" class="total">
                    <div>
                        <button id="moolamsmall74" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('moolam', '74')">मूलम्</button>
                        <button id="padasmall74" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '74')">पदविभागः</button>
                        <button id="anvayasmall74" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '74')">अन्वयः</button>
                        <button id="pratismall74" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '74')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall74" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '74')">तात्पर्यम्</button>
                        <button id="vyakyaasmall74" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('vyakyaa', '74')">वाक्याभ्यासः</button>
                        <button id="prasnaasmall74" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prasnaa', '74')">प्रश्नाः</button>
                    </div>
                    <div class="title">
                        74.अल्पकार्यकराः सन्ति 
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम् </td>
                            <td>अल्पकार्यकराः सन्ति ये नरा बहुभाषिणः।<br> शरत्कालिकनमेघास्ते नूनं गर्जन्ति केवलम्॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>अल्पकार्यकराः सन्ति ये नरा बहुभाषिणः। शरत्–कालिक–मेघाः ते नूनं गर्जन्ति केवलं॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>ये नरा अल्पकार्यकराः बहुभाषिणः सन्ति, ते नूनं शरत्–कालिक–मेघाः केवलं गर्जन्ति॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>ये नरा = ये जनाः; those men who;<br> बहुभाषिणः = अधिकं, वृथा च वदन्तः; who talk more;<br> सन्ति = वर्तन्ते; they are;<br> अल्पकार्यकराः = नाधिकं कार्यं कुर्वन्तः; less-working [Lit. less work doing];<br> शरत्–कालिक–मेघाः = शरदृतौ; autumnal clouds;<br> ते नूनं = ते मेघाः निश्चयं; They are certainly, assuredly, surely, verily, indeed;<br> गर्जन्ति = ध्वनिं कुर्वन्ति; roar;<br> केवलं = मात्रं; only</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>ये जनाः अधिकं प्रलपन्ते, ते न्यूनं कार्यं कुर्वन्ति। तेषां साम्यं शरदृतौ आच्छन्नाः मेघा इव। केवलं (वर्षसूचकं) ध्वनिं कुर्वन्ति (किन्तु न वर्षन्ति।) <br>Those people who talk more, do little work; They are indeed like the autumnal clouds, that only roar.</td>
                        </tr>
                        <tr class="prasnaa">
                            <td style="width: 90px">प्रश्नाः </td>
                            <td> १.बहुभाषिणः कीदृशाः?  <br>२.अल्पकार्यकराणां किमुपमानम्?  <br>३.‘बहुभाषिणः’ इत्यत्र समासविग्रहं वदत?  <br>४.‘शरत्कालीनमेघाः’ इत्यत्र समासविग्रहं वदत?  <br>५.‘अल्पकार्यकराः’ इत्यस्य पदविश्लेषणं वदत?  <br>६.नूनं ------ केवलम्। (रिक्तस्थानं पूरयत।)?</td>
                        </tr>
                        

                    </table>
                </div>
                    
                <div id="75" class="total">
                    <div>
                        <button id="moolamsmall75" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('moolam', '75')">मूलम्</button>
                        <button id="padasmall75" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '75')">पदविभागः</button>
                        <button id="anvayasmall75" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '75')">अन्वयः</button>
                        <button id="pratismall75" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '75')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall75" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '75')">तात्पर्यम्</button>
                        <button id="vyakyaasmall75" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('vyakyaa', '75')">वाक्याभ्यासः</button>
                        <button id="prasnaasmall75" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prasnaa', '75')">प्रश्नाः</button>
                    </div>
                    <div class="title">
                        75.यः पठति लिखति पश्यति 
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम् </td>
                            <td>यः पठति लिखति पश्यति परिपृच्छति पण्डितानुपाश्रयति।<br> तस्य दिवाकरकिरणैः नलिनीदलमिव विस्तारिता बुद्धिः॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>यः पठति लिखति पश्यति परिपृच्छति पण्डितान् उपाश्रयति। तस्य दिवाकर–किरणैः नलिनीदलम् इव विस्तारिता बुद्धिः।</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>यः पठति लिखति पश्यति परिपृच्छति पण्डितान् उपाश्रयति। तस्य दिवाकर–किरणैः नलिनीदलम् इव बुद्धिः विस्तारिता ।</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>यः = यो जनः; one who;<br> पठति = अध्ययनं करोति; reads;<br> लिखति = लेखनं करोति; writes;<br> पश्यति = अवलोकते; sees;<br> परिपृच्छति = जिज्ञासया प्रश्नं करोति; asks questions (with a desire to know);<br> पण्डितान् = विद्वज्जनान्; scholars (obj.);<br> उपाश्रयति = समीपमेति, आश्रयति; relies upon, depends;<br> तस्य = तज्जनस्य; his;<br> दिवाकर–किरणैः = सूर्यरश्मिभिः; by sun’s rays;<br> नलिनीदलम् इव = कमलपत्रमिव; like the petals of lotus;<br> बुद्धिः = धीशक्तिः; intellect, understanding;<br> विस्तारिता = व्याप्ता; expanded, spread</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>यः नरः (पुस्तकानि) पठति, (सत्साहित्यं) लिखति, (अनुशीलनं कुर्वन्) अवलोकते, (वस्तुतत्त्वं ज्ञातुकामः गुरुजनान् प्रश्नान्) पृच्छति, बहुश्रुतान् उपगच्छति च, तस्य नरस्य धीशक्तिः व्याकोचं प्राप्नोति। अत्रोदाहरणम्- यथा सूर्यमयूखैः कमलपत्राणि विकसितानि भवन्ति तथा। <br>That person who reads, writes, sees, enquires, relies upon learned men; his intellect expands like the lotus petals expand by the sunrays.</td>
                        </tr>
                        <tr class="prasnaa">
                            <td style="width: 90px">प्रश्नाः </td>
                            <td>१.कस्य विस्तारिता बुद्धिः?  <br>२.तत्र उपमानं किम्?  <br>३.‘दिवाकरकिरणैः’ इत्यत्र समासविग्रहं वदत?  <br>४.‘विस्तारिता’ इत्यस्य पदविश्लेषणं वदत?  <br>५.‘पण्डितान्’ इत्यत्र द्वितीयाविभक्तिः कथम्? <br>६.------ विस्तारिता बुद्धिः। (रिक्तस्थानं पूरयत।)?</td>
                        </tr>
                        

                    </table>
                </div>
                    
                <div id="76" class="total">
                    <div>
                        <button id="moolamsmall76" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('moolam', '76')">मूलम्</button>
                        <button id="padasmall76" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '76')">पदविभागः</button>
                        <button id="anvayasmall76" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '76')">अन्वयः</button>
                        <button id="pratismall76" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '76')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall76" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '76')">तात्पर्यम्</button>
                        <button id="vyakyaasmall76" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('vyakyaa', '76')">वाक्याभ्यासः</button>
                        <button id="prasnaasmall76" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prasnaa', '76')">प्रश्नाः</button>
                    </div>
                    <div class="title">
                        76.चित्ते प्रसन्ने भुवनं प्रसन्नं 
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम् </td>
                            <td>चित्ते प्रसन्ने भुवनं प्रसन्नं चित्ते विषण्णे भुवनं विषण्णम् ।<br> अतोऽभिलाषो यदि ते सुखे स्यात् चित्तप्रसादे प्रथमं यतस्व ॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>चित्ते प्रसन्ने भुवनं प्रसन्नं चित्ते विषण्णे भुवनं विषण्णम् । अतः अभिलाषः यदि ते सुखे स्यात् चित्तप्रसादे प्रथमं यतस्व ॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>चित्ते प्रसन्ने भुवनं प्रसन्नं चित्ते विषण्णे भुवनं विषण्णम् । अतः यदि ते सुखे अभिलाषः स्यात् चित्तप्रसादे प्रथमं यतस्व ॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>चित्ते = मनसि; when mind (is);<br> प्रसन्ने = सन्तुष्टे, आनन्दिते; when pleased, delighted, propitiated, soothed;<br> भुवनं = जगत्; world;<br> विषण्णे = दुःखिते; when dejected, cast down, sad, sarrowful, spiritless, despondent;<br> अतः = अनेन कारणेन; hence;<br> यदि = यदि; if;<br> ते = तव; yours;<br> सुखे = आनन्दे; in happiness;<br> अभिलाषः = कामना; desire;<br> स्यात् = भवेत्; if there is;<br> चित्तप्रसादे = मनसः सन्तुष्टौ; for [lit. in] mind-propitiation;<br> प्रथमं = सर्वस्मात् पूर्वं; first;<br> यतस्व = यत्नं करोतु; try</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>यदा अन्तरङ्गं परितुष्टं, तदा सर्वलोकः परितुष्टः। यदा अन्तरङ्गं दुःखितं, तदा जगत्सर्वं दुःखितं भवति। (हे पठितः,) अतः यदि तव आकाङ्क्षा सुखेन स्थातुं भवति, तर्हि (समस्तयत्नेभ्यः) पूर्वं मनसः सन्तुष्टीकरणे यत्नं कुरु।  <br>When the mind is pleased, the entire world is pleased. When the mind is sad, the entire world sad. Hence, if you desire for happiness,then strive for the mind-propitiation first.</td>
                        </tr>
                        <tr class="prasnaa">
                            <td style="width: 90px">प्रश्नाः </td>
                            <td>१.कदा भुवनं प्रसन्नम्? <br>२.सुखाभिलाषी किं कुर्यात्? <br>३.‘चित्ते प्रसन्ने’ इत्यत्र केन सप्तमी?  <br>४.‘विषण्णम्’ इत्यस्य पदविश्लेषणं वदत?  <br>५.‘अतोऽभिलाषः’ इत्यत्र सन्धिः विभज्यताम्।  <br>६.‘चित्तप्रसादे’ इत्यत्र समासविग्रहं वदत?</td>
                        </tr>
                        

                    </table>
                </div>
                    
                <div id="77" class="total">
                    <div>
                        <button id="moolamsmall77" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('moolam', '77')">मूलम्</button>
                        <button id="padasmall77" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '77')">पदविभागः</button>
                        <button id="anvayasmall77" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '77')">अन्वयः</button>
                        <button id="pratismall77" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '77')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall77" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '77')">तात्पर्यम्</button>
                        <button id="vyakyaasmall77" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('vyakyaa', '77')">वाक्याभ्यासः</button>
                        <button id="prasnaasmall77" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prasnaa', '77')">प्रश्नाः</button>
                    </div>
                    <div class="title">
                        77.क्रोधो वैवस्वतो राजा 
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम् </td>
                            <td>क्रोधो वैवस्वतो राजा तृष्णा वैतरणी नदी ।<br> विद्या कामदुघा धेनुः सन्तोषो नन्दनं वनम् ॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>क्रोधः वैवस्वतः राजा तृष्णा वैतरणी नदी विद्या कामदुघा धेनुः सन्तोषः नन्दनं वनम् ॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td></td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>क्रोधः = कोपः; anger;<br> वैवस्वतःराजा = यमः (विवस्वतः पुत्रः); son of sun, Lord of death, yama;<br> तृष्णा = अप्राप्ताभिलाषा; strong desire of gain;<br> वैतरणी नदी = नरकमार्गे काचन मलिना नदी; the river of hell (river which must be crossed before entering the infernal regions);<br> विद्या = ज्ञानं; learning;<br> कामदुघा धेनुः = इच्छापूरको गौः; a fabulous cow yielding all desires;<br> सन्तोषः = आनन्दः, परितुष्टिः; happiness;<br> नन्दनं वनम् = स्वर्गे स्थितम् उद्यानम्; the divine grove (of Indra).</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>कोपः यमधर्मराज इव। अतिलिप्सा वैतरणी नदी इव। ज्ञानं कामप्रदा गौरिव। सन्तुष्टिः  नन्दनोद्यानमिव। <br>Anger is the Lord of death; greedy desire is like the river Vaitarinī; knowledge is the wish- fulfilling celestial cow; contentment is the divine garden.</td>
                        </tr>
                        <tr class="prasnaa">
                            <td style="width: 90px">प्रश्नाः </td>
                            <td>१.क्रोधः कीदृशः?  <br>२.कः नन्दनं वनम्?  <br>३.------ वैतरणी नदी । (रिक्तस्थानं पूरयत।)?  <br>४.‘कामदुघा’ इत्यस्य पदविश्लेषणं वदत? <br>५.‘नन्दनं वनम्’ नाम किम्?</td>
                        </tr>
                        

                    </table>
                </div>
                    
                <div id="78" class="total">
                    <div>
                        <button id="moolamsmall78" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('moolam', '78')">मूलम्</button>
                        <button id="padasmall78" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '78')">पदविभागः</button>
                        <button id="anvayasmall78" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '78')">अन्वयः</button>
                        <button id="pratismall78" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '78')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall78" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '78')">तात्पर्यम्</button>
                        <button id="vyakyaasmall78" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('vyakyaa', '78')">वाक्याभ्यासः</button>
                        <button id="prasnaasmall78" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prasnaa', '78')">प्रश्नाः</button>
                    </div>
                    <div class="title">
                        78.विसृज्य शूर्पवद्दोषान् 
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम् </td>
                            <td>विसृज्य शूर्पवद्दोषान् गुणान् गृह्णाति सज्जनः।<br> दोषग्राही गुणत्यागी चालनीव हि दुर्जनः॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>विसृज्य शूर्पवत् दोषान् गुणान् गृह्णाति सज्जनः। दोषग्राही गुणत्यागी चालनीव हि दुर्जनः॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>सज्जनः शूर्पवत् दोषान् विसृज्य गुणान् गृह्णाति। दोषग्राही गुणत्यागी चालनीव हि दुर्जनः॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>सज्जनः = सत्पुरुषः; noble person;<br> शूर्पवत् = तण्डुलादिस्फोटनार्थं वंशादिनिर्मितपात्रविशेषः, तद्वत्; like winnowing basket;<br> दोषान् = स्खलितान्, अपराधान्; faults;<br> विसृज्य = परित्यज्य; leaving [lit. having left out];<br>  गुणान् = सद्गुणान्, अनुकूललक्षणानि; virtues;<br> गृह्णाति = स्वीकरोति; takes, accepts;<br> दोषग्राही = छिद्रमात्रदर्शी; fault-seeker [not fault-finder, lit. one who picks/takes faults];<br> गुणत्यागी = सुगुणान् न पश्यति यः; one who abandones virtues;<br> चालनीइव हि = तितउ वत्; like filter, sieve, strainer;<br> दुर्जनः = दुष्टः; wicked person</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>उत्तमजनः (अन्येषां) दुष्टगुणान् त्यक्त्वा सद्गुणान् एव गणयति, यथा स्फोटनम् । किन्तु खलस्तु दोषान् गृह्णाति, गुणान् त्यजति यथा चालनी। <br>The virtuous leaves the bad qualities like a winnow and receives the virtues [only]; the wicked is like sieve who takes the faults and leaves the good qualites.</td>
                        </tr>
                        <tr class="prasnaa">
                            <td style="width: 90px">प्रश्नाः </td>
                            <td>१.सज्जनःकिं करोति?  <br>२.दुर्जनः कीदृशः?   <br>३.‘शूर्पवद्दोषान्’ इत्यत्र सन्धिः विभज्यताम्। <br>४.‘दोषग्राही’ इत्यत्र समासविग्रहं वदत?  <br>५.‘विसृज्य’ इत्यस्य पदविश्लेषणं वदत?  <br>६.‘चालनी’ नाम का?</td>
                        </tr>
                        

                    </table>
                </div>
                    
                <div id="79" class="total">
                    <div>
                        <button id="moolamsmall79" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('moolam', '79')">मूलम्</button>
                        <button id="padasmall79" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '79')">पदविभागः</button>
                        <button id="anvayasmall79" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '79')">अन्वयः</button>
                        <button id="pratismall79" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '79')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall79" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '79')">तात्पर्यम्</button>
                        <button id="vyakyaasmall79" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('vyakyaa', '79')">वाक्याभ्यासः</button>
                        <button id="prasnaasmall79" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prasnaa', '79')">प्रश्नाः</button>
                    </div>
                    <div class="title">
                        79.दुर्जनो दोषमादत्ते 
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम् </td>
                            <td>दुर्जनो दोषमादत्ते दुर्गन्धमिव सूकरः।<br> सज्जनश्च गुणग्राही हंसः क्षीरमिवाम्भसः॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>दुर्जनः दोषम् आदत्ते दुर्गन्धम् इव सूकरः। सज्जनः च गुणग्राही हंसः क्षीरम् इव अम्भसः॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>दुर्जनः सूकरः दुर्गन्धम् इव दोषम् आदत्ते। सज्जनः च गुणग्राही हंसः क्षीरम् इव अम्भसः॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>दुर्जनः = दुष्टः; wicked;<br> सूकरः = वराहः; pig;<br> दुर्गन्धम् इव = दूषितः गन्ध इव; like bad smell;<br> दोषम् = अपराधं; fault;<br> आदत्ते = स्वीकरोति, गृह्णाति; takes;<br> सज्जनः च = सत्पुरुषस्तु; noble;<br> गुणग्राही = सुगुणान् स्वीकरोति यः; who takes in good qualities;<br> हंसः = पक्षीविशेषः, नीरक्षीरविवेकवान् कश्चित् श्वेतः जल-स्थल-पक्षी; swan;<br> क्षीरम् इव = दुग्धमिव; like milk;<br> अम्भसः = जलात्; from water</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>यथा वराहः दुष्टं गन्धं गृह्णाति, तथैव खलः दोषमेव स्वीकरोति। (किन्तु) यथा हंसः वारिणः (नीरक्षीरसम्मिश्रणात्) दुग्धं गृह्णाति, तथैव सुजनः गुणान् स्वीकरोति। <br>The wicked, like a pig, takes the bad; But virtuous receives the good qualities [ignoring the vices] like a swan, that takes milk and leaves water.</td>
                        </tr>
                        <tr class="prasnaa">
                            <td style="width: 90px">प्रश्नाः </td>
                            <td> १.दुर्जनः किं करोति? दुर्जने उपमानं किम्?  <br>२.सज्जनः कीदृशः? तत्र उपमानं किम्?  <br>३.‘सज्जनश्च’ इत्यत्र सन्धिः विभज्यताम्।  <br>४.‘क्षीरमिवाम्भसः’ इत्यत्र सन्धिः विभज्यताम्।  <br>५.‘गुणग्राही’ इत्यत्र समासविग्रहं वदत? <br>६.दुर्गन्धमिव ------।(रिक्तस्थानं पूरयत।)। </td>
                        </tr>
                        

                    </table>
                </div>
                    
                <div id="80" class="total">
                    <div>
                        <button id="moolamsmall80" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('moolam', '80')">मूलम्</button>
                        <button id="padasmall80" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '80')">पदविभागः</button>
                        <button id="anvayasmall80" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '80')">अन्वयः</button>
                        <button id="pratismall80" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '80')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall80" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '80')">तात्पर्यम्</button>
                        <button id="vyakyaasmall80" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('vyakyaa', '80')">वाक्याभ्यासः</button>
                        <button id="prasnaasmall80" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prasnaa', '80')">प्रश्नाः</button>
                    </div>
                    <div class="title">
                        80.परोपदेशे पाण्डित्यं 
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम् </td>
                            <td>परोपदेशे पाण्डित्यं सर्वेषां सुकरं नृणाम्।<br> धर्मे स्वयमनुष्ठानं कस्यचित्तु महात्मनः॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>परोपदेशे पाण्डित्यं सर्वेषां सुकरं नृणाम्। धर्मे स्वयम् अनुष्ठानं कस्यचित् तु महात्मनः॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>परोपदेशे सर्वेषां नृणाम् पाण्डित्यं सुकरम्। कस्यचित् तु महात्मनः (एव) धर्मे स्वयम् अनुष्ठानम् ॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>परोपदेशे = इतरेभ्यः हितवाक्यकथने; in instructing, teaching, advising, prescribing;<br> सर्वेषां = सकलानां; of everybody, all;<br> नृणाम् = मनुष्याणां; of people;<br> पाण्डित्यं = विद्वत्ता; scholarship, profound learning, erudition;<br> सुकरम् = अयत्नसाध्यं, अनायासं; easy to do;<br> कस्यचित् तु = कस्यचित्; of only some;<br> महात्मनः = उत्तमप्रकृतिकस्य; of great person, noble one;<br> धर्मे = कर्तव्ये, शुभकर्मणि, पुण्याचरणे; in duty;<br> स्वयम् = आत्मा; self;<br> अनुष्ठानम् = आचरणं; Doing, performance, practice, execution, accomplishment</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>अन्येषां अनुशासनोक्तौ सर्वजनानां कौशलमस्ति। (किन्तु) कश्चित् उदारचरितः एव (उक्तोपदेशानां) स्वयमाचरणं करोति।  <br>To advise others is a very easy task for all people; But it is possible for only some noble person to execute those right duties in action by one-self.</td>
                        </tr>
                        <tr class="prasnaa">
                            <td style="width: 90px">प्रश्नाः </td>
                            <td>१.किं सुकरम्?  <br>२.धर्मे स्वयमनुष्ठानं कस्य? <br>३.‘परोपदेशे’ इत्यत्र समासविग्रहं वदत?  <br>४.‘पाण्डित्यं’ इत्यस्य पदविश्लेषणं वदत?  <br>५.‘नृणाम्’ इत्यत्र षष्ठीविभक्तिः कथम्?  <br>६.धर्मे स्वयमनुष्ठानं ------ ------। (रिक्तस्थानं पूरयत।)?</td>
                        </tr>
                        

                    </table>
                </div>
                    
