                    </div>
                    <div class="title">
                        81.ज्ञातिभिर्वण्ट्यते नैव 
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम् </td>
                            <td>ज्ञातिभिर्वण्ट्यते नैव चोरेणापि न नीयते।<br> (पाठ. लुण्ठ्यते) दाने नैव क्षयं याति विद्यारत्नं महद्धनम्॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>ज्ञातिभिः वण्ट्यते न एव चोरेण अपि न नीयते। दाने न एव क्षयं याति विद्यारत्नं महत् धनम्॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td></td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>ज्ञातिभिः = बन्धुभिः; by relatatives;<br> न वण्ट्यते = न विभज्यते; is not divided, partitioned, shared;<br>  चोरेण अपि = तस्करेणापि; even by thieves;<br> न नीयते = न ह्रियते; is not taken away;<br> दाने = अन्येभ्यः वितरणे; when given [lit. in giving];<br> क्षयं = अपचयः, व्यर्थं; Loss, decline, waste;<br> न याति = न प्राप्नोति; does not go;<br> विद्यारत्नं = ज्ञानं नाम मणिः; the gem of knowledge;<br> महत् धनं = उत्तमा सम्पत्; great wealth</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>ज्ञानं नाम मणिं बन्धुजनाः विभक्तुं न शक्नुवन्ति, चोराः हर्तुं न पारयन्ति। दाने कृते न तत् व्ययीभवति। अतः विद्याधनं उत्तमं धनमस्ति।  <br>The gem of knowledge is the greatest wealth; which is not divided amongst relatives, nor be taken away by thief,nor does it declines when given.</td>
                        </tr>
                        <tr class="prasnaa">
                            <td style="width: 90px">प्रश्नाः </td>
                            <td>१.विद्यारत्नं कीदृशम्?  <br>२.केन विद्यारत्नं न नीयते?   <br>३.‘ज्ञातिभिर्वण्ट्यते’ इत्यत्र सन्धिः विभज्यताम्। <br>४.‘विद्यारत्नं’ इत्यत्र समासविग्रहं वदत?  <br>५.दाने नैव ------ याति। (रिक्तस्थानं पूरयत।)?  <br>६.‘चोरेण’ इत्यत्र तृतीयाविभक्तिः कथम्?</td>
                        </tr>
                        

                    </table>
                </div>
                    
