                    </div>
                    <div class="title">
                        82.धनधान्यप्रयोगेषु 
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम् </td>
                            <td>धनधान्यप्रयोगेषु विद्यासङ्ग्रहणेषु च।<br> (पाठ. तथा विद्यागमेषु च) आहारे व्यवहारे च त्यक्तलज्जस्सुखी भवेत्॥ (पाठ. सदा भवेत्)</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td></td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>धनधान्य–प्रयोगेषु विद्यासङ्ग्रहणेषु च। आहारे व्यवहारे च त्यक्तलज्जः सुखी भवेत्॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>धनधान्य–प्रयोगेषु = वित्त-खाद्यबीज-सम्बन्धि-व्यवहारेषु; while using (or application, employment of) wealth and food-grains;<br> आहारे = अन्नव्यवहारे; in food (matters);<br> व्यवहारे च = लौकिकव्यवहारे च; in worldly dealings;<br> त्यक्तलज्जः = सङ्कोचविरहितः; one who has given up shy;<br> सुखी = नन्दितः; happy;<br> भवेत् = विद्येत; will be</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>धने, धान्ये, विद्यार्जने, अन्नादने, लौकिकविषयेषु च यः सङ्कोचं त्यक्त्वा व्यवहरति, सः सुखी भवति।; <br>One can be happy when one has given up being shy in the matters of wealth, food-grains, acquiring knowledge, food, worldly dealings. पाठ. तथा विद्यागमेषु च = similarly in learningshāstras; पाठ. सदा भवेत् = will always be</td>
                        </tr>
                        <tr class="prasnaa">
                            <td style="width: 90px">प्रश्नाः </td>
                            <td>१.कुत्र लज्जा त्यक्तव्या?  <br>२.कः सुखी भवेत्?  <br>३.‘त्यक्तलज्जस्सुखी’ इत्यत्र सन्धिः विभज्यताम्।  <br>४.‘धनधान्यप्रयोगेषु’ इत्यत्र समासविग्रहं वदत?  <br>५.आहारे ------ च। (रिक्तस्थानं पूरयत।)?</td>
                        </tr>
                        

                    </table>
                </div>
                    
