                    </div>
                    <div class="title">
                        83.अनभ्यासे विषं विद्या 
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम् </td>
                            <td>अनभ्यासे विषं विद्या अजीर्णे भोजनं विषम्।<br> (पाठ. दुरधीता विषं विद्या) विषं सभा दरिद्रस्य वृद्धस्य तरुणी विषम्॥ (पाठ. गोष्ठी दरिद्रस्य)</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>अनभ्यासे विषं विद्या अजीर्णे भोजनं विषं। विषं सभा दरिद्रस्य वृद्धस्य तरुणी विषम्॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>अनभ्यासे विद्या विषं। अजीर्णे भोजनं विषं। सभा दरिद्रस्य विषं। तरुणी वृद्धस्य विषम्॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>अनभ्यासे = पुनरावृत्ति-राहित्ये; when (there is) no practice;<br> विद्या = ज्ञानं; learning;<br> विषं = हानिकरं, विषमफलदायकं; poison;<br> अजीर्णे = अपचने; when (there is) indigestion;<br> भोजनं = खाद्यमन्नं; food;<br> सभा = सदः, गोष्ठी; assembly;<br> दरिद्रस्य = धनहीनस्य; of the poor;<br> तरुणी = युवती; young woman;<br> वृद्धस्य = जरठस्य; of the oldman;<br> </td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>अभ्यासराहित्ये ज्ञानं विषमं भवति। (पूर्वं भक्षितस्य) अजीर्णावस्थायां (पुनः) भोजनं हानिकरम्। अकिञ्चनस्य सङ्गोष्ठी पीडाकरी। स्थविरस्य युवती(प्रसङ्गः) विषम्।; <br>Knowledge is poison without practice; food is poison upon indigestion; social gathering is poison for a poor man; a young woman is poison for an old man.</td>
                        </tr>
                        <tr class="prasnaa">
                            <td style="width: 90px">प्रश्नाः </td>
                            <td>१.कदा विद्या विषम्? <br>२.किं किं कुत्र कुत्र विषम्? <br>३.‘दरिद्रस्य’ इत्यत्र षष्ठीविभक्तिः कथम्?  <br>४.वृद्धस्य ------ विषं। (रिक्तस्थानं पूरयत।)?  <br>५.‘अजीर्णे’ इत्यत्र केन सप्तमी?  <br>६.‘अनभ्यासे’ इत्यस्य पदविश्लेषणं वदत?</td>
                        </tr>
                        

                    </table>
                </div>
                    
