                        <button id="padasmall84" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '84')">पदविभागः</button>
                        <button id="anvayasmall84" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '84')">अन्वयः</button>
