                    </div>
                    <div class="title">
                        84.विद्वानेव विजानाति 
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम् </td>
                            <td>विद्वानेव विजानाति विद्वज्जनपरिश्रमम् ।<br> न हि वन्ध्या विजानाति गुर्वीं प्रसववेदनाम् ॥ कुवलयानन्द</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>विद्वान् एव विजानाति विद्वत्–जन–परिश्रमम् । न हि वन्ध्या विजानाति गुर्वीं प्रसववेदनाम्। </td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>विद्वान् एव विद्वत्–जन–परिश्रमम् विजानाति । न हि वन्ध्या गुर्वीं प्रसववेदनाम् विजानाति।</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>विद्वान् एव = केवलं पण्डितः; Only ascholar;<br> विद्वत्–जन–परिश्रमम् = पण्डितानां क्लमः, प्रयासः; exertion of scholars [Close application to or study of, being constantly occupied with];<br> विजानाति = अवबोधति; knows, is aware of;<br> न हि = नैव; not;<br> वन्ध्या = सन्तानोत्पादने अशक्ता; A barren woman;<br> गुर्वीं = भारवन्तीं; pregnant [here, heavy];<br> प्रसववेदनाम् = प्रसूतिसमयपीडां; pangs of child-birth, throes</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>विद्यावान् एव अन्यस्य विद्यावतः (ज्ञानसञ्चयाय कृतं) आयासं अवैति। महायातनाकरं प्रसूतिपीडां सन्तानजनने अशक्ता स्त्री कदापि नावगच्छति।  <br>A scholar alone is aware of [other] scholar’s endeavour. A childless woman would never understand the labour pain [caused while child- birth]. </td>
                        </tr>
                        <tr class="prasnaa">
                            <td style="width: 90px">प्रश्नाः </td>
                            <td>१.कः किं विजानाति?  <br>२.वन्ध्या किं न विजानाति? <br>३.‘विद्वज्जनपरिश्रमम्’ इत्यत्र समासविग्रहं वदत? <br>४.‘प्रसववेदनाम्’ इत्यत्र समासविग्रहं वदत?  <br>५.------ विजानाति । (रिक्तस्थानं पूरयत।) <br>६.‘गुर्वी’ इत्यस्य पदविश्लेषणं वदत?</td>
                        </tr>
                        

                    </table>
                </div>
                    
