                    </div>
                    <div class="title">
                        85.परैः प्रोक्ता गुणा यस्य 
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम् </td>
                            <td>परैः प्रोक्ता गुणा यस्य निर्गुणोऽपि गुणी भवेत् ।<br> इन्द्रोऽपि लुघतां याति स्वयं प्रख्यापितैर्गुणैः ॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>परैः प्रोक्ता गुणाः यस्य निर्गुणः अपि गुणी भवेत् । इन्द्रः अपि लुघतां याति स्वयम् प्रख्यापितैः गुणैः ॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>यस्य परैः गुणाः प्रोक्ता (सः) निर्गुणः अपि गुणी भवेत् । इन्द्रः अपि स्वयम् प्रख्यापितैः गुणैः लुघतां याति ॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>यस्य = यज्जनस्य; of whom;<br> परैः = अन्यैः; by others;<br> गुणाः = सद्गुणाः, लक्षणविशेषाः; good qualities;<br> प्रोक्ताः = कथ्यन्ते; said, told;<br> निर्गुणः अपि = गुणहीनः अपि; even when without attributes;<br> गुणी = सुगुणवान्; good, meritorious;<br> भवेत् = घटेत; would become;<br> इन्द्रः अपि = सुराणां प्रभुरपि; even Indra [king of gods];<br> स्वयम् = आत्मना; by himself;<br> प्रख्यापितैः = कथितैः, ज्ञापितैः; by praised, announced, published;<br> गुणैः = लक्षणविशेषैः; by [good] qualities;<br> लुघतां = ह्रस्वत्वं; absence of dignity, trivialness;<br> याति = प्राप्नोति; reaches, attains</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>यस्य गुणविशेषाः इतरैः कथ्यन्ते सः विशेषगुणहीनोऽपि सन्, गुणवान् सम्भवति। यदि महेन्द्रः अपि स्वयमेव (स्वमुखेन) स्वसद्गुणान् प्रकटयति, तर्हि सः अल्पत्वम् एति। <br>One whose qualities are praised by others, is considered as virtuous, even if he may not have those qualities. But Indra himself would look trivial, when he tells (brags) about his own attributes.</td>
                        </tr>
                        <tr class="prasnaa">
                            <td style="width: 90px">प्रश्नाः </td>
                            <td>१.कदा निर्गुणोऽपि गुणी भवेत्?  <br>२.इन्द्रः केन लघुतां याति?  <br>३.‘निर्गुणोऽपि’ इत्यत्र सन्धिः विभज्यताम्।  <br>४.‘प्रख्यापितैर्गुणैः’ इत्यत्र सन्धिः विभज्यताम्। <br>५.------ गुणी भवेत्। (रिक्तस्थानं पूरयत।)? <br>६.‘गुणैः’ इत्यत्र तृतीयाविभक्तिः कथम्?</td>
                        </tr>
                        

                    </table>
                </div>
                    
                <div id="86" class="total">
