                    </div>
                    <div class="title">
                        86.अविद्यानाशिनी विद्या 
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम् </td>
                            <td>अविद्यानाशिनी विद्या भावना भयनाशिनी ।<br> दारिद्र्यनाशनं दानं शीलं दुर्गतिनाशनम् ॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>सुलभः</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>अविद्यानाशिनी विद्या भावना भयनाशिनी । दारिद्र्यनाशनं दानं शीलं दुर्गतिनाशनम् ॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>अविद्यानाशिनी = अज्ञानान्तका; destroyer of ignorance;<br> विद्या = ज्ञानं; knowledge, learning;<br> भावना = ध्यानम्; Feeling of devotion, faith;<br> भयनाशिनी = आशङ्क-ध्वंसिनी; destroyer of fear;<br> दारिद्र्यनाशनं = अभाव-विनाशकं; destroyer of poverty;<br> दानं = अन्येभ्यः धनादीनां वितरणं; charity;<br> शीलं = सच्चरित्रम्; character;<br> दुर्गतिनाशनम् = दुर्भाग्यक्षयकरं; destroyer of misfortune, trouble</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>ज्ञानम् अज्ञानान्तकं भवति। ध्यानं भयं निषूदयति। दानं निर्धनत्वघातकं भवति। सच्चरित्रं दुर्भाग्यम् अपनयति।  <br>Knowledge destroys ignorance; faith removes fear; donating (charity) kills poverty; [good moral] character wards off misfortune.</td>
                        </tr>
                        <tr class="prasnaa">
                            <td style="width: 90px">प्रश्नाः </td>
                            <td>१.विद्या कीदृशी?  <br>२.दानं कीदृशम्?  <br>३.शीलं ------। (रिक्तस्थानं पूरयत।)?  <br>४.‘दारिद्र्यनाशनं’इत्यत्र समासविग्रहं वदत?  <br>५.------ भयनाशिनी (रिक्तस्थानं पूरयत।)?</td>
                        </tr>
                        

                    </table>
                </div>
                    
