                    </div>
                    <div class="title">
                        87.अपूर्वः कोऽपि कोशोऽयं 
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम् </td>
                            <td>अपूर्वः कोऽपि कोशोऽयं विद्यते तव भारति ।<br> व्ययतो वृद्धिमायाति क्षयमायाति सञ्चयात् ॥ - सुभाषितरत्नभाण्डागारः</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>अपूर्वः कः अपि कोशः अयं विद्यते तव भारति । व्ययतः वृद्धिम् आयाति क्षयम् आयाति सञ्चयात् ॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>भारति, अयं कः अपि अपूर्वः तव कोशः विद्यते । व्ययतः वृद्धिम् आयाति, सञ्चयात् क्षयम् आयाति ॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>भारति = हे सरस्वति; O sarasvatI, goddess/ deity of knowledge;<br> अयं = असौ; this;<br> कः अपि = कश्चित्; some;<br> अपूर्वः = विशिष्टः; not preceded, not having existed before;<br> तव = त्वत्सम्बन्धी; yours;<br> कोशः = निधिः; treasure, money, wealth, store;<br> विद्यते = भवति; is there, exists;<br> व्ययतः = विक्षेपात्; by spending;<br> वृद्धिम् = आधिक्यं; growth, increase, development;<br> आयाति = प्राप्नोति; follows, results;<br> सञ्चयात् = सङ्ग्रहणात्; by hoarding, accumulating, stocking;<br> क्षयम् = अपचयं; diminish, decay, waste</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>हे सरस्वति, तव कश्चित् विशिष्टः निधिः वर्तते। सः विनियोगेन वर्धते, समाहरणेन च अपक्षयमेति। <br>O sarasvati, your treasure is wonderful. By spending, it grows.By hoarding, it decays.</td>
                        </tr>
                        <tr class="prasnaa">
                            <td style="width: 90px">प्रश्नाः </td>
                            <td>१.कस्य कोशः अपूर्वः?  <br>२.कोशः कीदृशः? <br>३.‘कोशोऽयं’ इत्यत्र सन्धिः विभज्यताम्।  <br>४.‘व्ययतो’ इत्यस्य पदविश्लेषणं वदत?  <br>५.क्षयमायाति ------। (रिक्तस्थानं पूरयत।)?</td>
                        </tr>
                        

                    </table>
                </div>
                    
