                        <button id="padasmall88" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '88')">पदविभागः</button>
                        <button id="anvayasmall88" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '88')">अन्वयः</button>
                        <button id="pratismall88" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '88')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall88" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '88')">तात्पर्यम्</button>
                        <button id="vyakyaasmall88" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('vyakyaa', '88')">वाक्याभ्यासः</button>
                        <button id="prasnaasmall88" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prasnaa', '88')">प्रश्नाः</button>
                    </div>
                    <div class="title">
                        88.अहो प्रकृतिसादृश्यं 
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम् </td>
                            <td>अहो प्रकृतिसादृश्यं श्लेष्मणो दुर्जनस्य च ।<br> अहो प्रकृतिसादृश्यं श्लेष्मणो दुर्जनस्य च </td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>अहो प्रकृतिसादृश्यं श्लेष्मणः दुर्जनस्य च । मधुरैः कोपम् आयाति कटुकेन एव शाम्यति ॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>अहो श्लेष्मणः दुर्जनस्य च प्रकृतिसादृश्यम्। मधुरैः कोपम् आयाति कटुकेन एव शाम्यति ॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>अहो = धिक्; Oh!;<br> श्लेष्मणः = कफस्य; of phlegmatic humour;<br> दुर्जनस्य च = दुष्टस्य च; of wicked person;<br> प्रकृति-सादृश्यम् = स्वभावे समानत्वं; similarity in natural disposition;<br> मधुरैः = आनन्दकरैः; by sweet things;<br> कोपम् = क्रोधं; anger, fury;<br> आयाति = प्राप्नोति; comes (here- gets);<br> कटुकेन = परुषेण दूषणेन,; by pungency (a compound of ginger, black and long pepper);<br> एव शाम्यति = शान्तिं याति; appeased, subdued</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>अहो, कफस्य खलस्य च स्वभावयोः अनुरूपत्वं (दृश्यते)। (द्वावपि) मधुरैः (कफपक्षे मधुरपदार्थैः, दुष्टपक्षे मधुरवचनैः) कोपोद्दीप्तौ भवतः। कटुकेन (कफपक्षे कटुपदार्थैः, खलपक्षे कटुदूषणेन) शाम्यतः।   <br>Oh! there is similarity between the nature of phlegm and a wicked person. It gets enraged by sweet things and subdued by pungent thing.</td>
                        </tr>
                        <tr class="prasnaa">
                            <td style="width: 90px">प्रश्नाः </td>
                            <td>१.कयोः प्रकृतिसादृश्यम्?  <br>२.कैः कोपमायाति ?  <br>३.केन शाम्यति?  <br>४.‘कटुकेनैव’ इत्यत्र सन्धिः विभज्यताम्। <br>५.------ कोपमायाति। (रिक्तस्थानं पूरयत।)? <br>६.‘प्रकृतिसादृश्यं’ इत्यत्र समासविग्रहं वदत?</td>
                        </tr>
                        

                    </table>
                </div>
                    
