                        <button id="padasmall89" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '89')">पदविभागः</button>
                        <button id="anvayasmall89" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '89')">अन्वयः</button>
