                        <button id="prasnaasmall89" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prasnaa', '89')">प्रश्नाः</button>
                    </div>
                    <div class="title">
                        89.चला लक्ष्मीश्चलाः 
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम् </td>
                            <td>चला लक्ष्मीश्चलाः प्राणाश्चलं जीवितयौवनम् ।<br> चलाचले हि संसारे धर्म एको हि निश्चलः ॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td></td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>चला लक्ष्मीः चलाः प्राणाः चलं जीवितयौवनम् । चलाचले हि संसारे धर्म एकः हि निश्चलः ॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>चला = चञ्चला; transitory;<br> लक्ष्मीः = धनं; wealth;<br> प्राणाः = श्वासः; vital air(s), breath;<br> जीवितयौवनम् = जीवनं, तारुण्यं; life and youth;<br> संसारे = जगति; in the world;<br> धर्मः = शुभकर्म, कर्तव्यं; good works (regarded as one of the four ends of human existence);<br> एकः हि = केवलं; alone, only one;<br> निश्चलः = स्थिरः; stable, unmoving</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>अस्मिन् लोके वित्तं, प्राणः, जीवनं, तारुण्यं च सर्वं अशाश्वतम्। केवलं धर्म एव शाश्वतः भवति। <br>Wealth is transient. Breath is impermanent. Life and youth are perishable. In the transitory world, only dharma is steady (unchangeable).</td>
                        </tr>
                        <tr class="prasnaa">
                            <td style="width: 90px">प्रश्नाः </td>
                            <td>१.किं किं चलम्?  <br>२.कः निश्चलः?  <br>३.‘प्राणाश्चलं’ इत्यत्र सन्धिः विभज्यताम्। <br>४.‘जीवितयौवनम्’ इत्यत्र समासविग्रहं वदत?</td>
                        </tr>
                        

                    </table>
                </div>
                    
                <div id="90" class="total">
                    <div>
                        <button id="moolamsmall90" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('moolam', '90')">मूलम्</button>
                        <button id="padasmall90" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '90')">पदविभागः</button>
                        <button id="anvayasmall90" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '90')">अन्वयः</button>
                        <button id="pratismall90" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '90')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall90" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '90')">तात्पर्यम्</button>
                        <button id="vyakyaasmall90" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('vyakyaa', '90')">वाक्याभ्यासः</button>
                        <button id="prasnaasmall90" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prasnaa', '90')">प्रश्नाः</button>
                    </div>
                    <div class="title">
                        90.गुणेषु क्रियतां यत्नः 
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम् </td>
                            <td>गुणेषु क्रियतां यत्नः किमाटोपैः प्रयोजनम् ।<br> (पाठ. गुणेष्वेवादरः कार्यः) विक्रीयन्ते न घण्टाभिः गावः क्षीरविवर्जिताः ॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>गुणेषु क्रियतां यत्नः किम् आटोपैः प्रयोजनम्। विक्रीयन्ते न घण्टाभिः गावः क्षीरविवर्जिताः ॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>गुणेषु यत्नः क्रियतां, आटोपैः किम् प्रयोजनम्। घण्टाभिः गावः क्षीरविवर्जिताः न विक्रीयन्ते ॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>गुणेषु = लक्षणविशेषेषु; in good qualities;<br> यत्नः = प्रयासः; effort;<br> क्रियतां = आचरताम्; should do;<br> आटोपैः = आडम्बरैः; by self-conceit (simply, make-up?);<br> किम् प्रयोजनम् = कः लाभः; what use;<br> घण्टाभिः = नादवस्तुविशेषैः, वाद्यविशेषैः; by bells;<br> गावः = धेनवः; cows;<br> क्षीरविवर्जिताः = दुग्धरहिताः; devoid of milk;<br> न विक्रीयन्ते = न विक्रयणं यान्ति; are not sold</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>सद्गुणेषु प्रयत्नः अनुष्ठीयताम्। आडम्बरैः कः लाभः? घण्टाभिः (अलङ्कृताः) पयोदाने असमर्थाः धेनवः न विक्रेतुं शक्यन्ते।  <br>Make effort in [developing] good qualities. What can be gained by outward/artificial make-up? Milk-less cows do not get sold just by [tying] bells [in necks]. पाठ. गुणेष्वेवादरः कार्यः = respect should be given [lit. done] for good qualities only.</td>
                        </tr>
                        <tr class="prasnaa">
                            <td style="width: 90px">प्रश्नाः </td>
                            <td>१.कुत्र यत्नः क्रियताम्?  <br>२.के कैः न विक्रीयन्ते? <br>३.‘क्षीरविवर्जिताः’ इत्यत्र समासविग्रहं वदत?  <br>४.‘विक्रीयन्ते’इत्यत्र सन्धिः विभज्यताम्। <br>५.‘गुणेषु’ इत्यत्र केन सप्तमी?</td>
                        </tr>
                        

                    </table>
                </div>
                    
                <div id="91" class="total">
                    <div>
