                        <button id="taatparyamsmall91" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '91')">तात्पर्यम्</button>
                        <button id="vyakyaasmall91" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('vyakyaa', '91')">वाक्याभ्यासः</button>
                        <button id="prasnaasmall91" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prasnaa', '91')">प्रश्नाः</button>
                    </div>
                    <div class="title">
                        91.मृगा मृगैः सङ्गमनुव्रजन्ति 
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम् </td>
                            <td>मृगा मृगैः सङ्गमनुव्रजन्ति गावश्च गोभिस्तुरगास्तुरङ्गैः ।<br> मूर्खाश्च मूर्खैः सुधियः सुधीभिः समानशीलव्यसनेषु सख्यम् ॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>मृगाः मृगैः सङ्गम् अनुव्रजन्ति गावः च गोभिः तुरगाः तुरङ्गैः । मूर्खाः च मूर्खैः सुधियः सुधीभिः समान-शील-व्यसनेषु सख्यम् ॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>मृगाः मृगैः सङ्गम् अनुव्रजन्ति। गावः च गोभिः तुरगाः तुरङ्गैः (अनुव्रजन्ति)। मूर्खाः च मूर्खैः सुधियः सुधीभिः समान-शील-व्यसनेषु सख्यम् ॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>मृगाः = हरिणाः; deer;<br> सङ्गम् = साङ्गत्यं; company, association, friendship;<br> अनुव्रजन्ति = अनुसरन्ति; follow, go with;<br> गावः च = धेनवश्च; cows;<br> तुरगाः = अश्वाः; horses;<br> मूर्खाः च = अर्धज्ञाः; fools;<br> सुधियः = बुद्धिमन्तः; wise;<br> समान-शील-व्यसनेषु = तुल्यचरित्रे,कामजकोपजदोषेषु च सादृश्यं; in common character/nature and habits [शीलं = Disposition, nature, character, tendency, inclination, habit, custom - Apte];<br> सख्यम् = मित्रत्वं; friendship</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>हरिणाः हरिणैः सार्धं गच्छन्ति। धेनवः, अश्वाः चापि स्वजातिविशेषैः साकं यान्ति। तथैव जडधियः जडबुद्धिभिः, विवेकशीलिनः विवेकवद्भिश्च सह चरन्ति। यत्र शीले व्यसनेषु च साम्यं, तत्रैव मित्रत्वं भवति। <br>Deers follow [the company of] deers; cows go with [other] cows; horses with horses; fools [move] with fools; wise with wise. Friendship exists among those who have common/ similar nature and habits.</td>
                        </tr>
                        <tr class="prasnaa">
                            <td style="width: 90px">प्रश्नाः </td>
                            <td>१.मृगाः किं कुर्वन्ति? <br>२.मूर्खाः कैः अनुव्रजन्ति?  <br>३.सख्यं कुत्र भवति?  <br>४.‘गोभिस्तुरगास्तुरङ्गैः’ इत्यत्र सन्धिः विभज्यताम्।  <br>५.‘समानशीलव्यसनेषु’ इत्यत्र समासविग्रहं वदत? <br>६.‘मूर्खाश्च मूर्खैः’ इत्यत्र तृतीयाविभक्तिः कथम्?</td>
                        </tr>
                        

                    </table>
                </div>
                    
                <div id="92" class="total">
                    <div>
                        <button id="moolamsmall92" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('moolam', '92')">मूलम्</button>
                        <button id="padasmall92" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '92')">पदविभागः</button>
                        <button id="anvayasmall92" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '92')">अन्वयः</button>
