                        <button id="vyakyaasmall92" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('vyakyaa', '92')">वाक्याभ्यासः</button>
                        <button id="prasnaasmall92" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prasnaa', '92')">प्रश्नाः</button>
                    </div>
                    <div class="title">
                        92.शास्त्राण्यधीत्यापि भवन्ति मूर्खाः 
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम् </td>
                            <td>शास्त्राण्यधीत्यापि भवन्ति मूर्खाः यस्तु क्रियावान् पुरुषः स विद्वान् ।<br> सुचिन्तितं औषधमातुराणां न नाममात्रेण करोत्यरोगम् ॥ हितोपदेशः, मित्रलाभम्</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>शास्त्राणि अधीत्य अपि भवन्ति मूर्खाः यः तु क्रियावान् पुरुषः सः विद्वान् । सुचिन्तितं औषधम् आतुराणां न नाममात्रेण करोति अरोगम् ॥ </td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>शास्त्राणि अधीत्य अपि मूर्खाः भवन्ति। यः तु क्रियावान् पुरुषः सः विद्वान् । सुचिन्तितम् औषधम् नाममात्रेण आतुराणां अरोगम् न करोति ॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>शास्त्राणि = धर्माधर्म-निदेशक-ग्रन्थविशेषान्; (scriptures of) traditional disciplines;<br> अधीत्य अपि = अवबुध्यापि; inspite of having studied;<br> मूर्खाः = अर्धज्ञाः; fools;<br> भवन्ति = सम्भवन्ति; become;<br> यः तु = यः जनः; one who;<br> क्रियावान् = कार्यरतः, कर्तव्याय प्रयत्नशीलः; engaged in any actual work, versed in the practice of a thing;<br> पुरुषः = नरः; person, human being;<br> विद्वान् = पण्डितः; scholar;<br> सुचिन्तितम् = सम्यक् विचारितं; well-thought over, devised;<br> औषधम् = अगदः; medicine;<br> नाममात्रेण = नाम्नः उच्चारणेन, स्मरणेन वा; by name alone;<br> आतुराणां = रोगिणां; of the ill, patients, sick;<br> अरोगम् = व्याधिरहितं; free from disease, healthy, well;<br> न करोति = न घटयति; does not do</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>धर्मग्रन्थान् पठित्वापि जनाः जडधियः भवन्ति। यः कार्यशीलः सः एव पण्डितः भवति। रोगिणः सम्यक् चिन्तित्वा प्राप्तस्य औषधस्य नामोच्चारणमात्रेण रोगरहिताः न भवन्ति।  <br>People remain fools in spite of learning sciences (theories). The one engaged in real action [puts to practice] is the [true] scholar. Medicine well-devised will not cure the patients just by [uttering] its name. </td>
                        </tr>
                        <tr class="prasnaa">
                            <td style="width: 90px">प्रश्नाः </td>
                            <td>१.मूर्खाः किं कृत्वापि भवन्ति?  <br>२.कः विद्वान्?  <br>३.अरोगं किं केन न करोति? <br>४.‘शास्त्राण्यधीत्यापि’ इत्यत्र सन्धिः विभज्यताम्।  <br>५.‘करोत्यरोगम्’ इत्यत्र सन्धिः विभज्यताम्। <br>६.‘सुचिन्तितं’ इत्यस्य पदविश्लेषणं वदत?</td>
                        </tr>
                        

                    </table>
                </div>
                    
                <div id="93" class="total">
                    <div>
                        <button id="moolamsmall93" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('moolam', '93')">मूलम्</button>
                        <button id="padasmall93" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '93')">पदविभागः</button>
                        <button id="anvayasmall93" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '93')">अन्वयः</button>
                        <button id="pratismall93" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '93')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall93" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '93')">तात्पर्यम्</button>
                        <button id="vyakyaasmall93" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('vyakyaa', '93')">वाक्याभ्यासः</button>
                        <button id="prasnaasmall93" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prasnaa', '93')">प्रश्नाः</button>
                    </div>
                    <div class="title">
                        93.विषस्य विषयाणाञ्च
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम् </td>
                            <td>विषस्य विषयाणाञ्च दूरमत्यन्तमन्तरम् ।<br> उपभुक्तं विषं हन्ति विषयाः स्मरणादपि ॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>विषस्य विषयाणां च दूरम् अत्यन्तम् अन्तरम् । उपभुक्तं विषं हन्ति विषयाः स्मरणाद् अपि ॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>विषस्य विषयाणां च दूरम् अत्यन्तम् अन्तरम् । विषं उपभुक्तं हन्ति विषयाः स्मरणाद् अपि (घ्नन्ति) ॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>विषस्य = गरलस्य; of poison;<br> विषयाणां च = लौकिकविषयाणां; of worldly or sensual objects;<br> दूरम् = अध्वन्; distance;<br> अत्यन्तम् = नितरां; very much;<br> अन्तरम् = व्यवधिः; near, closely connected;<br> उपभुक्तं = अनुभूतं; when enjoyed, tasted;<br> हन्ति = नाशयति; kills;<br> स्मरणाद् अपि = मनसि सकृत् चिन्तनात्अपि; by remembering, thinkingalso</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>विषस्य विषयस्य च मध्ये दूरम् अधिकं नास्ति। विषे आस्वादिते सतिपुरुषः म्रियते। किन्तु विषयास्तु चिन्तनमात्रेण घ्नन्ति। <br>Poison and sensuous objects are very closely connected [lit. distance is very close]. Poison kills when consumed, but worldly objects kill just by thinking [about them].</td>
                        </tr>
                        <tr class="prasnaa">
                            <td style="width: 90px">प्रश्नाः </td>
                            <td>१.कयोः दूरमत्यन्तमन्तरम्? <br>२.विषं कथं हन्ति? <br>३.‘विषयाणाञ्च’ इत्यत्र सन्धिः विभज्यताम्। <br>४.‘उपभुक्तं’ इत्यस्य पदविश्लेषणं वदत?  <br>५.‘स्मरणादपि’ इत्यत्र पञ्चमीविभक्तिः कथम्?</td>
                        </tr>
                        

                    </table>
                </div>
                    
                <div id="94" class="total">
                    <div>
                        <button id="moolamsmall94" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('moolam', '94')">मूलम्</button>
                        <button id="padasmall94" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '94')">पदविभागः</button>
                        <button id="anvayasmall94" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '94')">अन्वयः</button>
                        <button id="pratismall94" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '94')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall94" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '94')">तात्पर्यम्</button>
                        <button id="vyakyaasmall94" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('vyakyaa', '94')">वाक्याभ्यासः</button>
                        <button id="prasnaasmall94" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prasnaa', '94')">प्रश्नाः</button>
                    </div>
                    <div class="title">
                        94.यथा खनन् खनित्रेण 
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम् </td>
                            <td>यथा खनन् खनित्रेण नरो वार्यधिगच्छति।<br> तथा गुरुगतां विद्यां शुश्रूषुरधिगच्छति॥२.२१८॥मनुसंहितायां द्वितीयोऽध्यायः</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>यथा खनन् खनित्रेण नरः वारि अधिगच्छति। तथा गुरुगतां विद्यां शुश्रूषुः अधिगच्छति॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>यथा खनित्रेण खनन् नरः वारि अधिगच्छति। तथा शुश्रूषुः गुरुगतां विद्यां अधिगच्छति॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>यथा = येन प्रकारेण; like, same as;<br> खनित्रेण = खनन-परिकरेण; with spade, hoe, a pick-axe;<br> खनन् = भूमिं विदारयन्; while digging;<br> नरः = जनः; person;<br> वारि = जलं; water;<br> अधिगच्छति = प्राप्नोति; gets, reaches;<br> तथा = तत्प्रकारेण; similarly;<br> शुश्रूषुः = श्रोतुमिच्छुकः, सेवापरः; Desirous of serving or attending, Obedient, attentive [lit. Desirous to hear.];<br>  गुरुगतां = आचार्ये स्थितां; contained in teacher, possessed by teacher;<br> विद्यां = ज्ञानं; knowledge, learning;<br> अधिगच्छति = लभते; receives, knows, learns</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>यथा अस्त्रविशेषेण (पृथ्वीं) विदारयन् पुरुषः नीरं प्राप्नोति, तथैव (श्रद्धया) गुरुसेवायां रतः गुरौ स्थितां विद्यां प्राप्नोति। <br>Just as a person gets water, by digging the earth with a spade, so does an obedient student gets knowledge within the teacher.</td>
                        </tr>
                        <tr class="prasnaa">
                            <td style="width: 90px">प्रश्नाः </td>
                            <td>१.कः नरः केन किमधिगच्छति? <br>२.शुश्रूषुः किमधिगच्छति? <br>३.‘वार्यधिगच्छति’इत्यत्र सन्धिः विभज्यताम्। <br>४.‘शुश्रूषुरधिगच्छति’ इत्यत्र सन्धिः विभज्यताम्। <br>५.‘खनित्रेण’ इत्यत्र तृतीयाविभक्तिः कथम्? <br>६.‘शुश्रूषुः’ इत्यस्य पदविश्लेषणं वदत?</td>
                        </tr>
                        

                    </table>
                </div>
                    
                <div id="95" class="total">
                    <div>
                        <button id="moolamsmall95" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('moolam', '95')">मूलम्</button>
                        <button id="padasmall95" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '95')">पदविभागः</button>
                        <button id="anvayasmall95" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '95')">अन्वयः</button>
                        <button id="pratismall95" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '95')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall95" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '95')">तात्पर्यम्</button>
                        <button id="vyakyaasmall95" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('vyakyaa', '95')">वाक्याभ्यासः</button>
                        <button id="prasnaasmall95" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prasnaa', '95')">प्रश्नाः</button>
                    </div>
                    <div class="title">
                        95.श्रीमानजननिन्द्यश्च 
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम् </td>
                            <td>श्रीमानजननिन्द्यश्च शूरश्चाप्यविकत्थनः ।<br> समदृष्टिः प्रभुश्चैव दुर्लभाः पुरुषास्त्रयः ॥ योगावासिष्ठम्, वैराग्य॰</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>श्रीमान् अजननिन्द्यः च शूरः च अपि अविकत्थनः । समदृष्टिः प्रभुः च एव दुर्लभाः पुरुषाः त्रयः ॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>श्रीमान् अजननिन्द्यः च शूरः च अपि अविकत्थनः प्रभुः च एव समदृष्टिः त्रयः पुरुषाः दुर्लभाः ॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>श्रीमान् = धनवान्; wealthy, rich;<br> अजननिन्द्यः च = जनैः न निन्द्यः; not blamable, censurable, reprehensible by people;<br> शूरः = पराक्रमशाली; hero, warrior, valiant man;<br> च अपि = च; and also;<br> अविकत्थनः = मिथ्याश्लाघां न करोति यः; not boasting, swaggering, vaunting, bragging;<br> प्रभुः च एव = अधिकारी, पालकः; lord, master, supreme authority;<br> समदृष्टिः = अभेदेन यः पश्यति; having vision of equality;<br> त्रयः = त्रिसङ्खामिताः; three;<br> पुरुषाः = नराः; people;<br> दुर्लभाः = नाधिकं दृश्यन्ते, लभ्यन्ते वा; difficult to obtain, scarce, rare</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>१. यः धनी, लोके निन्दाभाक् न भवति, २. यः पराक्रमी, किन्तु आत्मश्लाघाकारी न भवति, ३. यः पालकः, किन्तु सर्वत्र अभिन्नं पश्यति- एते त्रिविधाः पुरुषाः न सुलभाः।  <br>A wealthy man who is not blamed by people, a warrior who is not boasting, a leader who has vision of equaltiy- these 3 people are rare to find.</td>
                        </tr>
                        <tr class="prasnaa">
                            <td style="width: 90px">प्रश्नाः </td>
                            <td>१.प्रभुः कीदृशः दुर्लभः?  <br>२.के पुरुषाः दुर्लभाः?  <br>३.‘पुरुषास्त्रयः’ इत्यत्र सन्धिः विभज्यताम्।  <br>४.‘अजननिन्द्यः’ इत्यस्य पदविश्लेषणं वदत?  <br>५.‘अविकत्थनः’ इत्यत्र समासविग्रहं वदत? <br>६.------ प्रभुश्चैव। (रिक्तस्थानं पूरयत।)?</td>
                        </tr>
                        

                    </table>
                </div>
                    
                <div id="96" class="total">
                    <div>
                        <button id="moolamsmall96" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('moolam', '96')">मूलम्</button>
                        <button id="padasmall96" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '96')">पदविभागः</button>
                        <button id="anvayasmall96" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '96')">अन्वयः</button>
                        <button id="pratismall96" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '96')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall96" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '96')">तात्पर्यम्</button>
                        <button id="vyakyaasmall96" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('vyakyaa', '96')">वाक्याभ्यासः</button>
                        <button id="prasnaasmall96" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prasnaa', '96')">प्रश्नाः</button>
                    </div>
                    <div class="title">
                        96.दुर्जनः परिहर्तव्यो
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम् </td>
                            <td>दुर्जनः परिहर्तव्यो विद्ययालङ्कृतोऽपि सन् ।<br> मणिना भूषितः सर्पः किमसौ न भयङ्करः ॥ </td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>दुर्जनः परिहर्तव्यः विद्यया अलङ्कृतः अपि सन् । मणिना भूषितः सर्पः किम् असौ न भयङ्करः ॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>दुर्जनः विद्यया अलङ्कृतः अपि सन् परिहर्तव्यः । मणिना भूषितः सर्पः असौ किम् न भयङ्करः?</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>दुर्जनः = दुष्टः; wicked man;<br> विद्यया = ज्ञानेन; by scholarship, knowledge;<br> अलङ्कृतः अपि सन् = भूषितः भूत्वा अपि; even when adorned with;<br> परिहर्तव्यः = त्याज्यः; should be avoided, left;<br> मणिना = रत्नेन; with a gem;<br> भूषितः = अलङ्कृतः; decorated;<br> सर्पः = नागः; snake;<br> असौ = सः; it (lit. he);<br> किम् न = (प्रश्नः); is it not;<br> भयङ्करः = भयमुत्पादयतियः; dangerous, fearful</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>ज्ञानेन आभूषितोऽपि दुष्टात्मा (दूरेणैव) परित्याज्यः। अत्र उदाहरणम्। भुजङ्गः रत्नेन अलङ्कृतोऽपि (सुन्दरः उपगमने योग्यः न भवति) भयमेवोत्पादयति। <br>A wicked man should be abandoned, even when ornate with knowledge. Is a snake not scary even when it is adorned with a jewel?</td>
                        </tr>
                        <tr class="prasnaa">
                            <td style="width: 90px">प्रश्नाः </td>
                            <td>१.कीदृशः दुर्जनः परिहर्तव्यः? <br>२.कीदृशः सर्पः भयङ्करः?  <br>३.‘दुर्जनः’ इत्यत्र समासविग्रहं वदत?  <br>४.‘परिहर्तव्यो’ इत्यस्य पदविश्लेषणं वदत? <br>५.‘विद्ययाऽलङ्कृतोऽपि’ इत्यत्र सन्धिः विभज्यताम्। <br>६.------ भूषितः सर्पः। (रिक्तस्थानं पूरयत।)?</td>
                        </tr>
                        

                    </table>
                </div>
                    
                <div id="97" class="total">
                    <div>
                        <button id="moolamsmall97" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('moolam', '97')">मूलम्</button>
                        <button id="padasmall97" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '97')">पदविभागः</button>
                        <button id="anvayasmall97" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '97')">अन्वयः</button>
                        <button id="pratismall97" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '97')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall97" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '97')">तात्पर्यम्</button>
                        <button id="vyakyaasmall97" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('vyakyaa', '97')">वाक्याभ्यासः</button>
                        <button id="prasnaasmall97" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prasnaa', '97')">प्रश्नाः</button>
                    </div>
                    <div class="title">
                        97.पुण्यस्य फलमिच्छन्ति
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम् </td>
                            <td>पुण्यस्य फलमिच्छन्ति पुण्यं नेच्छन्ति मानवाः ।<br> न पापफलमिच्छन्ति पापं कुर्वन्ति यत्नतः ॥ महाभारतम्</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>पुण्यस्य फलम् इच्छन्ति पुण्यं न इच्छन्ति मानवाः। न पापफलम् इच्छन्ति पापं कुर्वन्ति यत्नतः ॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>मानवाः पुण्यस्य फलम् इच्छन्ति। पुण्यं न इच्छन्ति। पापफलम् न इच्छन्ति। यत्नतः पापं कुर्वन्ति ॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>मानवाः = मनुष्याः; people, human beings;<br> पुण्यस्य = धर्मकार्यस्य; of religious or moral merit, virtuous act;<br> फलम् = परिणामं; fruit, result, outcome;<br> इच्छन्ति = वाञ्छन्ति; (they) desire for;<br> पापफलम् = दुष्कर्मणः परिणामं; fruit of sin, crime;<br> यत्नतः = प्रयत्नेन; by striving, trying;<br> पापं = दुष्क्रियां, दुरितं; sin, crime, guilt, evil;<br> कुर्वन्ति = आचरन्ति; (they) do</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>पुरुषाः धर्मकार्यस्य लाभं काङ्क्षन्ति। किन्तु धर्मकार्याणि न कुर्वन्ति। ते दुष्कृतेः परिणामे इच्छुकाः न भवन्ति, किन्तु प्रयासेन दुरितान्याचरन्ति।  <br>People long for the fruit of virtue; but do not want (to do) virtuous acts. They do not desire for result of sin (i.e. punishment); but by practice, commit [acts of] sins.</td>
                        </tr>
                        <tr class="prasnaa">
                            <td style="width: 90px">प्रश्नाः </td>
                            <td>१.मानवाः किं नेच्छन्ति? <br>२.ते किं कथं कुर्वन्ति?  <br>३.‘नेच्छन्ति’ इत्यत्र सन्धिः विभज्यताम्।  <br>४.‘यत्नतः’ इत्यस्य पदविश्लेषणं वदत? <br>५.------ फलमिच्छन्ति। (रिक्तस्थानं पूरयत।)?</td>
                        </tr>
                        

                    </table>
                </div>
                    
                <div id="98" class="total">
                    <div>
                        <button id="moolamsmall98" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('moolam', '98')">मूलम्</button>
                        <button id="padasmall98" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '98')">पदविभागः</button>
                        <button id="anvayasmall98" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '98')">अन्वयः</button>
                        <button id="pratismall98" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '98')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall98" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '98')">तात्पर्यम्</button>
                        <button id="vyakyaasmall98" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('vyakyaa', '98')">वाक्याभ्यासः</button>
                        <button id="prasnaasmall98" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prasnaa', '98')">प्रश्नाः</button>
                    </div>
                    <div class="title">
                        98.अपां प्रवाहो गाङ्गोऽपि 
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम् </td>
                            <td>अपां प्रवाहो गाङ्गोऽपि समुद्रं प्राप्य तद्रसः।<br> भवत्यवश्यं तद्विद्वान्नाश्रयेदशुभात्मकम्॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>अपां प्रवाहः गाङ्गः अपि समुद्रं प्राप्य तद्-रसः। भवति अवश्यं तत् विद्वान् न आश्रयेद् अशुभात्मकम्॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>अपां प्रवाहः गाङ्गः अपि समुद्रं प्राप्य तद्-रसः। भवति अवश्यं तत् विद्वान् न अशुभात्मकम् आश्रयेद् ॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>अपां = जलस्य; of water;<br> प्रवाहः = धारा; flow;<br> गाङ्गः अपि = गङ्गायाः अपि; of gaṅgā;<br> समुद्रं = उदधिं; sea, ocean;<br> प्राप्य = स्थानं लब्ध्वा; having obtained;<br> तद्-रसः = तदीयं स्वादुत्वं; of that taste [lit. that-essenced];<br> भवति = घटते; it becomes;<br> अवश्यं = निश्चयेन; definitely;<br> तत् = अतः; thus;<br> विद्वान् = पण्डितः; a learned scholar;<br> अशुभात्मकम् = दुष्टं, दुर्जनं; inauspicious, impure, dirty, foul person;<br> न आश्रयेद् = न उपगच्छेत्; should not associate (with)</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>गङ्गानद्याः प्रवाहोऽपि सागरं प्रविश्य तादृशः रसवान् अवश्यं भवति। अतः कृतविद्यः दुष्टात्मानं नरं कदापि न उपेयात्।  <br>Even a stream of water like Ganga having reached the sea, certainly becomes saline (sea-like). Hence, a wise man should never associate with inauspicious persons.</td>
                        </tr>
                        <tr class="prasnaa">
                            <td style="width: 90px">प्रश्नाः </td>
                            <td>१.गाङ्गोऽपि प्रवाहः किं भवति? <br>२.तथा किं न कुर्यात्? <br>३.‘गाङ्गोऽपि’ इत्यत्र सन्धिः विभज्यताम्। <br>४.‘भवत्यवश्यं’ इत्यत्र सन्धिः विभज्यताम्। <br>५.‘अशुभात्मकम्’ इत्यत्र समासविग्रहं वदत?  <br>६.------ अशुभात्मकम्। (रिक्तस्थानं पूरयत।)?</td>
                        </tr>
                        

                    </table>
                </div>
                    
                <div id="99" class="total">
                    <div>
