                        <button id="padasmall99" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '99')">पदविभागः</button>
                        <button id="anvayasmall99" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '99')">अन्वयः</button>
                        <button id="pratismall99" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '99')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall99" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '99')">तात्पर्यम्</button>
                        <button id="vyakyaasmall99" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('vyakyaa', '99')">वाक्याभ्यासः</button>
                        <button id="prasnaasmall99" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prasnaa', '99')">प्रश्नाः</button>
                    </div>
                    <div class="title">
                        99.यदधीतमविज्ञातं 
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम् </td>
                            <td>यदधीतमविज्ञातं निगदेनैव शब्द्यते।<br> अनग्नाविव शुष्कैधो न तज्ज्वलति कर्हिचित्॥ -निरुक्तम्, १.१८</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>यद् अधीतम् अविज्ञातं निगदेन एव शब्द्यते। अनग्नौ इव शुष्क–एधः न तत् ज्वलति कर्हिचित्॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>यद् अधीतम् अविज्ञातं निगदेन एव शब्द्यते। अनग्नौ इव शुष्क–एधः तत् कर्हिचित् न ज्वलति ॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>यद् अधीतम् = यावत् अध्ययनेन प्राप्तं; what[ever] is learnt;<br> अविज्ञातं = न अवगतं; not understood;<br> निगदेन एव = उच्चारणेन एव; recitation, speech, discourse;<br> शब्द्यते = ध्वन्यते; is sounded;<br> अनग्नौ इव = अग्निभिन्नेपदार्थे; not in fire, (absence of fire) (lit. in non-fire);<br> शुष्क–एधः = अनार्द्रम् इन्धनम्; dried fuel (wood);<br> तत् = एतत्; that;<br> कर्हिचित् = कुत्रचित्; anywhere;<br> न ज्वलति = न दीप्यते; does not burn </td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>यत्किञ्चिदधीयते, किन्तु नावबोधति, तत् केवलं शब्दानामुच्चारणं मात्रम्। अत्रोदाहरणम्। यथा अक्लिन्नः एधः वह्निभिन्ने स्थले (पतित्वा) न प्रज्वलति, तथैव। <br>Whatever is learnt without its being understood is called mere cramming; like dry [logs of] wood on an extinguished fire, it can never illuminate.</td>
                        </tr>
                        <tr class="prasnaa">
                            <td style="width: 90px">प्रश्नाः </td>
                            <td>१.किं केन शब्द्यते?  <br>२.तत् किमिव न ज्वलति?  <br>३.‘अनग्नाविव’इत्यत्र सन्धिः विभज्यताम्।  <br>४.‘शुष्कैधो’ इत्यत्र समासविग्रहं वदत?  <br>५.‘शब्द्यते’ इत्यस्य पदविश्लेषणं वदत <br>६.न ------ कर्हिचित्। (रिक्तस्थानं पूरयत।)?</td>
                        </tr>
                        

                    </table>
                </div>
                    
