                        <button id="padasmall100" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '100')">पदविभागः</button>
                        <button id="anvayasmall100" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '100')">अन्वयः</button>
