                    </div>
                    <div class="title">
                        100.पङ्कैर्विना सरो भाति 
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम् </td>
                            <td>पङ्कैर्विना सरो भाति सदः खलजनैर्विना ।<br> कटुवर्णैर्विना काव्यं मानसं विषयैर्विना ॥ -भामिनीविलासः, ११६</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>पङ्कैः विना सरः भाति सदः खलजनैः विना । कटुवर्णैः विना काव्यं मानसं विषयैः विना ॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>सरः पङ्कैः विना भाति। सदः खलजनैः विना (भाति)। काव्यं कटुवर्णैः विना (भाति)। मानसं विषयैः विना (भाति) ॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>सरः = सरोवरं; lake, pond, pool, a large sheet of water;<br> पङ्कैः विना = कर्दमेन विना; without mud, clay;<br> भाति = शोभते; shines, looks beautiful;<br> सदः = सभा; assembly;<br> खलजनैः विना = दुष्टान् विहाय; without wicked people;<br> काव्यं = कविकर्म; poetry;<br> कटुवर्णैः विना = परुषशब्दैः रहितं; without harsh letters;<br> मानसं = मनः; heart, mind;<br> विषयैः विना = लौकिकविषयैः वर्जितं; without worldly or sensory objects</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>जलाशयः कलुषात् ऋते, सभा दुर्जनान् वर्जयित्वा, कविकृतिः कठिनशब्दव्यतिरिक्ता, अन्तरङ्गं च इन्द्रियविषयैर्विना – शोभन्ते।  <br>A pond is beautiful without mud; an assembly is beautiful without wicked men; a poem is beautiful without harsh letters; mind is beautiful without worldly objects.</td>
                        </tr>
                        <tr class="prasnaa">
                            <td style="width: 90px">प्रश्नाः </td>
                            <td>१.सरः कथं भाति? <br>२.कः विषयैर्विना भाति?  <br>३.‘खलजनैर्विना’ इत्यत्र सन्धिः विभज्यताम्। <br>४.‘कटुवर्णैः’ इत्यत्र समासविग्रहं वदत?   <br>५.सदः ------। (रिक्तस्थानं पूरयत।)?  <br>६.‘मानसं’ इत्यस्य पदविश्लेषणं वदत?</td>
                        </tr>
                        

                    </table>
                </div>
                    
                <div id="101" class="total">
                    <div>
