                        <button id="padasmall101" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '101')">पदविभागः</button>
                        <button id="anvayasmall101" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '101')">अन्वयः</button>
                        <button id="pratismall101" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '101')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall101" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '101')">तात्पर्यम्</button>
                        <button id="vyakyaasmall101" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('vyakyaa', '101')">वाक्याभ्यासः</button>
                        <button id="prasnaasmall101" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prasnaa', '101')">प्रश्नाः</button>
                    </div>
                    <div class="title">
                        101.मनो मधुकरो
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम् </td>
                            <td>मनो मधुकरो मेघो मद्यपो मत्कुणो मरुत्।<br> मा मदो मर्कटो मत्स्यो मकारा दश चञ्चलाः॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td></td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>मनः मधुकरः मेघः मद्यपः मत्कुणः मरुत् मा मदः मर्कटः मत्स्यः मकाराः दश चञ्चलाः॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>मनः = अन्तरङ्गं; mind, heart;<br> मधुकरः = भृङ्गः; honey-bee;<br> मेघः = जलदः; cloud;<br> मद्यपः = मधुपानं यः करोति; alcoholic, drunkard;<br> मत्कुणः = कीटविशेषः; bug;<br> मरुत् = वायुः; wind;<br> मा = लक्ष्मीः; Goddess lakṣmī, money, wealth;<br> मदः = हर्षातिरेकः; arrogance, conceit;<br> मर्कटः = वानरः; monkey;<br> मत्स्यः = मीनः; fish;<br> मकाराः = म-वर्णेन उच्चारिताः; ‘ma’ sounding ones (the words starting with letter ‘ma’);<br> दश = दशसङ्ख्याविशिष्टाः; ten;<br> चञ्चलाः = विचलनशीलाः; fickle, unsteady</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>चित्तं, भ्रमरः, घनः, मद्यपानकृत्, मत्कुणः, पवनः, धनदेवता, अतिहर्षः, कपिः, झषः- इति दश अस्थिराः भवन्ति।  <br>The mind, the bee, the cloud, the drunkard, the bug, the wind, wealth, pride, the monkey and the fish are the ten things starting with the letter ‘ma’ that are always unsteady.</td>
                        </tr>
                        <tr class="prasnaa">
                            <td style="width: 90px">प्रश्नाः </td>
                            <td>१.के चञ्चलाः?  <br>२.‘मधुकरो’ इत्यस्य पदविश्लेषणं वदत?  <br>३.मकारा दश ------। (रिक्तस्थानं पूरयत।)? <br>४.‘मद्यपो’ इत्यत्र समासविग्रहं वदत?</td>
                        </tr>
                        

                    </table>
                </div>
                    
                <div id="102" class="total">
                    <div>
                        <button id="moolamsmall102" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('moolam', '102')">मूलम्</button>
                        <button id="padasmall102" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '102')">पदविभागः</button>
                        <button id="anvayasmall102" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '102')">अन्वयः</button>
                        <button id="pratismall102" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '102')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall102" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '102')">तात्पर्यम्</button>
                        <button id="vyakyaasmall102" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('vyakyaa', '102')">वाक्याभ्यासः</button>
                        <button id="prasnaasmall102" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prasnaa', '102')">प्रश्नाः</button>
                    </div>
                    <div class="title">
                        102.विषमां हि दशां
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम् </td>
                            <td>विषमां हि दशां प्राप्य दैवं गर्हयते नरः ।<br> (पाठ. विषमां च दशां प्राप्तो देवान् गर्हति वै भृशम् </td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>विषमां हि दशां प्राप्य दैवं गर्हयते नरः आत्मनः कर्मदोषान् तु न एव जानाति अपण्डितः ॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>नरः हि विषमां दशां प्राप्य दैवं गर्हयते। अपण्डितः आत्मनः कर्मदोषान् तु न एव जानाति ॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>नरः = मनुष्यः; humans;<br> हि = निश्चयेन; indeed;<br> विषमां = प्रतिकूलां; opposite, adverse, unfavorable;<br> दशां = स्थितिं; condition;<br> प्राप्य = लब्ध्वा; having got, obtained;<br> दैवं = भाग्यं; luck, destiny;<br> गर्हयते = निन्दति; blames, censures, reproaches;<br> अपण्डितः = अविवेकी; unscholarly person, less-learned one;<br> आत्मनः = स्वकीयस्य; of self;<br> कर्मदोषान् तु = आचरित-अपराधान्; faults in deeds done, mis-acts;<br> न एव जानाति = नैव अवबोधति; does not understand</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>पुरुषः सङ्कटपरिस्थित्यां पतित्वा अदृष्टं उपालभते। जडबुद्धिः स्वीयाचरिते दुष्कृतीः नाधिगच्छति। <br>Indeed, having faced with adversities,man blames fate. The unscholarly person does not understand his own faulty [past] actions. </td>
                        </tr>
                        <tr class="prasnaa">
                            <td style="width: 90px">प्रश्नाः </td>
                            <td>१.नरः कदा दैवं गर्हयते?  <br>२.अपण्डितः किं नैव जानाति?  <br>३.जानात्यपण्डितः इत्यत्र सन्धिः विभज्यताम्। <br>४.‘कर्मदोषाः’ इत्यत्र समासविग्रहं वदत? <br>५.‘प्राप्य’ इत्यस्य पदविश्लेषणं वदत? <br>६.दैवं ------ नरः। (रिक्तस्थानं पूरयत।)</td>
                        </tr>
                        

                    </table>
                </div>
                    
                <div id="103" class="total">
                    <div>
                        <button id="moolamsmall103" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('moolam', '103')">मूलम्</button>
                        <button id="padasmall103" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '103')">पदविभागः</button>
                        <button id="anvayasmall103" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '103')">अन्वयः</button>
                        <button id="pratismall103" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '103')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall103" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '103')">तात्पर्यम्</button>
                        <button id="vyakyaasmall103" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('vyakyaa', '103')">वाक्याभ्यासः</button>
                        <button id="prasnaasmall103" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prasnaa', '103')">प्रश्नाः</button>
                    </div>
                    <div class="title">
                        103.अग्निहोत्रं गृहं क्षेत्रं 
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम् </td>
                            <td>अग्निहोत्रं गृहं क्षेत्रं गर्भिणीं वृद्धबालकौ।<br> रिक्तहस्तेन नोपेयात् राजानं देवतां गुरुम्॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>अग्निहोत्रं गृहं क्षेत्रं गर्भिणीं वृद्धबालकौ रिक्तहस्तेन न उपेयात् राजानं देवतां गुरुम् ॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>अग्निहोत्रं गृहं क्षेत्रं गर्भिणीं वृद्धबालकौ राजानं देवतां गुरुम् रिक्तहस्तेन न उपेयात् ॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>अग्निहोत्रं = यज्ञकुण्ड-वह्निः; fire;<br> गृहं = गेहं; home;<br> क्षेत्रं = सस्यभूमिं; field;<br> गर्भिणीं = ससत्त्वां; expecting (pregnant) woman;<br> वृद्धबालकौ = स्थविरं च, शिशुं च; old people and children;<br> राजानं = पालकं; king;<br> देवतां = देवं; deity, god;<br> गुरुं = विद्यादातारं; spiritual teacher;<br> रिक्तहस्तेन = शून्यपाणिः; with empty hand;<br> न उपेयात् = न उपगच्छेत्; should not approach</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>यज्ञस्थलं, (बन्ध्वादीनां) निवासं, कृषिस्थलं, गर्भवतीं, वयोऽधिकं, बालम्, अधिपं, नाकवासिनं, आचार्यं च – एतान् (यत्किमपि उपहारं अगृहीत्वा) रिक्तहस्तः न गन्तव्यम्। <br>One should not go empty–handed to the [holy] fire,home, field, pregnant woman, old people, child, king, deity and spiritual teacher.</td>
                        </tr>
                        <tr class="prasnaa">
                            <td style="width: 90px">प्रश्नाः </td>
                            <td>१.कान् रिक्तहस्तेन नोपेयात्?  <br>२.‘वृद्धबालकौ’ इत्यत्र समासविग्रहं वदत?  <br>३.‘गर्भिणीं’ इत्यस्य पदविश्लेषणं वदत? <br>४.------ नोपेयात्। (रिक्तस्थानं पूरयत।)?</td>
                        </tr>
                        

                    </table>
                </div>
                    
                <div id="104" class="total">
                    <div>
                        <button id="moolamsmall104" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('moolam', '104')">मूलम्</button>
                        <button id="padasmall104" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '104')">पदविभागः</button>
                        <button id="anvayasmall104" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '104')">अन्वयः</button>
                        <button id="pratismall104" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '104')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall104" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '104')">तात्पर्यम्</button>
                        <button id="vyakyaasmall104" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('vyakyaa', '104')">वाक्याभ्यासः</button>
                        <button id="prasnaasmall104" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prasnaa', '104')">प्रश्नाः</button>
                    </div>
                    <div class="title">
                        104.परोक्षे कार्यहन्तारं 
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम् </td>
                            <td>परोक्षे कार्यहन्तारं प्रत्यक्षे प्रियवादिनम्।<br>  वर्जयेत्तादृशं मित्रं विषकुम्भपयोमुखम्॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>परोक्षे कार्यहन्तारं प्रत्यक्षे प्रियवादिनम्। वर्जयेत् तादृशं मित्रं विषकुम्भ–पयोमुखम्॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>परोक्षे कार्यहन्तारं, प्रत्यक्षे प्रियवादिनम्, तादृशं विषकुम्भ–पयोमुखम् मित्रं वर्जयेत् ॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>परोक्षे = अप्रत्यक्षे; out of or beyond the range of sight, away from view;<br> कार्यहन्तारं = क्रियायाः विनाशकं; destroyer (spoiler) of work;<br> प्रत्यक्षे = साक्षात् स्थितौ; present, in sight, before the eye;<br> प्रियवादिनम् = मधुरवक्तारं; sweet-speaking one;<br> विषकुम्भ–पयोमुखम् = घटान्ते गरलं, घटतले दुग्धं यस्य; poison pot, with milk-[looking]surface;<br> तादृशं मित्रं = तद्विधं सुहृदं; such a friend;<br> वर्जयेत् = परित्यजेत्; should abandon, leave off</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>अनुपस्थितौ उद्देश्यघातकं, उपस्थितौ तु स्निग्धवाचकं, अन्तः क्ष्वेडधारिणं बहिस्तु क्षीरधारकं भाण्डमिव सङ्गिनं त्यजेत्। <br>Such a friend must be abandoned, who ruins [our] work in the back and talks sweet in front. He isa pot of poison, looking like milk on surface.</td>
                        </tr>
                        <tr class="prasnaa">
                            <td style="width: 90px">प्रश्नाः </td>
                            <td>१.कीदृशं मित्रं वर्जयेत्?  <br>२.‘विषकुम्भपयोमुखम्’ इत्यत्र समासविग्रहं वदत?  <br>३.‘कार्यहन्तारं’ इत्यत्र समासविग्रहं वदत?  <br>४.प्रत्यक्षे ------। (रिक्तस्थानं पूरयत।)?</td>
                        </tr>
                        

                    </table>
                </div>
                    
                <div id="105" class="total">
                    <div>
                        <button id="moolamsmall105" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('moolam', '105')">मूलम्</button>
                        <button id="padasmall105" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '105')">पदविभागः</button>
                        <button id="anvayasmall105" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '105')">अन्वयः</button>
                        <button id="pratismall105" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '105')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall105" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '105')">तात्पर्यम्</button>
                        <button id="vyakyaasmall105" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('vyakyaa', '105')">वाक्याभ्यासः</button>
                        <button id="prasnaasmall105" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prasnaa', '105')">प्रश्नाः</button>
                    </div>
                    <div class="title">
                        105.श्रद्धाभक्तिसमायुक्ता 
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम् </td>
                            <td>श्रद्धाभक्तिसमायुक्ता नान्यकार्येषु लालसाः।<br> वाग्यताः शुचयश्चैव श्रोतारः पुण्यशालिनः॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>सुलभः</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>श्रद्धा–भक्ति–समायुक्ताः अन्यकार्येषु न लालसाः वाग्यताः शुचयः च एव श्रोतारः पुण्यशालिनः (भवन्ति)॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>श्रद्धा–भक्ति–समायुक्ताः = श्रद्धायुताः, भक्तियुताः च; endowed with;<br> श्रद्धा; and devotion;<br> (श्रद्धा = intranslatable word; It is- devotedness, preparedness, trust in śāstra, reverence for guru, belief in system, confidence in self- all combined together.;<br> अन्यकार्येषु = इतरकर्मसु; in any other works;<br> न लालसाः = न आसक्ताः; not absorbed in;<br> वाग्यताः = वाचि नियन्त्रिताः; of controlled, restrained speech;<br> शुचयः च एव = शुद्धात्मानः; of clean mind and thought, pure, upright;<br> श्रोतारः = ये शृण्वन्ति ते; listeners, audience;<br> पुण्यशालिनः = पुण्यात्मानः; filled with (religious or moral) merit, virtuous</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>ये श्रवणकर्तारः श्रद्धायुक्ताः, भक्तियुक्ताश्च, कार्यान्तरेषु न मग्नाः, नियतवाचिनः, निर्मलान्तःकरणाः च, ते पुण्यात्मानः भवन्ति।  <br>Virtuous listeners are those who possess reverence and devotion, whose minds are not taking pleasure in other things, who are of controlled speech, and are pure.</td>
                        </tr>
                        <tr class="prasnaa">
                            <td style="width: 90px">प्रश्नाः </td>
                            <td>१.के पुण्यशालिनः? <br>२.‘श्रद्धाभक्तिसमायुक्ताः’ इत्यत्र समासविग्रहं वदत?  <br>३.‘वाग्यताः’ इत्यस्य पदविश्लेषणं वदत? <br>४.‘पुण्यशालिनः’ इत्यत्र समासविग्रहं वदत? <br>५.‘शुचयश्चैव’ इत्यत्र सन्धिः विभज्यताम्। <br>६.------ लालसाः। (रिक्तस्थानं पूरयत।)</td>
                        </tr>
                        

                    </table>
                </div>
                    
                <div id="106" class="total">
                    <div>
                        <button id="moolamsmall106" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('moolam', '106')">मूलम्</button>
                        <button id="padasmall106" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '106')">पदविभागः</button>
                        <button id="anvayasmall106" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '106')">अन्वयः</button>
                        <button id="pratismall106" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '106')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall106" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '106')">तात्पर्यम्</button>
                        <button id="vyakyaasmall106" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('vyakyaa', '106')">वाक्याभ्यासः</button>
                        <button id="prasnaasmall106" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prasnaa', '106')">प्रश्नाः</button>
                    </div>
                    <div class="title">
                        106.सम्पूर्णकुम्भो न करोति 
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम् </td>
                            <td>सम्पूर्णकुम्भो न करोति शब्दमर्धो घटो घोषमुपैति नूनम् ।<br> (पाठ. घोषमुपैति सम्यक्) विद्वान्‌ कुलीनो न करोति गर्वं मूढास्तु जल्पन्ति गुणैर्विहीनाः॥ (पाठ. विद्वान्नरो यो) (पाठ. गुणैर्विहीना बहु वादयन्ति)</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>सम्पूर्णकुम्भः न करोति शब्दं अर्धः घटः घोषम् उपैति नूनं । विद्वान्‌ कुलीनः न करोति गर्वं मूढाः तु जल्पन्ति गुणैः विहीनाः॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>सम्पूर्णकुम्भः शब्दं न करोति। अर्धः घटः नूनं घोषम् उपैति। विद्वान्‌ कुलीनः गर्वं न करोति। मूढाः तु गुणैः विहीनाः जल्पन्ति ॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>सम्पूर्णकुम्भः = पूर्णः घटः; a full ( = filled) pot;<br> शब्दं = ध्वनिं; sound;<br> न करोति = नाचष्टे; does not do;<br> अर्धः = अपूर्णः; half;<br> घटः = कुम्भः; pot;<br> नूनं घोषम् = बहु ध्वनिं; very much noise;<br> उपैति = (अत्र) करोति; makes (lit. under goes);<br> विद्वान्‌ = विवेकी; learned scholar;<br> कुलीनः = सत्कुले जातः; of noble family;<br> गर्वं = अत्यभिमानं; pride, haughtiness;<br> न करोति = नाचरति; does not do (here- become);<br> मूढाः तु = जडधियः तु; fools, block-heads;<br> गुणैः = सुगुणैः; by good qualities;<br> विहीनाः = रहिताः; devoid of, destitute or deprived of;<br> जल्पन्ति = वृथा आलपन्ते; babble, prattle</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>सम्भृतः कलशः निस्वनं न करोति। अर्धसम्भृतस्तु अधिकं निनदं करोति। उत्तमकुलोत्पन्नः पण्डितः दुरभिमानी न भवति। मूर्खाः, गुणहीनाः तु व्यर्थं वदन्ति।  <br>A completely filled pot does not make sound. A half filled pot makes lot of noise. A scholar of good family does not become haughty. Only the foolish, bereft of good qualities, babble. </td>
                        </tr>
                        <tr class="prasnaa">
                            <td style="width: 90px">प्रश्नाः </td>
                            <td>१.कः शब्दं न करोति?  <br>२.कः गर्वं न करोति?  <br>३.‘सम्पूर्णकुम्भो’ इत्यत्र समासविग्रहं वदत। <br>४.अर्धो घटो ------ नूनं। (रिक्तस्थानं पूरयत।)?  <br>५.‘गुणैर्विहीनाः’ इत्यत्र सन्धिः विभज्यताम्।  <br>६.‘उपैति’ इत्यस्य पदविश्लेषणं वदत?</td>
                        </tr>
                        

                    </table>
                </div>
                    
