                        <button id="padasmall107" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '107')">पदविभागः</button>
                        <button id="anvayasmall107" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '107')">अन्वयः</button>
                        <button id="pratismall107" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '107')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall107" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '107')">तात्पर्यम्</button>
                        <button id="vyakyaasmall107" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('vyakyaa', '107')">वाक्याभ्यासः</button>
                        <button id="prasnaasmall107" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prasnaa', '107')">प्रश्नाः</button>
                    </div>
                    <div class="title">
                        107.गुणवज्जनसंसर्गात् याति 
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम् </td>
                            <td>गुणवज्जनसंसर्गात् याति नीचोऽपि गौरवम्।<br> पुष्पमालाप्रसङ्गेन सूत्रं शिरसि धार्यते॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>गुणवत्-जनसंसर्गात् याति नीचः अपि गौरवम्। पुष्पमाला–प्रसङ्गेन सूत्रम् शिरसि धार्यते॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>गुणवत्-जनसंसर्गात् नीचः अपि गौरवम् याति। पुष्पमाला–प्रसङ्गेन सूत्रम् शिरसि धार्यते॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>गुणवत्-जनसंसर्गात् = सद्गुणयुक्तं; by being in company ofthose having good qualities, keeping in contact of good-natured people/person;<br> नीचः अपि = अधमः अपि; even a lowly person;<br> गौरवम् = सम्माननं; respect;<br> याति = प्राप्नोति; reaches, attains;<br> पुष्पमाला–प्रसङ्गेन = कुसुमस्रजः साङ्गत्येन; by having contact with garland;<br> सूत्रम् = तन्तुः; thread;<br> शिरसि = मूर्ध्नि; on head;<br> धार्यते = संस्थाप्यते; is kept, is worn</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>सज्जनानां सङ्गतौ हीनोऽपि आदरं प्राप्नोति। प्रसूनानां मालया संयुक्तः सन् तन्तुरपि उत्तमाङ्गे परिगृह्यते। <br>By the company of virtuous people, even a lowly person attains respect. The thread, due to its association with the flowers, is worn on the head [respected]. [It’s a popular tradition among women to wear flowers to decorate hair.]</td>
                        </tr>
                        <tr class="prasnaa">
                            <td style="width: 90px">प्रश्नाः </td>
                            <td>१.कः अपि केन गौरवं याति? <br>२.किं केन कुत्र धार्यते? <br>३.‘गुणवज्जनसंसर्गात्’ इत्यत्र समासविग्रहं वदत? <br>४.‘पुष्पमालाप्रसङ्गेन’ इत्यत्र समासविग्रहं वदत?   <br>५.‘नीचोऽपि’ इत्यत्र सन्धिः विभज्यताम्।  <br>६.सूत्रं ------ धार्यते। (रिक्तस्थानं पूरयत।)?</td>
                        </tr>
                        

                    </table>
                </div>
                    
                <div id="108" class="total">
                    <div>
