                        <button id="padasmall108" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '108')">पदविभागः</button>
                        <button id="anvayasmall108" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '108')">अन्वयः</button>
                        <button id="pratismall108" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '108')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall108" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '108')">तात्पर्यम्</button>
                        <button id="vyakyaasmall108" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('vyakyaa', '108')">वाक्याभ्यासः</button>
                        <button id="prasnaasmall108" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prasnaa', '108')">प्रश्नाः</button>
                    </div>
                    <div class="title">
                        108.शब्दजालं महारण्यं 
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम् </td>
                            <td>शब्दजालं महारण्यं चित्तभ्रमणकारणम् ।<br> अतः प्रयत्नाज्ज्ञातव्यं तत्त्वज्ञात् तत्त्वमात्मनः ॥ विवेकचूडामणिः, ६०</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>शब्दजालं महारण्यं चित्तभ्रमण-कारणम् अतः प्रयत्नात् ज्ञातव्यं तत्त्वज्ञात् तत्त्वम् आत्मनः ॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>शब्दजालं महारण्यं चित्तभ्रमण-कारणम् । अतः तत्त्वज्ञात् प्रयत्नात् आत्मनः तत्त्वं ज्ञातव्यम् ॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>शब्दजालं = पदानां जालं; a collection, mass of words;<br> महारण्यं = घनं वनं; great forest;<br> चित्तभ्रमणकारणम् = मनसः विभ्रामकं; cause of confusion in mind;<br> अतः = अनेन कारणेन; hence, therefore;<br> तत्त्वज्ञात् = यः सत्यं जानाति तस्मात्; from the one who knows the truth (about Self);<br> प्रयत्नात् = प्रयासेन; through effort;<br> आत्मनः = स्वीयं; of the Self;<br> तत्त्वं = सत्यं; Truth;<br> ज्ञातव्यम् = अवबोद्धव्यं; should know, learn</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>शब्दानां जालं गहनं विपिनमिव। तत् चित्तं भ्रामयति। अतः तथ्यं यः जानाति तस्मात् आत्मतत्त्वं ज्ञातव्यम्। <br>Words are like a dense forest and cause mind to deviate. Therefore one must study aboutSelf Knowledge from a Self-realized person.</td>
                        </tr>
                        <tr class="prasnaa">
                            <td style="width: 90px">प्रश्नाः </td>
                            <td>१.किं महारण्यम्? <br>२.अतः किं कस्मात् कथं ज्ञातव्यम्? <br>३.‘चित्तभ्रमणकारणम्’ इत्यत्र समासविग्रहं वदत? <br>४.‘प्रयत्नाज्ज्ञातव्यं’ इत्यत्र सन्धिः विभज्यताम्।   <br>५.‘तत्त्वज्ञात्’ इत्यस्य पदविश्लेषणं वदत?  <br>६.शब्दजालं महारण्यं ------। (रिक्तस्थानं पूरयत।)?</td>
                        </tr>
                        

                    </table>
                </div>
                    
                <div id="109" class="total">
                    <div>
