                        <button id="padasmall109" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '109')">पदविभागः</button>
                        <button id="anvayasmall109" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '109')">अन्वयः</button>
                        <button id="pratismall109" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '109')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall109" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '109')">तात्पर्यम्</button>
                        <button id="vyakyaasmall109" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('vyakyaa', '109')">वाक्याभ्यासः</button>
                        <button id="prasnaasmall109" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prasnaa', '109')">प्रश्नाः</button>
                    </div>
                    <div class="title">
                        109.वदनं प्रसादसदनं 
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम् </td>
                            <td>वदनं प्रसादसदनं सदयं हृदयं सुधामुचो वाचः ।<br> करणं परोपकरणं येषां केषां न ते वन्द्याः ॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>वदनं प्रसादसदनं सदयं हृदयं सुधामुचः वाचः । करणं परोपकरणं येषां केषां न ते वन्द्याः ॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>वदनं प्रसादसदनं सदयं हृदयं सुधामुचः वाचः । करणं परोपकरणं येषां ते केषां न वन्द्याः ॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>वदनं = मुखं; face;<br> प्रसादसदनं = प्रसन्नतायाः आस्पदं; abode of happiness;<br> सदयं = दयासहितं; compassionate, kind;<br> हृदयं = अन्तरङ्गं; heart;<br> सुधामुचः = मधु स्रवन्तः; releasing (giving out) nectar, expressing sweetness;<br> वाचः = वचनानि; words;<br> करणं = कार्यं; deed, act, action;<br>  परोपकरणं = परेषां उपकृतिः; helping or doing good to others [Service, help, assistance, favour, kindness, obligation to others];<br> येषां = यज्जनानां; of whom;<br> ते = ते जनाः; they;<br> केषां = केषां; whose;<br> न वन्द्याः = न अभिवाद्याः; respectable, adorable</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>येषाम् आननम् आनन्दस्य निलयं, हृच्च करुणाभरितं, मधुरशब्दयुक्ता वाक् च भवति, कार्यं च परोपकृतिः, ते केषां न आदरणयोग्या? (सर्वेषां वन्द्याः इति भावः।) <br>Who will not adore those, whose face is abode of happiness, words are nectar-like (sweet),acts are to help others? [Lit. to whom are they adorable not?]</td>
                        </tr>
                        <tr class="prasnaa">
                            <td style="width: 90px">प्रश्नाः </td>
                            <td>१.के वन्द्याः?  <br>२.‘प्रसादसदनं’ इत्यत्र समासविग्रहं वदत?  <br>३.‘सुधामुचो’ इत्यत्र समासविग्रहं वदत?  <br>४.‘वन्द्याः’ इत्यस्य पदविश्लेषणं वदत? <br>५.‘सदयं’ इत्यस्य पदविश्लेषणं वदत? <br>६.करणं ------। (रिक्तस्थानं पूरयत।)?</td>
                        </tr>
                        

                    </table>
                </div>
                    
                <div id="110" class="total">
                    <div>
                        <button id="moolamsmall110" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('moolam', '110')">मूलम्</button>
                        <button id="padasmall110" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '110')">पदविभागः</button>
                        <button id="anvayasmall110" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '110')">अन्वयः</button>
                        <button id="pratismall110" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '110')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall110" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '110')">तात्पर्यम्</button>
                        <button id="vyakyaasmall110" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('vyakyaa', '110')">वाक्याभ्यासः</button>
                        <button id="prasnaasmall110" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prasnaa', '110')">प्रश्नाः</button>
                    </div>
                    <div class="title">
                        110.क्षणशः कणशश्चैव 
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम् </td>
                            <td>क्षणशः कणशश्चैव विद्यामर्थं च साधयेत् ।<br> क्षणे नष्टे कुतो विद्या कणे नष्टे कुतो धनम् ॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>क्षणशः कणशः च एव विद्याम् अर्थं च साधयेत् । क्षणे नष्टे कुतः विद्या कणे नष्टे कुतः धनम् ॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>क्षणशः कणशः च एव विद्याम् अर्थं च साधयेत् । क्षणे नष्टे कुतः विद्या कणे नष्टे कुतः धनम् ॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>क्षणशः = प्रत्येकं क्षणात्; from every moment (measure of time equal to 4/5 of a second);<br> कणशः च एव = प्रत्येकं कणात्; from every grain, a small bit of anything;<br> विद्यां = ज्ञानं; knowledge;<br> अर्थं च = धनं च; wealth, purpose;<br> साधयेत् = सिद्धिं कुर्यात्; should gain;<br> क्षणे नष्टे = यदा क्षणः अपैति; when a moment is lost;<br> कुतः = कस्मात्; from where, whence;<br> कणे नष्टे = कणः यदा विनश्यति तदा; when a grain is lost, [when even that] little bit is lost;<br> धनम् = वित्तं; money</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>क्षणं क्षणं उपयुज्य विद्यार्जनं, कणं कणं च प्रयुज्य धनार्जनं चकुर्यात्। काले विनष्टे विद्यार्जनं न साध्यम्। वस्तुनि नष्टे सति धनार्जनं न सिद्ध्यति। <br>One should learn from every moment, and earn wealth (or attain purpose) from each grain (every little bit). When time is lost, where is knowledge; and when grain is lost, where is money? (or when the little bit is lost, how is the purpose attained)?</td>
                        </tr>
                        <tr class="prasnaa">
                            <td style="width: 90px">प्रश्नाः </td>
                            <td>१.विद्यामर्थं कथं साधयेत्? <br>२.कुतः? <br>३.‘क्षणे नष्टे’ इत्यत्र केन सप्तमी? <br>४.‘कणशश्चैव’ इत्यत्र सन्धिः विभज्यताम्। <br>५.कणे नष्टे ------ ------। (रिक्तस्थानं पूरयत।)?</td>
                        </tr>
                        

                    </table>
                </div>
                    
                <div id="111" class="total">
                    <div>
                        <button id="moolamsmall111" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('moolam', '111')">मूलम्</button>
                        <button id="padasmall111" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '111')">पदविभागः</button>
                        <button id="anvayasmall111" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '111')">अन्वयः</button>
                        <button id="pratismall111" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '111')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall111" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '111')">तात्पर्यम्</button>
                        <button id="vyakyaasmall111" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('vyakyaa', '111')">वाक्याभ्यासः</button>
                        <button id="prasnaasmall111" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prasnaa', '111')">प्रश्नाः</button>
                    </div>
                    <div class="title">
                        111.आचारः परमो धर्म
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम् </td>
                            <td>आचारः परमो धर्म आचारः परमं तपः।<br> आचारः परमो धर्म आचारः परमं तपः</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>आचारः परमः धर्मः आचारः परमं तपः। आचारः परमं ज्ञानम् आचरात् किं न साध्यते॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td></td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>आचारः = सदाचारः, नियमानुष्ठानं; (here- Practicing of) any customary observance or duty;<br> परमः = उन्नतः, उत्तमः; highest, best, most excellent, greatest;<br> धर्मः = कर्तव्यम्; (here) sacred duty;<br> परमं तपः = उत्तमं तपः (वैधक्लेशजनकं कर्म); greatest penance;<br> परमं ज्ञानम् = उत्कृष्टः बोधः; superior knowledge;<br> आचरात् = सदाचरणेन, नियमानुष्ठानेन; through practicing;<br> किं = कः पदार्थः; what;<br> न साध्यते = न प्राप्तुं शक्यते; is not possible?</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>सदाचारानुष्ठानमेव उन्नतः धर्मः, उत्तमं तपः, उत्कृष्टं ज्ञानं च भवति। नियमानुष्ठानेन किं वा न साधयितुं शक्नोति पुरुषः? <br>Practicing is the highest dharma (sacred duty), greatest penance, superior knowledge. What is that which can't be achieved through practicing.</td>
                        </tr>
                        <tr class="prasnaa">
                            <td style="width: 90px">प्रश्नाः </td>
                            <td>१.आचारःनामकिम्? स्ववाक्येषु विवृणुत। <br>२.तपः इति किंलिङ्गकं पदम्?  <br>३.आचारात् इत्यत्र कः विभक्तिः?</td>
                        </tr>
                        

                    </table>
                </div>
                    
                <div id="112" class="total">
                    <div>
                        <button id="moolamsmall112" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('moolam', '112')">मूलम्</button>
                        <button id="padasmall112" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '112')">पदविभागः</button>
                        <button id="anvayasmall112" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '112')">अन्वयः</button>
                        <button id="pratismall112" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '112')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall112" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '112')">तात्पर्यम्</button>
                        <button id="vyakyaasmall112" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('vyakyaa', '112')">वाक्याभ्यासः</button>
                        <button id="prasnaasmall112" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prasnaa', '112')">प्रश्नाः</button>
                    </div>
                    <div class="title">
                        112.सर्वद्रव्येषु विद्यैव 
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम् </td>
                            <td>सर्वद्रव्येषु विद्यैव द्रव्यमाहुरनुत्तमम् ।<br> अहार्यत्वादनर्घ्यत्वादक्षयत्वाच्च सर्वदा ॥ -हितोपदेशः</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>सर्वद्रव्येषु विद्या एव द्रव्यम् आहुः अनुत्तमम् । अहार्यत्वाद् अनर्घ्यत्वाद् अक्षयत्वात् च सर्वदा ॥ </td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>सर्वद्रव्येषु विद्या एव सर्वदा अहार्यत्वाद् अनर्घ्यत्वाद् अक्षयत्वात् च अनुत्तमम् द्रव्यम् आहुः ॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>सर्वद्रव्येषु = सर्ववस्तुषु; among all objects, substances;<br> विद्या एव = ज्ञानं; knowledge (learning) only;<br> सर्वदा = सर्वसमयेषु; always;<br> अहार्यत्वाद् = न शक्यते हर्तुमिति कारणेन; because of unstealability;<br> अनर्घ्यत्वाद् = अमूल्यत्वात्; because of invaluability, pricelessness;<br> अक्षयत्वात् च = क्षयं न यातीति कारणेन; because of imperishability;<br> अनुत्तमम् = अस्मात्परं न किञ्चिद् भवतीति; nothing better than this, the best;<br> द्रव्यम् = वस्तु; substance;<br> आहुः = इति वदन्ति; they say</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>सर्वधनेषु सर्वदा विद्याधनं प्रधानं भवति। नास्मादुत्तमं किञ्चिदन्यत् भवति। तस्य गुणा एवम्- विद्या न केनचित् हर्तुं शक्यते, तस्य मूल्यं इयदिति वक्तुं न शक्यते, तस्याः दानेनापि सा वर्धते, न तु क्षीयते।  <br>They say- Knowledge is the supreme-most among all substances in the world- because it is unstealable, invaluable, and always imperishable.</td>
                        </tr>
                        <tr class="prasnaa">
                            <td style="width: 90px">प्रश्नाः </td>
                            <td>१.सर्वद्रव्येषुकिंअनुत्तमम्?  <br>२.अहार्यं नाम किम्?   <br>३.कथं विद्या अक्षयद्रव्यं भवति? <br>४.‘अनर्घ्य’-शब्दस्य पदविश्लेषणं वदत?  <br>५.‘अक्षयत्वात्’ इत्यत्र पञ्चमी कथम्?  <br>६.‘सर्वद्रव्येषु’ इत्यत्र कथं सप्तमी?</td>
                        </tr>
                        

                    </table>
                </div>
                    
                <div id="113" class="total">
                    <div>
                        <button id="moolamsmall113" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('moolam', '113')">मूलम्</button>
                        <button id="padasmall113" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '113')">पदविभागः</button>
                        <button id="anvayasmall113" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '113')">अन्वयः</button>
                        <button id="pratismall113" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '113')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall113" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '113')">तात्पर्यम्</button>
                        <button id="vyakyaasmall113" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('vyakyaa', '113')">वाक्याभ्यासः</button>
                        <button id="prasnaasmall113" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prasnaa', '113')">प्रश्नाः</button>
                    </div>
                    <div class="title">
                        113.दूरस्थो ज्ञायते 
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम् </td>
                            <td>दूरस्थो ज्ञायते सर्वः पर्वते ज्वलनादिवत् ।<br> चूडामणिः शिरस्थोऽपि दृश्यते न स्वचक्षुषा ॥ रामायणमञ्जरी, किष्किंदा</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>दूरस्थः ज्ञायते सर्वः पर्वते ज्वलनादिवत् चूडामणिः शिरस्थः अपि दृश्यते न स्वचक्षुषा ।</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>दूरस्थः सर्वः पर्वते ज्वलनादिवत् ज्ञायते। चूडामणिः शिरस्थः अपि स्वचक्षुषा न दृश्यते ।</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>दूरस्थः = अनिकटम्, असन्निकृष्टम्, दूरे स्थितः; situated faraway;<br> सर्वः = समस्तं; everything;<br> पर्वते = उत्तुङ्गशैले; on the mountain;<br> ज्वलनादिवत् = अग्निवत्; like the fire;<br> ज्ञायते = अवगम्यते; is known;<br> चूडामणिः = मूर्धाभरणम्, शिरोरत्नम्; a jewel worn on the top of the head, a crest-jewel;<br> शिरस्थः अपि = मूर्ध्नि स्थितोऽपि; even when situated on (one’s own) head;<br> स्वचक्षुषा = स्वस्य अक्षिभ्याम्; with own eye;<br> न दृश्यते = न लक्ष्यते, न गोचरीभवति; cannot be seen</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>यथा पर्वते ज्वलद् वह्निः दूरतः अपि द्रष्टुं शक्यते तथा, दूरे स्थितं कश्चित् वस्तु सम्पूर्णतया दृश्यते। किन्तु यत् स्वसमीपे वर्तते, तदपि कदाचित् द्रष्टुं न पारयामः। यथा चूडामणिः शिरसि वर्तमानः अपि स्वस्य नेत्राभ्यां साक्षात् द्रष्टुं न शक्यते, तथैव। <br>Everything faraway can be known, like the fire on the mountain. But crest-jewel cannot be seen by one’s own eyes.</td>
                        </tr>
                        <tr class="prasnaa">
                            <td style="width: 90px">प्रश्नाः </td>
                            <td>१.दूरस्थःसर्वःकथंज्ञायते?  <br>२.स्वचक्षुषा किं न दृश्यते?  <br>३.चूडामणिः कुत्र वर्तते?  <br>४.‘दृश्यते’ इति शब्दस्य पदविश्लेषणं वदत?  <br>५.‘ज्वलनादिवत्’ इत्यत्र समासविग्रहं वदत?  <br>६.अस्य श्लोकस्य अन्तरार्थः कः?</td>
                        </tr>
                        

                    </table>
                </div>
                    
                <div id="114" class="total">
                    <div>
                        <button id="moolamsmall114" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('moolam', '114')">मूलम्</button>
                        <button id="padasmall114" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '114')">पदविभागः</button>
                        <button id="anvayasmall114" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '114')">अन्वयः</button>
                        <button id="pratismall114" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '114')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall114" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '114')">तात्पर्यम्</button>
                        <button id="vyakyaasmall114" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('vyakyaa', '114')">वाक्याभ्यासः</button>
                        <button id="prasnaasmall114" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prasnaa', '114')">प्रश्नाः</button>
                    </div>
                    <div class="title">
                        114.प्रेक्षणीयः प्रयत्नेन 
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम् </td>
                            <td>प्रेक्षणीयः प्रयत्नेन स्वभावो नेतरे गुणाः अतीत्य हि गुणान् सर्वान् स्वभावो मूर्ध्नि वर्तते ॥।<br></td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>प्रेक्षणीयः प्रयत्नेन स्वभावः न इतरे गुणाः । अतीत्य हि गुणान् सर्वान् स्वभावः मूर्ध्नि वर्तते॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>स्वभावः प्रयत्नेन प्रेक्षणीयः। इतरे गुणाः न । गुणान् सर्वान् अतीत्य हि स्वभावः मूर्ध्नि वर्तते ॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>स्वभावः = अन्तःप्रकृतिः, स्वकीयभावः, निसर्गः; inner nature;<br> प्रयत्नेन = प्रकृष्टेन यत्नेन; by efforts;<br> प्रेक्षणीयः = परिशीलनीयः, सूक्ष्मतया दर्शनीयः; should be observed;<br> न इतरे = नान्ये; not others;<br> गुणाः = विशेषलक्षणानि; qualities;<br> गुणान् सर्वान् = समस्तान् गुणान्; all the qualities;<br> अतीत्य हि = अतिरिच्य, अतिक्रम्य; surpassing;<br> मूर्ध्नि = शिरसि; on head;<br> वर्तते = भवति; stays, is there</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>मानवस्य प्रकृतिरेव परिशीलनीयः। न इतने गुणाः (गौणत्वात्)। समस्तगुणान् अतिरिच्य स्वकीया प्रकृतिरेव प्रमुखा वर्तते। (तत्परिशीलनेन सर्वे गुणाः ज्ञायन्ते।  <br>One should observe the inner nature carefully, and not other qualities. Surpassing all (general) qualities, inner nature happens to be head of them.</td>
                        </tr>
                        <tr class="prasnaa">
                            <td style="width: 90px">प्रश्नाः </td>
                            <td>१.कःप्रेक्षणीयः? <br>२.के न प्रेक्षणीयाः? <br>३.स्वभावः कुत्र वर्तते? <br>४.अतीत्य -- अस्य शब्दस्य पदविश्लेषणं वदत? <br>५.प्रेक्षणीयः -- अस्मिन् शब्दे कः प्रत्ययः? <br>६.मूर्ध्नि वर्तते- इत्यस्य कोऽभिप्रायः?</td>
                        </tr>
                        

                    </table>
                </div>
                    
                <div id="115" class="total">
                    <div>
                        <button id="moolamsmall115" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('moolam', '115')">मूलम्</button>
                        <button id="padasmall115" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '115')">पदविभागः</button>
                        <button id="anvayasmall115" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '115')">अन्वयः</button>
                        <button id="pratismall115" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '115')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall115" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '115')">तात्पर्यम्</button>
                        <button id="vyakyaasmall115" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('vyakyaa', '115')">वाक्याभ्यासः</button>
                        <button id="prasnaasmall115" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prasnaa', '115')">प्रश्नाः</button>
                    </div>
                    <div class="title">
                        115.गुरुर्बन्धुरबन्धूनां
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम् </td>
                            <td>गुरुर्बन्धुरबन्धूनां गुरुश्चक्षुरचक्षुषां ।<br> गुरुः पिता च माता च सर्वेषां न्यायवर्तिनां ॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>गुरुः बन्धुः अबन्धूनां गुरुः चक्षुः अचक्षुषां । गुरुः पिता च माता च सर्वेषां न्यायवर्तिनां ॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>गुरुः अबन्धूनां बन्धुः। गुरुः अचक्षुषां चक्षुः। सर्वेषां न्यायवर्तिनां गुरुः पिता च माता च ॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>गुरुः = अध्यापकः, उपाध्यायः, आचार्यः; preceptor, teacher, preacher;<br> बन्धुः = ज्ञातिः, स्वजनः; brother, kin, relative;<br> अबन्धूनां = बन्धुविहीनानां, स्वजनरहितानां; of those who do not have any brothers or kinsmen;<br> चक्षुः = अक्षि, नयनं; eye;<br> अचक्षुषां = चक्षुरहितानां, अक्षिविहीनानां; of those without eyes (blind);<br> पिता = जनकः, जन्मदाता; father;<br> माता = जननी, जनयित्री; mother;<br> सर्वेषां = सर्वजनानां; of everyone, all;<br> न्यायवर्तिनां = सन्मार्गगामिनां; for those who travel on righteous path</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>अध्यापकः अथवा उपाध्यायः बान्धवविहीनानां बन्धुरिव भवति। सः दृष्टिहीनानां दृष्टिः भूत्वा सन्मार्गं दर्शयति। सः सत्पथगामिनां न्यायमार्गावलम्बिनां पितराविव भवति। <br>Guru is the relative of those without relatives. He is the eyes of those without sight. He is the father and mother to all those who travel on the righteous path of life. (Guru is one’s everything.. like  God. He helps us to see the Truth.)</td>
                        </tr>
                        <tr class="prasnaa">
                            <td style="width: 90px">प्रश्नाः </td>
                            <td>१.गुरुःकस्यबन्धुःभवति?  <br>२.गुरुः अचक्षुषां किं भवति?  <br>३.गुरुः न्यायवर्तिनां किं भवति?  <br>४.‘न्यायवर्तिनां’शब्दस्य व्युत्पत्तिं दर्शयत।  <br>५.‘अबन्धूनां’ इत्यत्र समासविग्रहं वदत?  <br>६.अचक्षुषां चक्षुः इत्यस्य कोऽर्थः?</td>
                        </tr>
                        

                    </table>
                </div>
                    
                <div id="116" class="total">
                    <div>
                        <button id="moolamsmall116" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('moolam', '116')">मूलम्</button>
                        <button id="padasmall116" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '116')">पदविभागः</button>
                        <button id="anvayasmall116" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '116')">अन्वयः</button>
                        <button id="pratismall116" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '116')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall116" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '116')">तात्पर्यम्</button>
                        <button id="vyakyaasmall116" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('vyakyaa', '116')">वाक्याभ्यासः</button>
                        <button id="prasnaasmall116" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prasnaa', '116')">प्रश्नाः</button>
                    </div>
                    <div class="title">
                        116.को न याति वशं लोके 
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम् </td>
                            <td>को न याति वशं लोके मुखं पिण्डेन पूरितः ।<br> मृदङ्गो मुखलेपेन करोति मधुरं ध्वनिं ॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>कः न याति वशं लोके मुखं पिण्डेन पूरितः । मृदङ्गः मुखलेपेन करोति मधुरं ध्वनिं ॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>लोके कः मुखं पिण्डेन पूरितः वशं न याति? मृदङ्गः मुखलेपेन मधुरं ध्वनिं करोति ॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>लोके = जगति; in this world;<br> मुखं = मनुष्यपक्षे– आस्यं, मृदङ्गपक्षे– ध्वनये ताडनस्थानं; mouth, part where the instrument is striken for playing music (pun on the word);<br> पिण्डेन = मनुष्यपक्षे– अन्नकवलेन, मृदङ्गपक्षे– आर्द्रपिष्टेन; with a morsel of food, by a paste of flour (pun on the word);<br> पूरितः = भरितः; filled;<br> वशं = अधीनं; into control;<br> न याति = न भवति; does not go/ reach/ get;<br> मृदङ्गः = सङ्गीते वाद्यवस्तु लयकारकः; a South-Indian musical instrument for rhythm and accompaniment;<br> मुखलेपेन = मुखस्य अवलेपनेन; by mouth smearing;<br> मधुरं = श्रोतुं सुन्दरं, श्रवणसुखकरं; sweet;<br> ध्वनिं = sound; करोति = does</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>लोके कः मनुष्यः अन्नकवलेन दानेन दातुः अधीनो न भवति? मृदङ्गः अपि पिण्डेन ( = आर्द्र-पिष्टस्य-लेपनेन) पूरितः सन् सुन्दरं शब्दं करोति, मधुरं ध्वनति।  <br>Who does not get into control when mouth is filled with morsel of food? Mṛdaṅga makes beautiful sound when its mouth is smeared (with piṇḍa = paste of flour). [For better quality of sound, some (wheat flour-) paste is applied to the part where the instrument is striken for playing music. Poet compares it with giving someone their mouthful (of food) and getting them into his  control on that basis.]</td>
                        </tr>
                        <tr class="prasnaa">
                            <td style="width: 90px">प्रश्नाः </td>
                            <td>१.लोके मनुष्यः कथं वशं याति? <br>२.मृदङ्गः कथं मधुरं ध्वनति?  <br>३.अत्र पिण्डशब्दस्य कौ अर्थौ?  <br>४.‘मुखलेपेन’ इत्यत्र समासविग्रहं वदत?</td>
                        </tr>
                        

                    </table>
                </div>
                    
                <div id="117" class="total">
                    <div>
