                        <button id="padasmall117" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '117')">पदविभागः</button>
                        <button id="anvayasmall117" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '117')">अन्वयः</button>
                        <button id="pratismall117" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '117')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall117" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '117')">तात्पर्यम्</button>
                        <button id="vyakyaasmall117" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('vyakyaa', '117')">वाक्याभ्यासः</button>
                        <button id="prasnaasmall117" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prasnaa', '117')">प्रश्नाः</button>
                    </div>
                    <div class="title">
                        117.महाजनस्य संसर्गः 
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम् </td>
                            <td>महाजनस्य संसर्गः कस्य नोन्नतिकारकः।<br> पद्मपत्रस्थितं तोयं धत्ते मुक्ताफलश्रियम्॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>महाजनस्य संसर्गः कस्य न उन्नति-कारकः। पद्मपत्र-स्थितं तोयं धत्ते मुक्ताफल-श्रियम्॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>महाजनस्य संसर्गः कस्य न उन्नति–कारकः। पद्मपत्र–स्थितं तोयं मुक्ताफल-श्रियम् धत्ते ॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>महाजनस्य = सत्पुरुषस्य; of great person (people);<br> संसर्गः = परिचयः, सम्बन्धः; company, association, contact;<br> कस्य = कस्य नरस्य; whose, for whom;<br> उन्नति–कारकः न = वृद्धिः-समृद्धि-उदय-कारणं; not cause of growth, height, progress;<br> पद्मपत्र–स्थितं = कमलदले विद्यमानं; that which is upon a lotus leaf;<br> तोयं = जलं; water;<br> मुक्ताफल-श्रियं = मोक्तिकसौन्दर्यं; the beauty and virtue of pearl;<br> धत्ते = धरति; wears</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>सज्जनैः सख्यं कस्य अभ्युदयं न कारयति? कमलदले वर्तमानः जलबिन्दुः मौक्तिकवत् प्रकाशसौन्दर्यादिकं भजते। <br>Whom does, being in association with good people, not bring progress? The water [droplet] on a lotus leaf shines like a pearl.</td>
                        </tr>
                        <tr class="prasnaa">
                            <td style="width: 90px">प्रश्नाः </td>
                            <td>१.कः उन्नतिकारकः?  <br>२.केन सह संसर्गः किं करोति?  <br>३.किं मुक्ताफल-श्रियं धत्ते?  <br>४.‘पद्मपत्रस्थितं’ इत्यत्र समासविग्रहं वदत?  <br>५.‘मुक्ताफलश्रियं’ इत्यत्र समासविग्रहं वदत?  <br>६.‘उन्नतिकारकः’ इत्यत्र समासविग्रहं वदत?</td>
                        </tr>
                        

                    </table>
                </div>
                    
                <div id="118" class="total">
                    <div>
