                        <button id="padasmall118" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '118')">पदविभागः</button>
                        <button id="anvayasmall118" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '118')">अन्वयः</button>
                        <button id="pratismall118" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '118')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall118" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '118')">तात्पर्यम्</button>
                        <button id="vyakyaasmall118" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('vyakyaa', '118')">वाक्याभ्यासः</button>
                        <button id="prasnaasmall118" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prasnaa', '118')">प्रश्नाः</button>
                    </div>
                    <div class="title">
                        118.असतोऽपि भवति गुणवान् 
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम् </td>
                            <td>असतोऽपि भवति गुणवान् सद्भ्योऽपि परं भवन्त्यसद्वृत्ताः।<br> पङ्कादुदेति कमलं क्रिमयः कमालादपि भवन्ति॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>असतः अपि भवति गुणवान् सद्भ्यः अपि परं भवन्ति असद्वृत्ताः। पङ्काद् उदेति कमलं क्रिमयः कमालाद् अपि भवन्ति॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>असतः अपि गुणवान् भवति। सद्भ्यः अपि परं असत्–वृत्ताः भवन्ति। पङ्काद् कमलं उदेति। क्रिमयः कमालाद् अपि भवन्ति॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>असतः अपि = दुर्जनादपि; from the wicked;<br> गुणवान् = सद्गुणशीलः, सज्जनः, सुगुणयुक्तः; virtuous one;<br> भवति = जायते; comes out, is born;<br> सद्भ्यः अपि = सज्जनेभ्योऽपि, सत्पुरुषेभ्योऽपि; from noble ones also;<br> परं = किन्तु; but, very much;<br> असत्–वृत्ताः = दुष्टाः, दुर्गुणशीलाः, दुर्जनाः; wicked-natured;<br> पङ्काद् = (मृत्-जल-मिश्रित-कलुषस्थानात्), कर्दमात्, जम्बालात्; from the mud;<br> कमलं = पद्मं, पङ्कजं; lotus;<br> उदेति = प्रभवति, उत्पद्यते; comes out, rises;<br> क्रिमयः = सूक्ष्मजीविनः, कीटादि-अल्पप्राणिनः, क्षुद्रजन्तवः; germs;<br> कमालाद् अपि = पद्मात् अपि; from lotus also;<br> भवन्ति = जायन्ते, प्रभवन्ति; are born</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>दुर्जनेभ्यः सज्जनो जायते कदाचित्। क्वचित् सज्जनेभ्योऽपि दुष्टः उत्पद्यते। (यथा-) कर्दमात् (अशुचिस्थानात्) पद्मं विकसति, तस्मात् पद्मात् एव कीटाणवः जायन्ते।  <br>A virtuous person might arise from (among) wicked people; and evil-minded people can arise from (among) noble ones. Lotus is born out of mud, and germs arise out of even the lotus.</td>
                        </tr>
                        <tr class="prasnaa">
                            <td style="width: 90px">प्रश्नाः </td>
                            <td>१.कुतः गुणवान् भवति? <br>२.सद्भ्योऽपि के भवन्ति? <br>३.क्रिमयः कुतो जायन्ते?  <br>४.‘भवन्त्यसद्वृत्ताः’ इत्यत्र सन्धिः विभज्यताम्?  <br>५.‘पङ्कादुदेति’ इत्यत्र सन्धिः विभज्यताम्?  <br>६.‘असद्वृत्ताः’ इत्यत्र समासविग्रहं वदत?</td>
                        </tr>
                        

                    </table>
                </div>
                    
                <div id="119" class="total">
                    <div>
                        <button id="moolamsmall119" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('moolam', '119')">मूलम्</button>
                        <button id="padasmall119" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '119')">पदविभागः</button>
                        <button id="anvayasmall119" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '119')">अन्वयः</button>
                        <button id="pratismall119" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '119')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall119" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '119')">तात्पर्यम्</button>
                        <button id="vyakyaasmall119" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('vyakyaa', '119')">वाक्याभ्यासः</button>
                        <button id="prasnaasmall119" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prasnaa', '119')">प्रश्नाः</button>
                    </div>
                    <div class="title">
                        119.आत्मनो मुखदोषेण 
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम् </td>
                            <td>आत्मनो मुखदोषेण बध्यन्ते शुकसारिकाः ।<br> बकास्तत्र न बध्यन्ते मौनं सर्वार्थसाधनम् ॥ –पञ्चतन्त्रम् ४.४८</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>आत्मनः मुखदोषेण बध्यन्ते शुक-सारिकाः । बकाः तत्र न बध्यन्ते मौनं सर्वार्थ-साधनम् ॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>शुक-सारिकाः आत्मनः मुखदोषेण बध्यन्ते । बकाः तत्र न बध्यन्ते। मौनं सर्वार्थ-साधनम् ॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>आत्मनः = स्वस्य, स्वीयः; of the self;<br> मुखदोषेन = वाचा आचरित दोषेन, अनुचितस्थाने संवादनेन; by the fault of the mouth (talk);<br> शुक-सारिकाः = पक्षिविशेषाः; parrot, a bird (nightingale/cuckoo?);<br> बकाः = पक्षिविशेषाः; cranes;<br> बध्यन्ते = बन्धनस्थानं यान्ति, जाले, वागुरायां वा पतन्ति; get trapped, tied down;<br> मौनं = तूष्णीं स्थितिः; silence;<br> सर्वार्थ-साधनम् = समस्त-प्रयोजन-सिद्धिकरं; instrument for obtaining all objects</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>शुक-पिकादि-पक्षिणः (अनुचितस्थलेषु) स्वमुखोद्घाटनवशात् (ध्वनिकरणेन) बन्धनं यान्ति। बकस्तु (तूष्णीं तिष्ठतीति कारणेन) कदाचिन्न बन्धे पतति। अतः तूष्णींस्थितिः ( = वाग्व्यापारराहित्यं) सर्वत्र (यत्रकुत्रचित् रहः व्यवहारः, गूढत्वं चापेक्ष्येते तत्र) प्रयोजनानि साधयति। <br>The birds like parrots and cuckoos? get trapped by fault of their mouths (voices/sounds). Cranes do not get trapped. Silence is an instrument for obtaining all objects. [Applies to certain contexts where one needs to be silent, in things related to secrecy and diplomacy.]</td>
                        </tr>
                        <tr class="prasnaa">
                            <td style="width: 90px">प्रश्नाः </td>
                            <td>१.शुकाः कुतः बध्यन्ते? <br>२.बकाः कुतो न बध्यन्ते? <br>३.किं सर्वाथसाधकं भवति?  <br>४.‘मुखदोषेण’ इत्यत्र समासविग्रहं वदत?  <br>५.------ न बध्यन्ते। (रिक्तस्थानं पूरयत।)?  <br>६.‘सर्वाथसाधकं’ इत्यत्र समासविग्रहं वदत?</td>
                        </tr>
                        

                    </table>
                </div>
                    
                <div id="120" class="total">
                    <div>
                        <button id="moolamsmall120" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('moolam', '120')">मूलम्</button>
                        <button id="padasmall120" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '120')">पदविभागः</button>
                        <button id="anvayasmall120" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '120')">अन्वयः</button>
                        <button id="pratismall120" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '120')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall120" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '120')">तात्पर्यम्</button>
                        <button id="vyakyaasmall120" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('vyakyaa', '120')">वाक्याभ्यासः</button>
                        <button id="prasnaasmall120" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prasnaa', '120')">प्रश्नाः</button>
                    </div>
                    <div class="title">
                        120.रत्नैर्महार्हैस्तुतुषुर्न देवा
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम् </td>
                            <td>रत्नैर्महार्हैस्तुतुषुर्न देवा न भेजिरे भीमविषेण भीतिम् ।<br> सुधां विना न प्रययुर्विरामं न निश्चिदार्थाद्विरमन्ति धीराः ॥ –नीतिशतकम्, भर्तृहरिः</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>रत्नैः महार्हैः तुतुषुः न देवाः न भेजिरे भीमविषेण भीतिं । सुधां विना न प्रययुः विरामं न निश्चितार्थात् विरमन्ति धीराः ॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>देवाः महार्हैः रत्नैः न तुतुषुः। भीमविषेण भीतिं न भेजिरे। सुधां विना विरामं न प्रययुः। धीराः निश्चितार्थात् न विरमन्ति ॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>देवाः = द्युर्लोकवासिनः; gods;<br> महार्हैः = अमूल्यैः; by great, valuable, priceless;<br> रत्नैः = तन्नामविशिष्टैः मणिभिः; by gems, precious stones;<br> न तुतुषुः = न तृप्ता अभवन्; did not get satisfied, were not contented;<br> भीमविषेण = भयानक-गरलेन, हालाहलेन; by terrible poison;<br> भीतिं = भयं; fear;<br> न भेजिरे = न प्राप्नुवन्; did not take recourse;<br> सुधां = अमृतम्; amṛtaṃ, the nectar of immortality;<br> विना = रहितं; without;<br> विरामं = अवसानं, विघ्नः; Cessation, discontinuance, pause, termination;<br> न प्रययुः = न प्राप्नुवन्; did not reach;<br> धीराः = धैर्यशालिनः, स्थिरचित्ताः; courageous;<br> निश्चितार्थात् = कृतात् सङ्कल्पात्; from determined, ascertained end, aim, objective;<br> न विरमन्ति = निवर्तन्ते (पृथकग्गच्छन्ति); do not stop, do not cease to act, do not give up</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>द्युलोकवासिनः देवताः अमूल्यमणिभिः न सन्तोषमलभन्त। ते घोरगरलेन (हालाहालेन) न भीताः। यावत् पीयूषं न प्राप्नुवन्, तावत् प्रयत्नं नात्यजन्। सङ्कल्पितेभ्यः कार्येभ्यः धैर्यशालिनो नराः न निवर्तन्ते (पृथकग्गच्छन्ति)।  <br>Gods did not get satisfied by precious stones; were not afraid by dangerous poison; did not stop until they attained the immortality nectar. Courageous people never quit (in) the (middle) goals  they decide (to attain.) </td>
                        </tr>
                        <tr class="prasnaa">
                            <td style="width: 90px">प्रश्नाः </td>
                            <td>१.के कैः न तुतुषुः? <br>२.केन भीतिं न भेजिरे?  <br>३.के तस्मात् न विरमन्ति?  <br>४.‘निश्चितार्थात्’ इत्यत्र समासविग्रहं वदत?  <br>५.‘भेजिरे’ इत्यस्य पदविश्लेषणं वदत? <br>६.‘तुतुषुः’ इत्यस्य पदविश्लेषणं वदत?</td>
                        </tr>
                        

                    </table>
                </div>
                    
                <div id="121" class="total">
                    <div>
                        <button id="moolamsmall121" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('moolam', '121')">मूलम्</button>
                        <button id="padasmall121" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '121')">पदविभागः</button>
                        <button id="anvayasmall121" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '121')">अन्वयः</button>
                        <button id="pratismall121" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '121')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall121" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '121')">तात्पर्यम्</button>
                        <button id="vyakyaasmall121" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('vyakyaa', '121')">वाक्याभ्यासः</button>
                        <button id="prasnaasmall121" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prasnaa', '121')">प्रश्नाः</button>
                    </div>
                    <div class="title">
                        121. साक्षराः विपरीताश्चेत् 
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम् </td>
                            <td>साक्षराः विपरीताश्चेद्राक्षसा एव केवलम्।<br> सरसो विपरीतश्चेत् सरसत्वं न मुञ्चति॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td></td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>साक्षराः विपरीताः चेत् राक्षसाः एव केवलम्। सरसः विपरीतः चेत् सरसत्वं न मुञ्चति॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>साक्षराः = अक्षरलेखनज्ञानिनः; those who can write, learned people in general;<br> विपरीताः = विरुद्धक्रमाः, विपर्ययाः; reversed, opposite;<br> चेत् = यदि; if;<br> राक्षसाः एव = दानवाः; demons verily;<br> केवलम् = मात्रम्; indeed (lit. only);<br> सरसः = सरलः, रसयुक्ताः; charming, lovely, agreeable, beautiful;<br> सरसत्वं = सरलत्वं, रसयुक्ततां; charm;<br> न मुञ्चति = न त्यज्यति; does not leave</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>अक्षराणां विपर्यस्तविन्यासेन अर्थगौरवं वर्णयति पद्यमिदम्। साक्षराः यदि विपरीतमाचरन्ति, (स्वेषामक्षरज्ञानस्य दुरुपयोगं कुर्वन्ति), तर्हि (विपरीताचरणेन अन्याय्येन यस्य हानिर्जाता, तस्मै) ते राक्षसाः (क्रूराः,दुष्टाः) भवन्ति। किन्तु सरसो विपरीत अपि (शब्दक्रमस्य विपर्यासेनापि) सरस एव भवति। (सरसः व्यक्तिः कदाचित् स्वस्य स्वभावं) रसयुक्तत्वं न मुञ्चति।) <br>If [the word] साक्षराः ( = scholars) become otherwise, they turn to राक्षसाः ( = devils). [But] if [the word] सरस ( = charming) is reversed, it does not leave out charmingness. This is play on words and meaning.</td>
                        </tr>
                        <tr class="prasnaa">
                            <td style="width: 90px">प्रश्नाः </td>
                            <td>१.साक्षराः विपरीताः किं भवन्ति?  <br>२.कः सरसत्वं न मुञ्चति?  <br>३.‘विपरीत’शब्दस्य कोऽर्थः? <br>४.‘साक्षराः’ इत्यस्य पदविश्लेषणं वदत?</td>
                        </tr>
                        

                    </table>
                </div>
                    
                <div id="122" class="total">
                    <div>
                        <button id="moolamsmall122" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('moolam', '122')">मूलम्</button>
                        <button id="padasmall122" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '122')">पदविभागः</button>
                        <button id="anvayasmall122" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '122')">अन्वयः</button>
                        <button id="pratismall122" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '122')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall122" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '122')">तात्पर्यम्</button>
                        <button id="vyakyaasmall122" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('vyakyaa', '122')">वाक्याभ्यासः</button>
                        <button id="prasnaasmall122" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prasnaa', '122')">प्रश्नाः</button>
                    </div>
                    <div class="title">
                        122.अपमानितोऽपि कुलजो न वदति 
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम् </td>
                            <td>अपमानितोऽपि कुलजो न वदति परुषं स्वभावदाक्षिण्यात्।<br> न हि मलयचन्दनतरुः परशुप्रहतः स्रवेत् पूयम्॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>अपमानितः अपि कुलजः न वदति परुषं स्वभाव–दाक्षिण्यात्। न हि मलय–चन्दनतरुः परशुप्रहतः स्रवेत् पूयम्॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>अपमानितः अपि कुलजः स्वभाव–दाक्षिण्यात् परुषं न वदति। मलय–चन्दनतरुः परशुप्रहतः पूयम् न हि स्रवेत्॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>अपमानितः अपि = पराभूतः; even when insulted;<br> कुलजः = सत्कुले उत्पन्नः; one born in a noble family;<br> स्वभाव–दाक्षिण्यात् = प्रकृतिसिद्ध-लब्ध-अनुकूलता-गुणवशात्; because of natural-born politeness;<br> परुषं = मनःपीडाकरवचनं, निष्ठुरवाक्यं; hurting [words];<br> न वदति = न ब्रवीति; does not speak;<br> मलय–चन्दनतरुः = मलयनामके पर्वते स्थितःवृक्षविशेषः; Sandal-wood tree on Malaya mountain;<br> परशुप्रहतः = कुठारेण आहतः, ताडितः; hit with axe;<br> पूयम् = दुर्गन्धं; filthy smell;<br> न हि = नैव; not;<br> स्रवेत् = निःसारयेत्, दद्यात्; give out, flow out</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>पराभूतः अपि सत्कुले जातः पुरुषः निष्ठुरवाक्यानि सहजसिद्धदयाभावात् न वदति । मलयगिरौ चन्दनतरुः कुठारेण आहतः अपि दुर्गन्धं न प्रसरति (सुगन्धमेव प्रसरति)॥  <br>Even when insulted, a noble-family-born person does not say hurting words, because of his innate natural politeness. The sandal tree of the Malaya mountain does not give out filthy smell [even] when cut with an axe. (It only gives out good smell.)</td>
                        </tr>
                        <tr class="prasnaa">
                            <td style="width: 90px">प्रश्नाः </td>
                            <td>१.कः कदा परुषं न वदति?  <br>२.सः कुतः परुषं न वदति?   ३चन्दनतरुः कुत्र वर्तते?   <br>४.चन्दनतरुः कदा किं न स्रवेत्?   <br>५.‘परशुप्रहतः’ इत्यत्र समासविग्रहं वदत? <br>६.‘कुलजः’ इति शब्दस्य पदविश्लेषणं वदत?</td>
                        </tr>
                        

                    </table>
                </div>
                    
                <div id="123" class="total">
                    <div>
                        <button id="moolamsmall123" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('moolam', '123')">मूलम्</button>
                        <button id="padasmall123" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '123')">पदविभागः</button>
                        <button id="anvayasmall123" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '123')">अन्वयः</button>
                        <button id="pratismall123" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '123')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall123" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '123')">तात्पर्यम्</button>
                        <button id="vyakyaasmall123" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('vyakyaa', '123')">वाक्याभ्यासः</button>
                        <button id="prasnaasmall123" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prasnaa', '123')">प्रश्नाः</button>
                    </div>
                    <div class="title">
                        123.आशाया कृतदासो 
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम् </td>
                            <td>आशाया कृतदासो यः स दासः सर्वदेहिनां ।<br> आशा दासीकृता येन तस्य दासायते जगत् ॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>आशाया कृतदासः यः सः दासः सर्वदेहिनां । आशा दासीकृता येन तस्य दासायते जगत् ॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>आशाया कृतदासः यः सः सर्वदेहिनां दासः। आशा दासीकृता येन तस्य जगत् दासायते ॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>आशाया = दीर्घाकाङ्क्षा, आयता तृष्णा; by greed;<br> कृतदासः = भृत्यः कारितः; rendered servant, made slave, enslaved;<br> यः = यः पुंसः; one who;<br> सः = सः पुरुषः; he;<br> सर्वदेहिनां = समस्तप्राणिनां; of all people, beings;<br> दासः = भृत्यः, सेवकः; slave;<br> येन = येन नरेण; by whom;<br> तस्य = तस्य जनस्य; his, of that one;<br> जगत् = संसारः, लोकः; world;<br> दासायते = दासो भवति; becomes a slave</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>यः पुरुषः अधिकतृष्णां करोति, सः (तृष्णाशान्तये सर्वेभ्यः जीवेभ्यः यत्किञ्चित् वाञ्छति। अतः) सर्वेषां जीवानां दासवत् जीवति। यः दीर्घाकाङ्क्षान् जहाति, सः (कस्यापि दासो न भवति, प्रत्युत) समस्तं जगत् तस्यैव दासो भवति (यतः सः कस्मादपि किमपि नाकाङ्क्षति।) जो आशा के दास हैं, वे पूरे लोक के दास होते हैं। आशा जिनकी दासी होती है, पूरा लोक उनका दास के समान होता है।  ఆశకు దాసులైనవారు లోకానికంతటికీ దాసులు. ఆశ ఎవరికి దాసురాలో, వారికి లోకమంతా దాసత్వం చేస్తుంది.  <br>Those who are under bondage of expectation are the bond-servants of the whole world. But to those whose slave is the expectation, the world is like a bond-servant.  One who is made slave of greed, becomes a slave of all beings. [But] to that who has enslaved the greed, the whole world becomes a slave.</td>
                        </tr>
                        <tr class="prasnaa">
                            <td style="width: 90px">प्रश्नाः </td>
                            <td>१.कः सर्वदेहिनां दासः? <br>२.आशया दासीकृतस्य किं भवति? <br>३.तस्य ------ जगत्। (रिक्तस्थानं पूरयत।)?  <br>४.‘दासायते’ इत्यस्य पदविश्लेषणं वदत?</td>
                        </tr>
                        

                    </table>
                </div>
                    
                <div id="124" class="total">
                    <div>
                        <button id="moolamsmall124" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('moolam', '124')">मूलम्</button>
                        <button id="padasmall124" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '124')">पदविभागः</button>
                        <button id="anvayasmall124" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '124')">अन्वयः</button>
                        <button id="pratismall124" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '124')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall124" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '124')">तात्पर्यम्</button>
                        <button id="vyakyaasmall124" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('vyakyaa', '124')">वाक्याभ्यासः</button>
                        <button id="prasnaasmall124" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prasnaa', '124')">प्रश्नाः</button>
                    </div>
                    <div class="title">
                        124.खलः करोति दुर्वृत्तं
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम् </td>
                            <td>खलः करोति दुर्वृत्तं नूनं फलति साधुषु ।<br> दशाननोऽहरत् सीतां बन्धनं तु महोदधेः ॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>खलः करोति दुर्वृत्तं नूनं फलति साधुषु । दशाननः अहरत् सीतां बन्धनं तु महा-उदधेः ॥ </td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>खलः दुर्वृत्तं करोति । नूनं साधुषु फलति । दशाननः सीतां अहरत् । महोदधेः तु बन्धनम् (अभवत्)॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>खलः = दुर्जनः; wicked man;<br> दुर्वृत्तं = दुष्कृतं, दुष्टाचरणं; bad deed;<br> करोति = आचरति; does;<br> नूनं = अवश्यम्; certainly, assuredly, surely, verily, indeed;<br> साधुषु = सज्जनेषु; upon good men;<br> फलति = फलितो भवति, प्रभावो पतति; bears fruit;<br> दशाननः = दशकण्ठः, दशग्रीवः, रावणः; the ten-faced demon (Rāvaṇa);<br> सीतां = जानकीं, रामपत्नीम्; Sita (obj.);<br> अहरत् = अपहरणम् अकरोत्; stole;<br> महोदधेः तु = समुद्रस्य तु; of the great ocean;<br> बन्धनं = (अत्र) सेतुनिर्माणं; confinement, (lit. binding);<br> </td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>दुर्जनः दुष्टं कार्यमाचरति, तत्फलं सज्जनेषु आपतति। रावणः सीतां अपाहरत्, किन्तु बन्धनं समुद्रस्य अभवत्। (रामः सीताप्राप्तये लङ्कां गन्तुं समुद्रे सेतुं निर्मितवान्।)  <br>The wicked one does bad things and they show up upon noble men. Ravana had taken away Sita and the ocean had to be confined. (Rama built bridge across the ocean to reach Ravana’s place, to get back Sita.)</td>
                        </tr>
                        <tr class="prasnaa">
                            <td style="width: 90px">प्रश्नाः </td>
                            <td>१.खलः किं करोति? <br>२.साधुषु किं फलति? <br>३.बन्धनं कस्य कुतः अभवत्? <br>४.‘दुर्वृत्तं’ इत्यस्य कोऽर्थः?  <br>५.‘महोदधेः’ इत्यत्र सन्धिः विभज्यताम्? <br>६.‘फलति साधुषु’ इत्यत्र कथं सप्तमीविभक्तिः?</td>
                        </tr>
                        

                    </table>
                </div>
                    
                <div id="125" class="total">
                    <div>
                        <button id="moolamsmall125" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('moolam', '125')">मूलम्</button>
                        <button id="padasmall125" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '125')">पदविभागः</button>
                        <button id="anvayasmall125" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '125')">अन्वयः</button>
                        <button id="pratismall125" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '125')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall125" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '125')">तात्पर्यम्</button>
                        <button id="vyakyaasmall125" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('vyakyaa', '125')">वाक्याभ्यासः</button>
                        <button id="prasnaasmall125" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prasnaa', '125')">प्रश्नाः</button>
                    </div>
                    <div class="title">
                        125.अर्थनाशं मनस्तापं
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम् </td>
                            <td>अर्थनाशं मनस्तापं गृहे दुश्चरितानि च ।<br> (पाठ. गृहिणीचरितानि च) वञ्चनं चापमानं च मतिमान्न प्रकाशयेत् ॥ -चाणक्यनीतिः</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>अर्थनाशं मनस्तापं गृहे दुश्चरितानि च । वञ्चनं च अपमानं च मतिमान् न प्रकाशयेत् । </td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>मतिमान् अर्थनाशं, मनस्तापं, गृहे दुश्चरितानि च, वञ्चनं च, अपमानं च- न प्रकाशयेत् । </td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>मतिमान् = विवेकवान्; wise person, intelligent one;<br> अर्थनाशं = धनहानिं; loss of money;<br> मनस्तापं = हृदयपीडां; mental agony, inner pain;<br> गृहे = गेहे; at home;<br> दुश्चरितानि च = दुष्टानि आचरितानि; bad characters, wrong behaviour (of home-mates);<br> वञ्चनं च = प्रतारणं, छलः; deceit, fraud, deception;<br> अपमानं च = पराभवः; insult, dishonour;<br> न प्रकाशयेत् = न बहिः प्रकटयेत्; should not disclose;<br> (पाठ. गृहिणीचरितानि = पत्न्याः सम्बन्धिविषयाः = character aspects of one’s wife)</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>विचारशीलः नरः स्वसम्बद्धविषयानां प्रस्तुतिम् अन्येषां समक्षे न कुर्यात् । एतान् रहसि स्थापयेत्– आर्थिकहानिः, हृदयपीडा, गेहे स्थितानां सदस्यानां दुष्टानि आचरितानि, (अन्यैः स्वस्मिन् कृतं) कपटं, अनादरः च।  <br>Wise man should never disclose [the following things]– monitory loss, inner pain, having bad things/people/events within the household, being cheated and being humiliated.</td>
                        </tr>
                        <tr class="prasnaa">
                            <td style="width: 90px">प्रश्नाः </td>
                            <td>१.अर्थनाशो नाम किम्?  <br>२.मतिमान् किं न कुर्यात्?   <br>३.------ प्रकाशयेत्। (रिक्तस्थानं पूरयत।)?  <br>४.‘प्रकाशयेत्’ इत्यस्य पदविश्लेषणं वदत? <br>५.‘मनस्तापं’ कः सन्धिरिति विस्तरं वदत।</td>
                        </tr>
                        

                    </table>
                </div>
                    
                <div id="126" class="total">
                    <div>
                        <button id="moolamsmall126" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('moolam', '126')">मूलम्</button>
                        <button id="padasmall126" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '126')">पदविभागः</button>
                        <button id="anvayasmall126" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '126')">अन्वयः</button>
                        <button id="pratismall126" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '126')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall126" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '126')">तात्पर्यम्</button>
                        <button id="vyakyaasmall126" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('vyakyaa', '126')">वाक्याभ्यासः</button>
                        <button id="prasnaasmall126" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prasnaa', '126')">प्रश्नाः</button>
                    </div>
                    <div class="title">
                        126.गर्वाय परपीडायै 
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम् </td>
                            <td>गर्वाय परपीडायै दुर्जनस्य धनं बलम्।<br> सुजनस्य तु दानाय रक्षणाय च ते सदा॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>गर्वाय परपीडायै दुर्जनस्य धनं बलम्। सुजनस्य तु दानाय रक्षणाय च ते सदा॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>दुर्जनस्य धनं गर्वाय बलम् परपीडायै (च भवतः)। सुजनस्य तु सदा (धनं) दानाय (बलं परेषां) रक्षणाय च ते (भवतः) ॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>गर्वाय = औद्धत्याय, अहङ्काराय, मदाय, अभिमानाय; for arrogance;<br> परपीडायै = अन्येषां बाधनाय; for harming, paining others;<br> दुर्जनस्य = दुष्टपुरुषस्य; of the wicked;<br> धनं = वित्तं; money;<br> बलम् = शक्तिः; power, strength;<br> सुजनस्य तु = सज्जनस्य, सत्पुरुषस्य; of good one;<br> दानाय = अर्थवितरणाय; for charity;<br> रक्षणाय च = पालनाय; for protecting;<br> ते = एते; these two;<br> सदा = सर्वकालेषु; always</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>दुष्टपुरुषस्य वित्तं सदा अहङ्काराय भवति। तस्य बलम् अन्येषां बाधनाय उपयुज्यते। सज्जनानाम् अर्थः (निर्धनेभ्यः) वितरणाय, शक्तिस्तु अन्येषां पालनाय उपयुज्यते (इति तयोः भेदः)। <br>Wicked one’s money and strength are for arrogance, and harming of others [respectively]. [But] those two of a good man are always [used] for giving to others and for protection.</td>
                        </tr>
                        <tr class="prasnaa">
                            <td style="width: 90px">प्रश्नाः </td>
                            <td>१.दुर्जनस्य धनं किमर्थं भवति? <br>२.दुर्जनस्य बलं किमर्थं भवति? <br>३.सज्जनस्य धनं किमर्थं भवति? <br>४.सज्जनस्य बलं किमर्थं भवति?  <br>५.‘परपीडायै’ इत्यत्र समासविग्रहं वदत? <br>६.‘गर्वाय’ इत्यत्र चतुर्थीविभक्तिः कथम्?</td>
                        </tr>
                        

                    </table>
                </div>
                    
                <div id="127" class="total">
                    <div>
                        <button id="moolamsmall127" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('moolam', '127')">मूलम्</button>
                        <button id="padasmall127" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '127')">पदविभागः</button>
                        <button id="anvayasmall127" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '127')">अन्वयः</button>
                        <button id="pratismall127" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '127')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall127" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '127')">तात्पर्यम्</button>
                        <button id="vyakyaasmall127" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('vyakyaa', '127')">वाक्याभ्यासः</button>
                        <button id="prasnaasmall127" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prasnaa', '127')">प्रश्नाः</button>
                    </div>
                    <div class="title">
                        127.अक्रोधेन जयेत्
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम् </td>
                            <td>अक्रोधेन जयेत् क्रोधमसाधुं साधुना जयेत् ।<br> (पाठ. जयेत् क्रुद्धं) जयेत् कदर्यं दानेन जयेत् सत्येन चानृतम् ॥ महाभारतम्, उद्योगपर्व</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>अक्रोधेन जयेत् क्रोधम् असाधुं साधुना जयेत् । जयेत् कदर्यं दानेन जयेत् सत्येन च अनृतम् ।</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>क्रोधम्अक्रोधेन जयेत्।असाधुं साधुना जयेत् । कदर्यं दानेन जयेत्। सत्येन च अनृतम् जयेत् ।</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>क्रोधम् = चित्तस्य तीक्ष्णतां; anger;<br> अक्रोधेन = क्रोधराहित्येन, शान्त्या; by patience, lack of anger;<br> जयेत् = नियमितव्यम्; should win over;<br> असाधुं = साधुभिन्नं, असच्चरितं, दुष्टं; bad, unpleasant, wicked;<br> साधुना = उत्तमवृत्त्या; by (what is) fit, proper, right;<br> कदर्यं = क्षुद्रत्वं, कृपणभावं, धनादिदानभावकराहित्यं; avariciousness, miserliness;<br> दानेन = धनादिवितरणेन; by charity;<br> सत्येन च = तथ्येन, अवितथेन, यथार्थेन; by truth;<br> अनृतम् = सत्यभिन्नं, मिथ्यां; falsehood;<br> पाठ. क्रुद्धम् = क्रोधयुक्तं नरम्; angry person (obj.)</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>शान्तिभावेन क्रोधं, दुष्टं सज्जनतया, दानविरुद्धबुद्धिं दानकरणेन, मिथ्यां च यथार्थतत्त्वेन नियतितव्यम्।  <br>One should win over anger by patience; wicked(ness) by (what is) right(eousness); win over the miserliness by charity and falsehood by truth.</td>
                        </tr>
                        <tr class="prasnaa">
                            <td style="width: 90px">प्रश्नाः </td>
                            <td>१.क्रोधं केन जयेत्?  <br>२.कदर्यं नाम किम्?  <br>३.दानेन किं जयेत्? <br>४.सत्येन किं जयेत्?  <br>५.‘अक्रोधः’ इत्यस्य कोऽर्थः?</td>
                        </tr>
                        

                    </table>
                </div>
                    
                <div id="128" class="total">
                    <div>
                        <button id="moolamsmall128" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('moolam', '128')">मूलम्</button>
                        <button id="padasmall128" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '128')">पदविभागः</button>
                        <button id="anvayasmall128" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '128')">अन्वयः</button>
                        <button id="pratismall128" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '128')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall128" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '128')">तात्पर्यम्</button>
                        <button id="vyakyaasmall128" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('vyakyaa', '128')">वाक्याभ्यासः</button>
                        <button id="prasnaasmall128" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prasnaa', '128')">प्रश्नाः</button>
                    </div>
                    <div class="title">
                        128.वित्तमेव कलौ नॄणां 
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम् </td>
                            <td>वित्तमेव कलौ नॄणां जन्माचारगुणोदयः ।<br> धर्मन्यायव्यवस्थायां कारणं बलमेव हि ॥ भागवतम् १२.२.२</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>वित्तम् एव कलौ नॄणां जन्म-आचार-गुण-उदयः । धर्म-न्याय-व्यवस्थायां कारणं बलम् एव हि ।</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>कलौ वित्तम् एव नॄणां जन्म-आचार-गुण-उदयः, बलं धर्म-न्याय-व्यवस्थायां कारणं एव हि (भवति)।</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>कलौ = कलियुगे; in age of kali;<br> वित्तम् एव = धनम् एव; money alone;<br> नॄणां = मनुष्याणां; of men;<br> जन्म-आचार-गुण-उदयः = उत्पत्तौ, चरित्रे, गुणे च उदयकारणम्; cause for rise in birth, conduct and qualities;<br> बलम् = शक्तिः; strength;<br> धर्म-न्याय-व्यवस्थायां = धर्म(कर्तव्य/आचार)-व्यवस्थितौ, नीति-व्यवस्थितौ च; in the institution of dharma (here, duty) and law;<br> कारणं = हेतुः, बीजम्; cause;<br> एव हि = तथैव, तथ्यम्; alone</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>कलियुगे धनमेव मनुष्याणां जन्मनि, चरित्रे, गुणे च उन्नतेः कारणं भवति। कर्तव्याचारादिव्यवस्थितौ शक्तिः एव हेतुः भवति । [धनस्य बलस्य च प्रामुख्यमत्रोच्यते। तत्सामान्यस्थितिरत्र वर्ण्यते। किन्तु धनस्य बलस्य उन्नतिकारणत्वादपि न केनचित् तद् अन्यायमार्गेण, अधर्ममार्गेण वा न लब्धव्यम्। अन्याय्यस्य फलं तु पापं सदा यस्मिन् कस्मिन्नपि युगे तथ्येन भवतीति स्मरणीयम्।] <br>In age of Kali, wealth becomes the main reason for rise of people in (terms of) birth, conduct and qualities; and strength is indeed the main reason in the institutions of dharma and nyAya.[Importance of money and strength is stated. This shloka only states the condition typical to the age. But it does not mean one should earn it by wrong means. And then, one should always remember that, though importance for money is established in every age, but adopting wrong means will always have its fruit as sin.]</td>
                        </tr>
                        <tr class="prasnaa">
                            <td style="width: 90px">प्रश्नाः </td>
                            <td>१.नॄणां वित्तं कलौ किं भवति? <br>२.वित्तं कुत्र बलं भवति?  <br>३.‘जन्माचारगुणोदयः’ इत्यत्र समासविग्रहं वदत?  <br>४.‘धर्मन्यायव्यवस्थायां’ इत्यत्र समासविग्रहं वदत?  <br>५.‘नॄणां’ इति पदं विश्लेषयत।</td>
                        </tr>
                        

                    </table>
                </div>
                    
                <div id="129" class="total">
                    <div>
                        <button id="moolamsmall129" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('moolam', '129')">मूलम्</button>
                        <button id="padasmall129" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '129')">पदविभागः</button>
                        <button id="anvayasmall129" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '129')">अन्वयः</button>
                        <button id="pratismall129" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '129')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall129" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '129')">तात्पर्यम्</button>
                        <button id="vyakyaasmall129" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('vyakyaa', '129')">वाक्याभ्यासः</button>
                        <button id="prasnaasmall129" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prasnaa', '129')">प्रश्नाः</button>
                    </div>
                    <div class="title">
                        129.रत्नाकरः किं कुरुते 
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम् </td>
                            <td>रत्नाकरः किं कुरुते स्वरत्नैः विन्ध्याचलः किं करिभिः करोति ।<br> श्रीखण्डखण्डैः मलयाचलः किं परोपकाराय सतां विभूतयः ॥-सुभाषितरत्नभाण्डागारः </td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>रत्नाकरः किं कुरुते स्वरत्नैः विन्ध्याचलः किं करिभिः करोति । श्रीखण्डखण्डैः मलयाचलः किं परोपकाराय सतां विभूतयः । </td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>रत्नाकरः स्वरत्नैः किं कुरुते ? विन्ध्याचलः करिभिः किं करोति ? मलयाचलः श्रीखण्डखण्डैः किं (करोति ?) सतां विभूतयः परोपकाराय (भवन्ति)। </td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>रत्नाकरः = समुद्रः; ocean;<br> स्वरत्नैः = स्वस्य अमूल्यमणिभिः; with gems;<br> किं कुरुते = किं प्रयोजनं निर्वहति; what does it do?;<br> विन्ध्याचलः = तन्नामविशिष्टः पर्वतः; the mountain of vindhya;<br> करिभिः = गजैः; with elephants;<br> किं करोति = किं कार्यं साध्नोति; what does it do?;<br> मलयाचलः = तन्नामविशिष्टः पर्वतः; mountain of malaya;<br> श्रीखण्डखण्डैः = चन्दनशकलैः; with sandal wood pieces;<br> सतां = सज्जनानां, उत्तमपुरुषाणां; of noble people;<br> विभूतयः = ऐश्वर्याणि; wealth, riches;<br> परोपकाराय = अन्येषां साहाय्यार्थं; for helping others</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>उदधिः (स्वस्मिन् स्थितैः) रत्नैः किं करोति ? (स्वार्थाय नोपयुङ्क्ते)। विन्ध्याचलः गजैः किमपि प्रयोजनं न साधयति। मलयपर्वताय स्वस्य चन्दनस्य न कोऽपि उपयोगः। उत्तमानां ऐश्वर्याणि अन्येषां प्रयोजनायैव भवन्ति। <br>What does ocean do with its gems? What does Vindhya mountain do with its elephants? What use does Malaya mountain have of sandalwood pieces? The riches of noble people are for helping others.</td>
                        </tr>
                        <tr class="prasnaa">
                            <td style="width: 90px">प्रश्नाः </td>
                            <td>१.कः स्वरत्नैः किं कुरुते? <br>२.कःकरिभिः किं करोति? <br>३.मलयाचलस्य इत्यत्र समासविग्रहं वदत? <br>४.‘श्रीखण्डखण्डैः’ इत्यत्र समासविग्रहं वदत? <br>५.सतां विभूतयः किमर्थं भवन्ति?</td>
                        </tr>
                        

                    </table>
                </div>
                    
                <div id="130" class="total">
                    <div>
                        <button id="moolamsmall130" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('moolam', '130')">मूलम्</button>
                        <button id="padasmall130" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '130')">पदविभागः</button>
                        <button id="anvayasmall130" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '130')">अन्वयः</button>
                        <button id="pratismall130" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '130')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall130" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '130')">तात्पर्यम्</button>
                        <button id="vyakyaasmall130" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('vyakyaa', '130')">वाक्याभ्यासः</button>
                        <button id="prasnaasmall130" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prasnaa', '130')">प्रश्नाः</button>
                    </div>
                    <div class="title">
                        130.सतां हि दर्शनं 
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम् </td>
                            <td>सतां हि दर्शनं पुण्यं तीर्थभूताश्च सज्जनाः।<br> कालेन फलते तीर्थं सद्यः सज्जनसङ्गतिः॥</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>सतां हि दर्शनं पुण्यं तीर्थभूताः च सज्जनाः। कालेन फलते तीर्थं सद्यः सज्जन–सङ्गतिः॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>सतां हि दर्शनं पुण्यं तीर्थभूताः च सज्जनाः। कालेन तीर्थं फलते सज्जन–सङ्गतिः सद्यः (फलति)॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>सतां हि = सज्जनानां, उत्तमजनानां; of the saints;<br> दर्शनं = अभ्युपगमनं, समीपं गमनं; (here) visiting (lit. seeing);<br> पुण्यं = पुण्यकरं, शुभादृष्टं, सुकृतं, श्रेयः; meritorious;<br> तीर्थभूताः च = पुण्यस्थल-सदृशाः; like a pilgrimage;<br> सज्जनाः = सन्तः पुरुषाः, उत्तमजनाः; saintly people;<br> कालेन = कञ्चित् कालानन्तरं; in time (here- after some time);<br> तीर्थम् = पुण्यस्थानं; pilgrimage;<br> फलते = लाभं करोति; is fruitful (अपाणिनीयप्रयोगः, फल इति परस्मैपदी);<br> सज्जन–सङ्गतिः = साधुजनानां संयोगः; meeting/ company of saints;<br> सद्यः = सपदि, तत्क्षणं; immediately</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>साधुजनानां दर्शनं सुकृतिकरं भवति। सज्जनाः पुण्यक्षेत्रसदृशाः भवन्ति। पुण्यक्षेत्रसन्दर्शनेन फलं चिरेण लभ्यते। साधुसमागमस्तु सपदि फलं यच्छति। <br>Visiting the noble is by itself holy; since they are the source of pious and sacred knowledge. While the other 'tirthas' or holy places give their effects after some time, acquaintance with the good and righteous pays off immediately.</td>
                        </tr>
                        <tr class="prasnaa">
                            <td style="width: 90px">प्रश्नाः </td>
                            <td>१.केषां दर्शनं पुण्यम्?  <br>२.सज्जनाः कीदृशाः?  <br>३.तीर्थं कदा फलति? सद्यः किं फलति? <br>४.‘तीर्थभूताः’ इत्यत्र समासविग्रहं वदत? <br>५.‘सज्जनसङ्गतिः’ इत्यत्र समासविग्रहं वदत? <br>६.साधुसमागमेन को लाभः? (स्वशब्दैः वर्णयत।)</td>
                        </tr>
                        

                    </table>
                </div>
                    
                <div id="131" class="total">
                    <div>
                        <button id="moolamsmall131" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('moolam', '131')">मूलम्</button>
                        <button id="padasmall131" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '131')">पदविभागः</button>
                        <button id="anvayasmall131" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '131')">अन्वयः</button>
                        <button id="pratismall131" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '131')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall131" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '131')">तात्पर्यम्</button>
                        <button id="vyakyaasmall131" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('vyakyaa', '131')">वाक्याभ्यासः</button>
                        <button id="prasnaasmall131" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prasnaa', '131')">प्रश्नाः</button>
                    </div>
                    <div class="title">
                        131.ददाति प्रतिगृह्णाति
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम् </td>
                            <td>ददाति प्रतिगृह्णाति गुह्यमाख्याति पृच्छति ।<br> भुङ्क्ते भोजयते चैव षड्विधं प्रीतिलक्षणम् ॥ -पञ्चतन्त्रम्, मित्रसंप्राप्तिः</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td></td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>ददाति प्रतिगृह्णाति गुह्यम् आख्याति पृच्छति भुङ्क्ते भोजयते च एव (इति) षड्विधं प्रीतिलक्षणम् ।</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>ददाति = वस्तु अन्यस्य आयत्तं करोति, अन्यस्मै अर्पयति; gives;<br> प्रतिगृह्णाति = स्वीकरोति, अन्यस्य वस्तु स्वायत्तीकरोति; receives (something in return);<br> गुह्यम् = रहस्यं, निगूढविषयं; secret (hidden feelings);<br> आख्याति = वदति, भाषते; speaks;<br> पृच्छति = ज्ञातुकामो भूत्वा प्रश्नं करोति; asks, inquires;<br> भुङ्क्ते = खादति; eats (along with);<br> भोजयते = अन्नं खादयति, भोक्तुं अन्नं ददाति; feeds, offers food to eat;<br> च एव = अपि च; also;<br> षड्विधं = षट्-प्रकारकं; six kinds;<br> प्रीतिलक्षणम् = मैत्रीभावस्य चिह्नं; characteristic of friendship</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>(वस्तूनाम्) अर्पणं, (यदि किञ्चित् दीयते तर्हि) स्वीकरणं, रहस्यविषयस्य (स्वयं) भाषणं, (मित्रं रहःसम्बन्धि)प्रश्नकरणं, (मित्रगृहे स्वयं) भोजनस्य स्वीकृतिः, (मित्राय) भोजनदानं– इति षट्प्रकारकं लक्षणं मित्रतायाः वर्तते। <br>Giving (things), accepting (something in return), sharing secrets, asking (private questions), dines (along) and (invites to) offer food– these are the six signs of friendship.</td>
                        </tr>
                        <tr class="prasnaa">
                            <td style="width: 90px">प्रश्नाः </td>
                            <td>१.अस्मिन् श्लोके कस्य लक्षणमुच्यते?  <br>२.कति विधं तल्लक्षणम्?  <br>३.‘दानं’ नाम किम्?  <br>४.‘गुह्यम् आख्याति’ इत्यस्य कोऽर्थः?  <br>५.‘प्रीतिलक्षणम्’ इत्यत्र समासविग्रहं वदत?</td>
                        </tr>
                        

                    </table>
                </div>
                    
                <div id="132" class="total">
                    <div>
                        <button id="moolamsmall132" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('moolam', '132')">मूलम्</button>
                        <button id="padasmall132" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('pada', '132')">पदविभागः</button>
                        <button id="anvayasmall132" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('anvaya', '132')">अन्वयः</button>
                        <button id="pratismall132" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prati', '132')">प्रतिपदार्थः</button>
                        <button id="taatparyamsmall132" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('taatparyam', '132')">तात्पर्यम्</button>
                        <button id="vyakyaasmall132" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('vyakyaa', '132')">वाक्याभ्यासः</button>
                        <button id="prasnaasmall132" class="mini-btn" style="margin:0.2em" onclick="toggleOneSloka('prasnaa', '132')">प्रश्नाः</button>
                    </div>
                    <div class="title">
                        132.प्रकीर्णे विषयारण्ये
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम् </td>
                            <td>प्रकीर्णे विषयारण्ये धावन्तं विप्रमाथिनम् ।<br> ज्ञानाङ्कुशेन कुर्वीत वश्यमिन्द्रियदन्तिनम् ॥ –सुभाषितसुधानिधिः</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>प्रकीर्णे विषय-अरण्ये धावन्तं विप्रमाथिनम् । ज्ञान-अङ्कुशेन कुर्वीत वश्यम् इन्द्रिय-दन्तिनम् । </td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>प्रकीर्णे विषयारण्ये विप्रमाथिनम् धावन्तं इन्द्रियदन्तिनं ज्ञानाङ्कुशेन वश्यं कुर्वीत । </td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>प्रकीर्णे = विच्छिन्ने, विक्षिप्ते; confused, agitated, disordered;<br> विषयारण्ये = (विषयः = चक्षुरादिग्राह्य-भोगसाधनं) विषयाणां वने (आलङ्कारिकं); in the forest of objects of senses (in the material world (fig.));<br> विप्रमाथिनं = पीडनकर्तारम्, मारणकर्तारम्, प्रमथनशीलं, देहेन्द्रिय-क्षोभकं; (obj.) That which is tormenting, harassing, torturing, afflicting, harrowing;<br> धावन्तं = अतिवेगेन प्लवन्तं, प्रद्रवन्तं; that which is running (obj.);<br> इन्द्रियदन्तिनं = (इन्द्रियं = ज्ञानकर्मसाधनं) इन्द्रियगजं (आलङ्कारिकं); the elephant of senses (fig.);<br> ज्ञानाङ्कुशेन = अवबोध-नामकेन अस्त्रेण (आलङ्कारिकं) (अङ्कुशः = हस्त्यादि-चालनार्थकं लोहमय-वक्राग्रं अस्त्रं); by the goad of knowledge (fig.);<br> वश्यं = स्वस्य आयत्तं, स्वनियतं; submission, control;<br> कुर्वीत = कुर्यात्; should do, should make it happen</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>चक्षुरादीन्द्रियं नाम गजः, यः विक्षिप्ते (चक्षुरादिग्राह्याणां) विषयाणां वने क्षोभकारको भूत्वा (अनियतः) धावति, तं गजं अवबोधनाम्ना अङ्कुशेन स्वनियतं कुर्यात्। <br>The elephant named ‘sense’ (‘indriya’ common name for ten senses) that is running uncontrolled in the forest of sensory objects, should be subdued by the goad of knowledge.</td>
                        </tr>
                        <tr class="prasnaa">
                            <td style="width: 90px">प्रश्नाः </td>
                            <td>१.इन्द्रियदन्ती कुत्र धावति?  <br>२.सः किंविधो भवति? <br>३.तं कथं वश्यं कुर्यात्?  <br>४.‘विषयारण्ये’ इत्यत्र समासविग्रहं वदत? <br>५.‘विप्रमाथिनम्’ इति शब्दस्य व्युत्पत्तिं कथयत। <br>६.‘ज्ञानांकुशेन’ इत्यत्र समासविग्रहं वदत?</td>
                        </tr>
                        

                    </table>
                </div>
                    
                <div id="133" class="total">
                    <div>
