                    </div>
                    <div class="title">
                        133.अहो साहजिकं प्रेम
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम् </td>
                            <td>अहो साहजिकं प्रेम दूरादपि विराजते ।<br> चकोरनयनद्वन्द्वमाह्लादयति चन्द्रमाः ॥ –सुभाषितरत्नभाण्डागारः</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>अहो साहजिकं प्रेम दूराद् अपि विराजते । चकोर-नयन-द्वन्द्वम् आह्लादयति चन्द्रमाः ॥ </td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>अहो,दूराद् अपि साहजिकं प्रेम विराजते । (अत्रोदारहरणम्-) चन्द्रमाः चकोर–नयन–द्वन्द्वम् आह्लादयति ॥ </td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>अहो = अहो; Oh;<br> दूराद् अपि = दूरे स्थित अपि; from far away;<br> साहजिकं = अकृतकं; natural;<br> प्रेम = प्रणयः; love;<br> विराजते = विलसति; hails;<br> चन्द्रमाः = चन्द्रः; moon;<br> चकोर–नयन–द्वन्द्वम् = चकोरपक्षिणः अक्षिद्वयं; two eyes of the bird Cakora;<br> आह्लादयति = आनन्दयति; delights</td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>(यः) अकृतकप्रणयः (तस्य लक्षणमेवं यथा, सः) दूरे स्थितोऽपि विलसति। (अस्योदाहरणं यथा) (बहुदूरे स्थितः) चन्द्रः चकोरपक्षिणः अक्षिद्वयं आनन्दयति। <br>Oh, the natural (inborn) love shines (keeps existing) even from long distance. The moon delights the pair of eyes of the Cakora bird.</td>
                        </tr>
                        <tr class="prasnaa">
                            <td style="width: 90px">प्रश्नाः </td>
                            <td>१.साहजिकप्रेम्णः को विशेषः? <br>२.चन्द्रमाः किमाह्लादयति?  <br>३.चन्द्रमाः-चकोरयोः उदाहरणेन किं ज्ञायते? <br>४.‘साहजिकं’ शब्दस्य पदविश्लेषणं वदत? <br>५.‘चकोरनयनद्वन्द्वम्’ इत्यत्र समासविग्रहं वदत?  <br>६.‘आह्लादयति’ इत्यत्र को धातुः, क उपसर्गः, कश्च प्रत्ययः?</td>
                        </tr>
                        

                    </table>
                </div>
                    
