                    </div>
                    <div class="title">
                        134.चित्तमिन्द्रियसेनाया 
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम् </td>
                            <td>चित्तमिन्द्रियसेनाया नायकस्तज्जयाज्जयः।<br> उपानद्गूढपादस्य ननु चर्मावृतैव भूः॥ --सुभाषितावलिः ३.३४७</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>चित्तम् इन्द्रिय-सेनायाः नायकः तत्-जयात् जयः। उपानद्-गूढपादस्य ननु चर्म-आवृता एव भूः॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>इन्द्रियसेनायाः नायकः चित्तम् । तत्-जयात् जयः। उपानद्-गूढपादस्य भूः चर्मावृता एव ननु ॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td>इन्द्रिय-सेनायाः = ज्ञानकर्मसाधनानां सैन्यस्य; नायकः = अधिपतिः;<br> चित्तम् = मनः; तत्-जयात् = तस्य उपरि जयं प्राप्य, तं पराजित्य;<br> जयः = वस्तुतः विजयः; उपानद्-गूढपादस्य = यस्य चरणौ पादरक्षाभ्यां रक्षितौ तस्य, पादरक्षाधारिणः;<br> भूः = भूमिः; चर्मावृता एव ननु = छादन्या आच्छन्ना किल;<br> </td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>मनः इन्द्रियसैनिकाणाम्नियन्त्रकः इव अस्ति। तस्मिन् जयप्रात्पिरेव विजयः इति कथ्यते। (इन्द्रियाणामुपरि जयप्राप्त्या कोऽपि लाभः नास्ति।) यस्य अङ्घ्रिद्वयं पादत्राणाभ्याम् अवितं, तस्मै धरा कृत्त्याआच्छादिता इव भवति। इन्द्रियों की सेना का नायक चित्त है। उसके जीतने से जीत है। चप्पल से पैर को ढकने से सारी भूमि पर चर्म की बिछाव के समान ही तो है।  ఇంద్రియాలనేసేనకునాయకుడుమనసు. దానిపైవిజయమే (నిజమైన) జయం. చెప్పులువేసుకున్నపాదాలకుభూమిఅంతాతోలు (తివాచీ) కప్పినట్టేకదా. <br>Mind is the head of the army of the sense organs. (Real) victory is (achieved) from winning it over. The earth is as if covered by hide, to the one who wears shoes.</td>
                        </tr>
                        <tr class="prasnaa">
                            <td style="width: 90px">प्रश्नाः </td>
                            <td>१.चित्तं कस्य नायकः? <br>२.कस्य भूः चर्मावृतेव? <br>३.नायकस्तज्जयाज्जयः इत्यत्र कः सन्धिः? <br>४.‘इन्द्रियसेनायाः’ इत्यत्र समासः कः?  <br>५.‘उपानद्गूढपादस्य’इत्यत्र समासः कः?</td>
                        </tr>
                        

                    </table>
                </div>
                    
