                    <div class="title">
                        135.कन्दुको भित्तिनिक्षिप्त
                    </div>
                    <table>
                        <tr class="moolam">
                            <td style="width: 90px">मूलम् </td>
                            <td>कन्दुको भित्तिनिक्षिप्त इव प्रतिफलन्मुहुः ।<br> आपतत्यात्मनि प्रायो दोषोऽन्यस्य चिकीर्षतः ॥ --कथासरित्सागरः (३.६.२१३)</td>
                        </tr>
                        <tr class="pada">
                            <td style="width: 90px">पदविभागः </td>
                            <td>कन्दुकः भित्ति-निक्षिप्तः इव प्रतिफलन् मुहुः । आपतति आत्मनि प्रायः दोषः अन्यस्य चिकीर्षतः ॥</td>
                        </tr>
                        <tr class="anvaya">
                            <td style="width: 90px">अन्वयः </td>
                            <td>कन्दुकः भित्तिनिक्षिप्तः मुहुः प्रतिफलन् इव, प्रायः अन्यस्य चिकीर्षतः दोषः आत्मनि आपतति ॥</td>
                        </tr>
                        <tr class="prati">
                            <td style="width: 90px">प्रतिपदार्थः </td>
                            <td></td>
                        </tr>
                        <tr class="taatparyam">
                            <td style="width: 90px">तात्पर्यम् </td>
                            <td>दीवार पर फेंका हुआ गेंद जिसप्रकार झट से उल्टा (फेंकने वाले की ओर) आजाता है, उसी प्रकार दूसरे के प्रति दोष आचरण करना चाहें, तो वह हमारे ही पर आगिरता है।  గోడమీదకుకొట్టినబంతివెంటనేతిరిగివచ్చినట్టు, ఇతరులకుచెడుచేద్దామంటేఅదిమనమీదకేవచ్చిపడుతుంది. <br>A ball thrown on a wall bounces back immediately. Similarly, the faults desired to be done for others often fall upon the self.</td>
                        </tr>
                        <tr class="prasnaa">
                            <td style="width: 90px">प्रश्नाः </td>
                            <td></td>
                        </tr>
                        

                    </table>
